-- EldoUI's texts in Danish (daDK): the core: options window, installer, layouts, move mode, profiles, saved data and chat messages.
-- English is the key; a text missing here shows in English. Written by the
-- EldoUI authors in natural Danish: game terms players use (quest, loot, raid,
-- tank, cooldown) stay English with Danish grammar, names stay as the game shows
-- them. Keep every %s, %d, {token} and |c...|r code exactly as it is.
-- This folder loads only when Dansk is picked under General > EldoUI language,
-- and the table is built then. It is its own addon, so EldoUI comes from its global.
local E = EldoUI
if not E then return end
-- Danish is complete: General > EldoUI language offers it.
E.completeLanguages = E.completeLanguages or {}
E.completeLanguages.daDK = true
-- Danish writes decimals with a comma: 1,2 tusind, 0,40 til 1,20.
E.decimalCommas = E.decimalCommas or {}
E.decimalCommas.daDK = true
