	["<addon>  save another addon's setup into EldoUI (%s)"] = "<addon>  gem en anden addons opsætning i EldoUI (%s)",
	["<kind> ...  in-game checks that print what the game reports"] = "<kind> ...  tjek i spillet der udskriver hvad spillet melder",
	["<module>  same as /eui <module> off"] = "<module>  samme som /eui <module> off",
	["<module>  same as /eui <module> on"] = "<module>  samme som /eui <module> on",
	["<name> | undo  apply a layout preset, or undo the last setup change (no name lists them)"] = "<name> | undo  anvend et layoutpreset, eller fortryd den seneste opsætningsændring (uden navn vises listen)",
	["<new name>  rename the profile this character uses"] = "<new name>  omdøb den profil som denne karakter bruger",
	["<party | raid | guild | player> [all | general | positions | global | <module> | <list>]  offer settings to a group, guild or player"] = "<party | raid | guild | player> [all | general | positions | global | <module> | <list>]  tilbyd indstillinger til en gruppe, et guild eller en spiller",
	["<profile>  copy chosen modules from another profile"] = "<profile>  kopier valgte moduler fra en anden profil",
	["<words>  open the options with every setting that matches"] = "<words>  åbn indstillingerne med alle indstillinger der matcher",
	["[<profile> | none]  the profile new characters of your class start with"] = "[<profile> | none]  den profil nye karakterer af din klasse starter med",
	["[<profile>]  put this character on a profile you already set up, as it is, with its own chat tabs, game settings and class spells"] = "[<profile>]  lad denne karakter bruge en eksisterende profil uændret med sine egne chatfaner, spilindstillinger og klasseevner",
	["[<step> | undo]  run the EldoUI setup again, open one step (layout, role, modules ...) or undo the last setup"] = "[<step> | undo]  kør EldoUI-opsætningen igen, åbn ét trin (layout, role, modules ...), eller fortryd den seneste opsætning",
	["[<step>]  same as /eui install: run the EldoUI setup again"] = "[<step>]  det samme som /eui install: kør EldoUI-opsætningen igen",
	["[all | general | positions | global | <module> | <list>]  export settings as a readable Lua table"] = "[all | general | positions | global | <module> | <list>]  eksporter indstillinger som en læsbar Lua-tabel",
	["[all | general | positions | global | <module> | <list>]  export settings as a share string"] = "[all | general | positions | global | <module> | <list>]  eksporter indstillinger som en delestreng",
	["[check | keyboard | hidden]  where bags, map and the other game keys are; check your keys or your keyboard"] = "[check | keyboard | hidden]  hvor tasker, kort og spillets andre taster er; tjek dine taster eller dit tastatur",
	["[clear]  open EldoUI's error log, or empty it"] = "[clear]  åbn EldoUI's fejllog, eller tøm den",
	["[command]  this list, or how to use one command"] = "[command]  denne liste, eller hvordan du bruger én kommando",
	["[copy | force]  version, modules, restrictions and secret values; copy = for a bug report; force = test switch for combat restrictions"] = "[copy | force]  version, moduler, begrænsninger og hemmelige værdier; copy = til en fejlrapport; force = testkontakt til kampbegrænsninger",
	["[copy]  copy Blizzard's active Edit Mode layout as text, or open the import window"] = "[copy]  kopier Blizzards aktive Edit Mode-layout som tekst, eller åbn importvinduet",
	["[element] [on | off | toggle] | <element> skin | move | hide | replace | improve on | off | reset [category]  which Blizzard parts EldoUI may change"] = "[element] [on | off | toggle] | <element> skin | move | hide | replace | improve on | off | reset [category]  hvilke dele af Blizzards UI EldoUI må ændre", -- l10n: keep
	["[list | restore <part> [<name>] | follow <part> [<name>]]  your saved data's safety net: open the Saved data page, list the copies kept before updates, put one back, or let a restored part follow updates again"] = "[list | restore <part> [<name>] | follow <part> [<name>]]  sikkerhedsnettet for dine gemte data: åbn siden Gemte data, vis kopierne der er gemt før opdateringer, gendan én, eller lad en gendannet del følge opdateringerne igen", -- l10n: keep
	["[list | setup [name]]  the Plugins page; list = print them; setup = their setup pages again"] = "[list | setup [name]]  siden Plugins; list = udskriv dem; setup = vis deres opsætningssider igen",
	["[lock | unlock | reset | list]  move and scale Blizzard windows"] = "[lock | unlock | reset | list]  flyt og skaler Blizzard-vinduer",
	["[movement | strafe | numbers | mouse | esdf | restore]  keybind mode, or the preview of a key set (its id or its name)"] = "[movement | strafe | numbers | mouse | esdf | restore]  genvejstasttilstand, eller forhåndsvisning af et tastesæt (dets id eller navn)",
	["[name | reset]  list the tour helps, show one again, or show them all again"] = "[name | reset]  vis listen over førstegangshjælp, vis én igen, eller vis dem alle igen",
	["[page | use <addon> | keep <addon> | fit [on | off] [addon]]  which other addons do an EldoUI job; page = the Other addons page; use = EldoUI does that addon's jobs; keep = the addon does; fit = the layout spots for other addons"] = "[page | use <addon> | keep <addon> | fit [on | off] [addon]]  hvilke andre addons der dækker en EldoUI-funktion; page = siden Andre addons; use = EldoUI overtager addonens funktioner; keep = addonen beholder dem; fit = layoutpladserne til andre addons", -- l10n: keep
	["[track | missing]  language info; record and list texts that have no translation yet"] = "[track | missing]  sproginfo; registrer og vis tekster der endnu ikke har en oversættelse",
	["[undo]  fill the empty buttons of bars 4 and 5 with your out-of-combat class spells now; undo takes the last fill off again"] = "[undo]  fyld de tomme knapper på linje 4 og 5 med din klasses evner til uden for kamp nu; undo tager den seneste udfyldning af igen",
	["[undo]  open the keys and spells preview; undo takes the last new spells EldoUI placed off your bars again"] = "[undo]  åbn forhåndsvisningen af taster og evner; undo tager de nye evner EldoUI sidst satte på dine linjer af igen",
	["A 1-pixel shadow under EldoUI's text, softer when there is an outline too. With no outline, the shadow keeps text readable over bright ground."] = "En skygge på 1 pixel under EldoUI's tekst, blødere når der også er kontur. Uden kontur holder skyggen teksten læselig på lys baggrund.",
	["A bar that shows on mouse-over"] = "En linje der vises når du holder musen over",
	["A bar with gold, FPS ..."] = "En bjælke med guld, FPS ...",
	["A border, glow or tint in the threat color (Colors page). Only the game's threat state is used; the game's color curve shows it even where the state is hidden."] = "En kant, glød eller tone i aggrofarven (siden Farver). Kun spillets aggrotilstand bruges; spillets farvekurve viser den også hvor tilstanden er skjult.",
	["A bright line at the end of the cast bar fill."] = "En lys streg for enden af castbarens fyld.",
	["A bundle with %d parts."] = { one = "En samling med %d del.", other = "En samling med %d dele." },
	["A character on the picked profile. Its own picks from its setup are checked below; a character without a saved setup gets EldoUI's suggestions."] = "En karakter på den valgte profil. Dens egne valg fra dens opsætning er afkrydset herunder; en karakter uden gemt opsætning får EldoUI's forslag.",
	["A character on this profile whose keys differ from this key set (a new character, or keys the game reset). Ask me: one alert with a preview. Automatic: its keys are set out of combat, with a backup and Undo. Off: nothing happens. Keys you set yourself are never written over."] = "En karakter på denne profil hvis taster afviger fra dette tastesæt (en ny karakter eller taster som spillet har nulstillet). Spørg mig: én advarsel med forhåndsvisning. Automatisk: karakterens taster sættes uden for kamp med sikkerhedskopi og Fortryd. Fra: intet sker. Taster du selv har sat, bliver aldrig overskrevet.",
	["A chat reset can't be undone"] = "En nulstilling af chatten kan ikke fortrydes",
	["A class bar for every class but the shaman keeps your buffs, auras and key cooldowns in view."] = "En klassebjælke til alle klasser undtagen shaman holder dine buffs, auraer og vigtige cooldowns synlige.",
	["a class spell"] = "en klasseevne",
	["A copy from before is on the Saved data page."] = "En kopi fra før ligger på siden Gemte data.",
	["A copy is kept first: Undo in the alert or the Saved data page puts it back."] = "Der gemmes først en kopi: Fortryd i beskeden eller siden Gemte data sætter den tilbage.",
	["A defensive you use often."] = "En defensiv evne du bruger ofte.",
	["A dropped window's corner lands on this grid, in pixels. 1 places it freely."] = "Når du slipper et vindue, lander dets hjørne på dette gitter (i pixels). 1 placerer det frit.",
	["A faded window becomes solid while you point at it."] = "Et udtonet vindue bliver fuldt synligt mens du peger på det.",
	["A fear, not a stun."] = "En fear, ikke et stun.",
	["A few of the game's own interface settings that fit EldoUI. Only what is checked changes, and \"Blizzard default\" in /eui puts your own values back."] = "Et par af spillets egne interfaceindstillinger der passer til EldoUI. Kun det der er afkrydset, ændres, og \"Blizzard-standard\" i /eui gendanner dine egne værdier.",
	["A few short steps set up the whole UI. Every step is optional: Skip leaves that part as it is."] = "Et par korte trin sætter hele UI'et op. Alle trin er valgfrie: Spring over lader den del være som den er.",
	["A finisher: spends combo points."] = "En finisher: bruger combopoints.",
	["A form: faster on foot, no spells while in it."] = "En form: hurtigere til fods, ingen evner mens du er i den.",
	["A glow while the game marks the spell as important. The look is on the Glows page (Cast bars: important spells), shared by every cast bar."] = "En glød mens spillet markerer evnen som vigtig. Udseendet findes på siden Glød (Castbars: vigtige evner) og deles af alle castbars.",
	["A home-made swing timer would need hidden combat stats, so EldoUI skins Blizzard's built-in timer instead."] = "En hjemmelavet swingtimer ville kræve skjulte kampværdier, så EldoUI giver Blizzards indbyggede timer skin i stedet.",
	["A key the key sets never take."] = "En tast som tastesættene aldrig tager.",
	["A layer chip on the minimap shows your layer and hops you to another with a click."] = "En layer-chip på minikortet viser dit layer og skifter dig til et andet med et klik.",
	["A layout places all your frames at once. A style changes the look of one part. UI amount picks how many helpers are on. A pack sets all three in one click."] = "Et layout placerer alle dine rammer på én gang. En stil ændrer udseendet af én del. UI-mængde vælger hvor mange hjælpere der er slået til. En pakke sætter alle tre med ét klik.",
	["A level only switches EldoUI modules on or off. It never moves frames or changes your skin, key bindings or other addons."] = "Et trin slår kun EldoUI-moduler til eller fra. Det flytter aldrig rammer og ændrer aldrig dit skin, dine genvejstaster eller andre addons.",
	["a list with %d entries"] = { one = "en liste med %d post", other = "en liste med %d poster" },
	["A locked frame can't be dragged by accident. The arrows and the X and Y boxes still move it."] = "En låst ramme kan ikke trækkes ved et uheld. Pilene og X- og Y-felterne flytter den stadig.",
	["A Lua error was logged. Type %s to see it."] = "Der blev logget en Lua-fejl. Skriv %s for at se den.",
	["a macro with a lower rank: update it in /eui macros"] = "en makro med en lavere rang: opdater den i /eui macros",
	["A mark at the percent."] = "Et mærke ved procenten.",
	["A menu opens where you click it."] = "En menu åbner der hvor du klikker.",
	["A modern take on the original look: your frame and your target's sit low beside the center for short eye travel, over two bar rows, with the party on the left and the same round minimap."] = "En moderne udgave af det originale udseende: din ramme og dit måls sidder lavt ved midten, så øjet ikke skal flytte sig langt, over to rækker handlingslinjer, med gruppen til venstre og det samme runde minikort.",
	["A module switched off is fully gone after a reload."] = "Et modul der er slået fra, er helt væk efter en genindlæsning.",
	["A module that is off does nothing and costs nothing; Blizzard's own version of that part of the UI stays. Turning a module off fully brings back Blizzard's version after a reload, which Finish offers. Every module can be switched later in /eui > Modules or with the switch next to it in the options sidebar."] = "Et modul der er slået fra, gør intet og koster intet; Blizzards egen version af den del af UI'et bliver. Slår du et modul fra, kommer Blizzards version helt tilbage efter en genindlæsning; Afslut tilbyder en. Alle moduler kan slås til og fra senere i /eui > Moduler eller med kontakten ved siden af modulet i sidepanelet med indstillinger.",
	["A mount or travel spell you own."] = "En mount eller rejseevne du har.",
	["A new Keys and spells step shows your keys, class spells and macros first and changes nothing on your bars until you press Apply."] = "Et nyt Taster og evner-trin viser først dine taster, klasseevner og makroer og ændrer intet på dine handlingslinjer før du trykker på Anvend.",
	["A new profile %s, a copy with the %s role. %s stays as it is."] = "En ny profil %s, en kopi med rollen %s. %s røres ikke.",
	["A newer version of %s is out: %s (you have %s)."] = "En nyere version af %s er ude: %s (du har %s).",
	["A player (by name)"] = "En spiller (efter navn)",
	["A player's guild name."] = "En spillers guildnavn.",
	["A player's name with their chosen title."] = "En spillers navn med den valgte titel.",
	["A player's race."] = "En spillers race.",
	["A player's rank in their guild."] = "En spillers rang i guilden.",
	["A profile called \"%s\", fresh from EldoUI's defaults. Your current profile stays as it is, so you can switch back in /eui > Profiles."] = "En profil kaldet \"%s\", med EldoUI's standardindstillinger. Din nuværende profil røres ikke, så du kan skifte tilbage i /eui > Profiler.",
	["A profile holds the layout, skin, styles, modules and the Blizzard UI switches, and characters can share one. This page puts this character on a profile that is set up already and changes nothing in it.\n\nWhat belongs to the character is set up for it: chat tabs, game settings, other addons' profiles, click-casting for a class that has none on the profile yet, and class spells and macros on empty buttons. Each comes from what the character you copy from picked in its own setup, or from EldoUI's suggestions when it has no saved setup. Uncheck a part to leave it as it is.\n\nA profile set up for another role can be copied for this character's role: the copy gets the role, and the original stays as it is.\n\nAttach keeps a backup first. The last page lists every change with Revert this, and Undo the whole setup (or /eui install undo) puts this character back on the profile it used before. Full setup instead goes through every step on its own."] = "En profil rummer layoutet, skinnet, stilene, modulerne og Blizzard-UI-kontakterne, og flere karakterer kan dele en. Denne side sætter karakteren på en profil der allerede er sat op, og ændrer intet i den.\n\nDet der hører til karakteren, sættes op til den: chatfaner, spilindstillinger, andre addons' profiler, klikkast til en klasse som endnu ikke har noget på profilen, og klasseevner og makroer på tomme knapper. Hver del kommer fra det som karakteren du kopierer fra, valgte i sin egen opsætning, eller fra EldoUI's forslag hvis den ikke har en gemt opsætning. Fjern fluebenet ved en del for at lade den være som den er.\n\nEn profil der er sat op til en anden rolle, kan kopieres til denne karakters rolle: kopien får rollen, og originalen røres ikke.\n\nTilknyt gemmer først en sikkerhedskopi. Den sidste side viser hver ændring med Rul dette tilbage, og Fortryd hele opsætningen (eller /eui install undo) sætter karakteren tilbage på den profil den brugte før. Fuld opsætning går i stedet gennem hvert trin for sig.",
	["A profile named %s already exists. Use %s."] = "Der findes allerede en profil med navnet %s. Brug %s.",
	["A profile with that name already exists."] = "Der findes allerede en profil med det navn.",
	["A quiet center: unit frames high, level with the resource bar, three stacked bar rows."] = "En rolig midte: unitframes højt oppe på højde med ressourcebjælken, tre stablede rækker handlingslinjer.",
	["A quiet screen: thin unit and group frames, no keybind text, a small minimap and a quiet info bar."] = "En rolig skærm: tynde unitframes og grupperammer, ingen genvejstaster på knapperne, et lille minikort og en rolig infobjælke.",
	["A raid warning appears in the middle of the screen."] = "En raidadvarsel vises midt på skærmen.",
	["A ready check starts."] = "Et klar-tjek starter.",
	["A recipe one of your characters can learn later"] = "En opskrift som en af dine karakterer kan lære senere",
	["A recipe one of your characters can learn now"] = "En opskrift som en af dine karakterer kan lære nu",
	["A red band inside the frame."] = "Et rødt bånd inde i rammen.",
	["a reload"] = "en genindlæsning",
	["A role is not a layout. Healer moves your party and raid frames next to the center (a few frames that sat there step outward) and turns on dispel and boss debuff highlights. Tank adds threat colors and the threat meter. Melee and Ranged keep the layout as it is; Ranged also shows the five-second rule on your mana bar.\n\nClick-casting (healers): a binding casts a spell on the frame you click, e.g. Shift + left click casts your fast heal on that party member. EldoUI suggests spells from your spellbook; only the ones you tick are bound, plain left and right click stay target and menu, and nothing casts by itself. Change or remove them any time in /eui > Click Casting."] = "En rolle er ikke et layout. Healer flytter dine gruppe- og raidrammer ind ved midten (nogle få rammer der sad der, flytter udad) og slår fremhævning af dispel og bossdebuffs til. Tank tilføjer aggrofarver og aggromåleren. Melee og Ranged lader layoutet være som det er; Ranged viser også femsekundersreglen på din manabjælke.\n\nKlikkast (healere): en binding caster en evne på den ramme du klikker på, fx caster Shift + venstreklik din hurtige heal på det gruppemedlem. EldoUI foreslår evner fra din evnebog; kun dem du sætter flueben ved, bindes, almindeligt venstre- og højreklik er stadig mål og menu, og intet castes af sig selv. Ændr eller fjern dem når som helst i /eui > Klikkast.",
	["A role moves a few frames on top of your layout: healers get group frames near the center, tanks get threat colors."] = "En rolle flytter nogle få rammer oven på dit layout: healere får grupperammer nær midten, tanks får aggrofarver.",
	["A root, snare or second control spell."] = "En root, snare eller ekstra kontrolevne.",
	["A saved value EldoUI can't read is set aside here, never deleted. Put back returns it to its place and sets aside what sits there now."] = "En gemt værdi EldoUI ikke kan læse, lægges til side her og slettes aldrig. Læg tilbage sender den tilbage til sin plads og lægger det der står der nu, til side.",
	["A second movement spell, or a travel form."] = "En ekstra bevægelsesevne eller en rejseform.",
	["A second shade above this percent, for abilities that work on healthy units."] = "En ekstra skygge over denne procent, til evner der virker på enheder med meget liv.",
	["A second way to stop or push away an enemy."] = "En ekstra måde at stoppe eller skubbe en fjende væk på.",
	["A setting"] = "En indstilling",
	["A shaped portrait frame, a heavy divider between health and power and a shaded name strip."] = "En formet portrætramme, en kraftig skillelinje mellem liv og ressource og en skyggelagt navnestribe.",
	["A short explanation of this step."] = "En kort forklaring af dette trin.",
	["A short flash on the frame when your target changes. Follows General > Animations."] = "Et kort blink på rammen når dit mål skifter. Følger Generelt > Animationer.",
	["A slow pulsing border, no movement round the frame."] = "En langsomt pulserende kant, ingen bevægelse rundt om rammen.",
	["A small layer over your layout for the job you do in groups. Boss frames, boss mod bars and your cast bar never move by role."] = "Et lille lag over dit layout til den rolle du har i grupper. Bossrammer, bossmodbjælker og din castbar flytter sig aldrig efter rolle.",
	["A soft shadow around EldoUI windows and panels in the flat skins, Modern and Minimal Modern."] = "En blød skygge rundt om EldoUI's vinduer og paneler i de flade skins, Modern og Minimal Modern.",
	["A Soulstone on an ally is the warlock's ally save: Create Soulstone is on the Resurrection button."] = "En Soulstone på en allieret er Warlockens redning af en allieret: Create Soulstone ligger på knappen Genoplivning.",
	["A sound when a cast starts that the game marks as important. Stays silent where the game hides that flag. Off by default; no preset turns it on."] = "En lyd når et cast starter som spillet markerer som vigtigt. Er tavs hvor spillet skjuler den markering. Fra som standard; intet preset slår den til.",
	["A speed aspect, not a dash: a hit dazes you while it is on."] = "Et fartaspect, ikke en sprint: et slag gør dig dazed mens det er slået til.",
	["A spell for your role: a taunt, a mark or a slow fall."] = "En evne til din rolle: en taunt, et mark eller et slow fall.",
	["A spell ID, the exact spell name, or Shift-click a spell link into the box. Press Enter."] = "Et evne-ID, evnens præcise navn eller Shift-klik et evnelink ind i feltet. Tryk Enter.",
	["A spell you learn at a trainer or with a talent, when its button is empty. Ask me: one alert with a preview. Automatic: it goes on its button out of combat, with Undo. Off: nothing happens."] = "En evne du lærer hos en træner eller med et talent når dens knap er tom. Spørg mig: én advarsel med forhåndsvisning. Automatisk: den kommer på sin knap uden for kamp med Fortryd. Fra: intet sker.",
	["A step-by-step setup with Express, preset packs, UI amount and the Overview page."] = "En opsætningsguide trin for trin med Express, presetpakker, UI-mængde og Oversigt-siden.",
	["a string for %s. Copy it into that addon's own import; EldoUI doesn't apply it."] = "en streng til %s. Kopier den ind i addonens egen import; EldoUI anvender den ikke.",
	["A style sets the look of this part in one click. Picking another style replaces it, settings included, so pick the style first and fine-tune after."] = "En stil sætter udseendet af denne del med ét klik. Vælger du en anden stil, erstatter den denne, indstillinger med, så vælg stilen først og finjuster bagefter.",
	["A subtle color in the background of EldoUI windows and panels: Midnight blue, Pine green, Wine red or Dusk violet. None keeps the plain dark panels. Text keeps its contrast in every tint."] = "En diskret farve i baggrunden af EldoUI's vinduer og paneler: Midnight (blå), Pine (grøn), Wine (rød) eller Dusk (violet). Ingen beholder de almindelige mørke paneler. Teksten bevarer sin kontrast i alle toninger.",
	["A subtle tint in the background of EldoUI windows and panels."] = "En diskret toning i baggrunden af EldoUI's vinduer og paneler.",
	["A text string with the list, to share or keep."] = "En tekststreng med listen, til at dele eller gemme.",
	["A tidy modern screen: everything under your character, quiet flat panels with a fine edge and EldoUI's helpers."] = "En ryddelig moderne skærm: alt under din karakter, rolige flade paneler med en fin kant og EldoUI's hjælpere.",
	["A window dropped close to a screen edge sits flush against it."] = "Et vindue som du slipper tæt på en skærmkant, lægger sig helt op ad den.",
	["A window that would be taller than the screen at its scale is shown a little smaller. Its saved scale stays."] = "Et vindue der ville blive højere end skærmen ved sin skala, vises lidt mindre. Den gemte skala bevares.",
	["A/D strafe"] = "A/D-strafe",
	["A/D strafe only: Mouse 4 and Mouse 5 press buttons 6 and 7 of bars 1 to 3, with Shift and Ctrl for bars 2 and 3."] = "Kun A/D strafe: Mus 4 og Mus 5 trykker knap 6 og 7 på linje 1 til 3, med Shift og Ctrl for linje 2 og 3.",
	["Above"] = "Over",
	["Above health"] = "Over liv",
	["Absorb shield"] = "Absorberingsskjold",
	["Accent color"] = "Accentfarve",
	["Accent color, art style, fonts, bar texture, colors and the other General settings. Your layout stays; check Layout to take that too."] = "Accentfarve, grafikstil, skrifttyper, bjælketekstur, farver og de øvrige generelle indstillinger. Dit layout bliver; sæt hak i Layout for også at tage det med.",
	["Accent follows the theme accent (General). Class uses your class color. Custom uses the color you pick."] = "Accent følger temaets accentfarve (Generelt). Klasse bruger din klassefarve. Brugerdefineret bruger den farve du vælger.",
	["Accent, panels, sounds and scale for the whole UI."] = "Accentfarve, paneler, lyde og skala for hele UI'et.",
	["Accessibility"] = "Tilgængelighed",
