	["Accessibility settings put back."] = "Tilgængelighedsindstillingerne er gendannet.",
	["Accessibility: %s"] = "Tilgængelighed: %s",
	["Accessibility: keep"] = "Tilgængelighed: behold",
	["Account-wide lists"] = "Lister for hele kontoen",
	["Account-wide lists (all)"] = "Lister for hele kontoen (alle)",
	["Achievements"] = "Achievements",
	["Across from the screen point in the title to the same point of the frame: a higher number moves it right, a lower one left. Press Enter to apply."] = "Vandret fra skærmpunktet i titlen til samme punkt på rammen: et højere tal flytter den til højre, et lavere til venstre. Tryk Enter for at bruge det.",
	["Action bar procs"] = "Procs på handlingslinjer",
	["Action bars"] = "Handlingslinjer",
	["Action bars and buttons"] = "Handlingslinjer og knapper",
	["Action Bars and Cooldowns"] = "Handlingslinjer og cooldowns",
	["Action button look, cooldown text and proc alerts"] = "Handlingsknappernes udseende, cooldowntekst og proc-advarsler",
	["Action buttons"] = "Handlingsknapper",
	["Activate"] = "Aktiver",
	["Activate added Edit Mode layouts"] = "Aktiver tilføjede Edit Mode-layouts",
	["Acts for you: a spell you learn goes on an empty button with its key, out of combat."] = "Handler på dine vegne: en evne du lærer, sættes på en tom knap med sin genvejstast, uden for kamp.",
	["Acts for you: when you learn a higher rank of a spell, your buttons with a lower rank get the new one, out of combat."] = "Handler på dine vegne: når du lærer en højere rang af en evne, får dine knapper med en lavere rang den nye, uden for kamp.",
	["Acts for you: your class's out-of-combat spells (travel, tracking, poisons, pet care) go on the empty buttons of bars 4 and 5, out of combat."] = "Handler på dine vegne: din klasses evner til brug uden for kamp (rejse, sporing, gift, pleje af pet) kommer på de tomme knapper på linje 4 og 5, uden for kamp.",
	["Add a spell"] = "Tilføj en evne",
	["Add the class macros"] = "Tilføj klassemakroerne",
	["Add to Edit Mode"] = "Føj til Edit Mode",
	["Add to Edit Mode is off: %s."] = "Føj til Edit Mode er slået fra: %s.",
	["Add to Edit Mode: EldoUI saves it as a new account layout for you, out of combat."] = "Føj til Edit Mode: EldoUI gemmer det som et nyt kontolayout for dig, uden for kamp.",
	["Added the Edit Mode layout %s and made it active."] = "Edit Mode-layoutet %s er tilføjet og gjort aktivt.",
	["Added the Edit Mode layout %s."] = "Edit Mode-layoutet %s er tilføjet.",
	["AddOn list"] = "Addonliste",
	["Addon messages are restricted right now. Sending continues when the restriction ends."] = "Addonbeskeder er begrænset lige nu. Afsendelsen fortsætter når begrænsningen ophører.",
	["Addon messages are restricted right now. The offer goes out when the restriction ends."] = "Addonbeskeder er begrænset lige nu. Tilbuddet sendes når begrænsningen ophører.",
	["Addon profiles"] = "Addonprofiler",
	["Addon profiles are set up when combat ends."] = "Addonprofiler sættes op når kampen slutter.",
	["Addon setups: %s"] = "Addonopsætninger: %s",
	["Addon: %s"] = "Addon: %s",
	["Addons found"] = "Fundne addons",
	["Addons may not work out their own death analysis, so Blizzard's recap stays."] = "Addons må ikke selv analysere et dødsfald, så Blizzards oversigt bliver.",
	["Addons you already use"] = "Addons du allerede bruger",
	["Addons you use that do the same job as part of EldoUI, and who handles each job."] = "Addons du bruger som dækker det samme som en del af EldoUI, og hvem der står for hver funktion.",
	["Address book and quick send"] = "Adressebog og hurtig afsendelse",
	["After High contrast"] = "Efter Høj kontrast",
	["After the time below without a fight, target, movement, cast or loot, every EldoUI frame dims. Any of those, or the Show HUD key, brings it back."] = "Efter tiden nedenfor uden kamp, mål, bevægelse, cast eller loot dæmpes alle EldoUI-rammer. Enhver af dem, eller tasten Vis HUD, bringer dem tilbage.",
	["alarm and stopwatch"] = "alarm og stopur",
	["Alegreya SC"] = "Alegreya SC",
	["Alerts, banners and messages"] = "Advarsler, bannere og beskeder",
	["Alerts, toasts and banners"] = "Advarsler, pop op-beskeder og bannere",
	["Alignment guides"] = "Hjælpelinjer",
	["All"] = "Alle",
	["All follow the skin"] = "Alle følger skinnet",
	["All frame positions"] = "Alle rammeplaceringer",
	["All frames"] = "Alle rammer",
	["All frames reset to the current layout."] = "Alle rammer er nulstillet til det aktuelle layout.",
	["All lists"] = "Alle lister",
	["All modules"] = "Alle moduler",
	["All nine WoW: Forever dungeons have their own Journal pages, and quests say where they sit in their chain."] = "Alle ni WoW: Forever-dungeons har deres egne sider i Journalen, og quests fortæller hvor de ligger i deres kæde.",
	["All of them already have the settings of %s: nothing to copy."] = "Alle har allerede indstillingerne fra %s: intet at kopiere.",
	["All set"] = "Alt er klar",
	["Alliance"] = "Alliance",
	["Alliance or Horde."] = "Alliance eller Horde.",
	["Allow list (only these)"] = "Tilladelsesliste (kun disse)",
	["Allow lists show only their spells; block lists hide them. Built-in lists keep their type."] = "Tilladelseslister viser kun deres egne evner; blokeringslister skjuler dem. Indbyggede lister beholder deres type.",
	["Already on"] = "Allerede slået til",
	["already on your bars: not moved"] = "allerede på dine linjer: ikke flyttet",
	["already on your controller bars: not moved"] = "allerede på dine controllerlinjer: flyttes ikke",
	["Already set"] = "Allerede sat",
