	["Also add the class macros"] = "Tilføj også klassemakroerne",
	["Also done by EldoUI"] = "Klares også af EldoUI",
	["Also on this spot"] = "Også på denne plads",
	["Also on this spot: %s. Right-click to pick one."] = "Også på denne plads: %s. Højreklik for at vælge en.",
	["Also put class spells on empty buttons"] = "Sæt også klasseevner på tomme knapper",
	["Also turns off %s: EldoUI's modules take over their jobs."] = "Slår også %s fra: EldoUI's moduler overtager deres funktioner.",
	["Also turns on Move and scale for %s in Blizzard UI."] = "Slår også Flyt og skaler til for %s i Blizzard-UI.",
	["Also used by %s. The change is theirs too."] = "Bruges også af %s. Ændringen gælder også for dem.",
	["Also used by %s. They get a new, empty profile Default, and the setup opens at their next login."] = "Bruges også af %s. De får en ny, tom profil Default, og opsætningen åbner ved deres næste login.",
	["Also used by %s. They go back to the profile Default."] = "Bruges også af %s. De går tilbage til profilen Default.",
	["Alt"] = "Alt",
	["Alt overview"] = "Altoversigt",
	["Alt setup"] = "Opsætning til alts",
	["Alt+drag its side panels to detach them."] = "Alt+træk i sidepanelerne for at løsne dem.",
	["Alt-click"] = "Alt-klik",
	["Always"] = "Altid",
	["Always (in the profile)"] = "Altid (i profilen)",
	["Always keeps dragged places in the profile. The others forget them at logout or when the window closes. Scales are always kept."] = "Med Altid gemmes de placeringer du trækker vinduerne til, i profilen. Med de andre valg glemmes de ved logout eller når vinduet lukkes. Skalaer gemmes altid.",
	["Always pays with your own gold."] = "Betaler altid med dit eget guld.",
