	["Always shown"] = "Altid vist",
	["Always: never fades. Combat only: in combat. Mouse over: while the mouse is on it. Minimal: in combat or with a target. Quiet: while you are active. A change below makes it Custom."] = "Altid: toner aldrig ud. Kun i kamp: i kamp. Musen over: mens musen er over den. Minimal: i kamp eller med et mål. Quiet: mens du er aktiv. En ændring nedenfor gør den til Brugerdefineret.",
	["AM"] = "AM",
	["an anchor has no supported native frame"] = "en forankring har ingen understøttet EldoUI-ramme",
	["an anchor is ambiguous or points to itself"] = "en forankring er tvetydig eller peger på sig selv",
	["An EllesmereUI or ElvUI profile becomes an EldoUI layout. After the preview, apply it as a new profile or to this one; both can be undone."] = "En EllesmereUI- eller ElvUI-profil bliver til et EldoUI-layout. Efter forhåndsvisningen anvender du det som en ny profil eller på denne; begge dele kan fortrydes.",
	["An NPC's title (Innkeeper, Flight Master). Outside instances only."] = "En NPC's titel (Innkeeper, Flight Master). Kun uden for instanser.",
	["an older copy of this character's journal"] = "en ældre kopi af denne karakters journal",
