	["An older shape of this list."] = "En ældre form af denne liste.",
	["An open center for every class: three bar blocks in a row, unit frames low and far apart."] = "En åben midte til alle klasser: tre blokke handlingslinjer på række, unitframes lavt og langt fra hinanden.",
	["An open middle and a quiet screen: high frames, the quietest skin and only what you need to play."] = "En åben midte og en rolig skærm: rammer højt oppe, det mest afdæmpede skin og kun det du behøver for at spille.",
	["an unknown date"] = "en ukendt dato",
	["Anchor"] = "Ankerpunkt",
	["and %d more"] = { one = "og %d mere", other = "og %d mere" },
	["And %d more."] = { one = "Og %d til.", other = "Og %d til." },
	["Animations"] = "Animationer",
	["Ankh"] = "Ankh",
	["another addon has this spot"] = "en anden addon har denne plads",
	["Another character set up EldoUI on this account already. Pick the profile this character should use: the profile stays as it is, and only this character's own parts are set up. Attach keeps a backup first."] = "En anden karakter har allerede sat EldoUI op på denne konto. Vælg den profil denne karakter skal bruge: profilen røres ikke, og kun karakterens egne dele sættes op. Tilknyt gemmer først en sikkerhedskopi.",
	["Another character set up EldoUI on this account. Put this one on a profile you already have, as it is: only this character's own parts are set up."] = "En anden karakter har sat EldoUI op på denne konto. Brug en eksisterende profil uændret til denne karakter. Kun denne karakters egne dele sættes op.",
	["Another tank has it"] = "En anden tank har aggro",
	["Answer in the addon's own window to finish: %s"] = "Svar i addonens eget vindue for at gøre det færdigt: %s",
	["Any"] = "Alle",
