	["Appearance"] = "Udseende",
	["Applied"] = "Anvendt",
	["Applied %d parts of the bundle."] = { one = "%d del af samlingen er anvendt.", other = "%d dele af samlingen er anvendt." },
	["Applied last"] = "Sidst anvendt",
	["Applies at Finish"] = "Anvendes ved Afslut",
	["Applies at once. The first full look keeps following your layout's skin."] = "Anvendes med det samme. Det første komplette udseende følger fortsat dit layouts skin.",
	["Applies every pick you haven't applied yet and shows what changed."] = "Anvender alle valg du ikke har anvendt endnu og viser hvad der blev ændret.",
	["Applies the summary above. Parts on Keep stay exactly as they are."] = "Anvender opsummeringen ovenfor. Dele der står på Behold, er præcis som de er.",
	["Applies this step's pick and goes on to the next step. It also keeps the previews you picked on the steps before."] = "Anvender dette trins valg og går videre til næste trin. Forhåndsvisningerne fra de tidligere trin beholdes også.",
	["Apply"] = "Anvend",
	["Apply %s"] = "Anvend %s",
	["Apply %s to all of them"] = "Anvend %s på dem alle",
	["Apply %s?\n\n%s.\n\nOnly empty buttons get a spell and your own actions stay. Your current keys are saved first, and Undo puts everything back."] = "Anvend %s?\n\n%s.\n\nKun tomme knapper får en evne, og dine egne handlinger bevares. Dine nuværende taster gemmes først, og Fortryd sætter alt tilbage.",
	["Apply a layout"] = "Anvend et layout",
	["Apply a preset pack in one click, or go through the steps: each one shows its pick at once, and %s puts it back."] = "Anvend en presetpakke med ét klik, eller gå trinnene igennem: hvert trin viser sit valg med det samme, og %s sætter det tilbage.",
	["Apply also turns on auto repair (your own gold), junk selling and fast loot."] = "Anvend slår også automatisk reparation (dit eget guld), salg af skrald og hurtig loot til.",
	["Apply and continue"] = "Anvend og fortsæt",
	["Apply as a new layout"] = "Anvend som nyt layout",
	["Apply can also put your known class spells on empty buttons of bars 1 to 3. A button with your own action keeps it, and nothing moves by itself later: after you learn new spells, apply again to fill their buttons."] = "Anvend kan også sætte dine kendte klasseevner på tomme knapper på linje 1 til 3. En knap med din egen handling beholder den, og intet flytter sig af sig selv senere: anvend igen når du har lært nye evner, så deres knapper bliver fyldt.",
	["Apply checked parts"] = "Anvend valgte dele",
	["Apply complete look"] = "Anvend komplet udseende",
	["Apply the %s keys and class spells?\n\n%s.\n\nOnly empty buttons get a spell: your own actions stay, and nothing moves. Your current keys are saved first, and Undo puts back the keys and takes the spells off again."] = "Vil du anvende tasterne og klasseevnerne fra %s?\n\n%s.\n\nKun tomme knapper får en evne: det du selv har på knapperne, bliver liggende, og intet flyttes. Dine nuværende taster gemmes først, og Fortryd gendanner tasterne og fjerner evnerne igen.",
	["Apply the %s keys?\n\n%s.\n\nOnly keys change: spells and bars stay as they are. Your current keys are saved first, and Undo last key set puts them back."] = "Vil du anvende tasterne fra %s?\n\n%s.\n\nKun taster ændres: evner og linjer røres ikke. Dine nuværende taster gemmes først, og Fortryd sidste tastesæt lægger dem tilbage.",
	["Apply the pack"] = "Anvend pakken",
	["Apply to all (%d)"] = "Anvend på alle (%d)",
	["Apply UI amount"] = "Anvend UI-mængde",
	["April"] = "april",
	["Arcane"] = "Arcane",
