	["Arcane Powder"] = "Arcane Powder",
	["Arcane resistance"] = "Arkanmodstand",
	["Are you sure?"] = "Er du sikker?",
	["Area, finisher or resource spells for your role."] = "AoE-, finisher- eller ressourceevner til din rolle.",
	["Arrow across"] = "Pil vandret",
	["Arrow anchor"] = "Pilens ankerpunkt",
