	["Bar texture"] = "Bjælketekstur",
	["Bar texture, smooth bars, panel opacity and tint, frame shadows and every module's bar texture in one place."] = "Bjælketekstur, glidende bjælker, panelernes opacitet og toning, rammeskygger og alle modulers bjælketekstur samlet ét sted.",
