	["Bars"] = "Bjælker",
	["Bars %s appear when you point at their spot. Their buttons and keys always work."] = "Linje %s vises når du peger på deres plads. Knapperne og tasterne virker altid.",
	["Bars 1 to 3 hide their keys, so you can't see the keys you just set."] = "Linje 1 til 3 skjuler deres taster, så du kan ikke se de taster du lige har sat.",
	["Bars 1-8, pet, stance and vehicle bars, the zone ability, the totem bar, button look and gamepad bar. Changes wait until out of combat."] = "Linje 1-8, pet-, stance- og køretøjslinjer, zoneevnen, totemlinjen, knapudseende og gamepadlinje. Ændringer venter til du er uden for kamp.",
	["Bars 4 and 5 filled: %s. /eui fillbars undo takes them off again."] = "Linje 4 og 5 fyldt: %s. /eui fillbars undo tager dem af igen.",
	["Bars glide to new values instead of jumping. The game animates them, so this works in combat too."] = "Bjælker glider til nye værdier i stedet for at springe. Spillet animerer dem, så det virker også i kamp.",
