	["Base"] = "Basis",
	["Base size of the countdown numbers; 16 is normal. Action bars, bag slots and aura icons scale their own number size by this."] = "Grundstørrelse for nedtællingstallene; 16 er normalt. Handlingslinjer, taskepladser og auraikoner skalerer deres egen talstørrelse efter den.",
	["Base text size of EldoUI windows and bars."] = "Grundstørrelse for teksten i EldoUI's vinduer og bjælker.",
	["Bash, on Hard control in Bear Form, is the druid stop."] = "Bash, på Hård kontrol i Bear Form, er druidens stop.",
	["Bash, on Hard control, is the bear's stop."] = "Bash, på Hård kontrol, er bjørnens stop.",
	["Battlefield (zone) map"] = "Slagmarkskort (zonekort)",
	["Battleground"] = "Battleground",
