	["BigWigs: the EldoUI profile was not imported."] = "BigWigs: EldoUI-profilen blev ikke importeret.",
	["billion"] = "mia.",
	["Bind the spells checked below to clicks on party and raid frames. Nothing is bound unless this is checked."] = "Bind evnerne der er afkrydset herunder, til klik på gruppe- og raidrammer. Intet bindes medmindre dette er afkrydset.",
	["Bl"] = "Bl",
	["Black"] = "Sort",
	["Black opaque panels with bright 2-pixel borders (the High contrast art style) and a thick outline on every EldoUI text. Off puts back the art style and outline you had."] = "Sorte uigennemsigtige paneler med klare kanter på 2 pixels (grafikstilen Høj kontrast) og en tyk kontur på al EldoUI-tekst. Fra gendanner den grafikstil og kontur du havde.",
	["Black opaque panels with bright 2-pixel borders and a thick outline on every EldoUI text. It takes the place of the skin; turning it off in /eui puts that skin back."] = "Sorte uigennemsigtige paneler med lyse kanter på 2 pixel og en tyk kontur på al EldoUI-tekst. Det træder i stedet for skinnet; slår du det fra i /eui, kommer skinnet tilbage.",
	["Black opaque panels with bright borders and a thick text outline."] = "Sorte uigennemsigtige paneler med klare kanter og en tyk tekstkontur.",
