	["Blizzard Edit Mode layout with %d frames, added as a new Edit Mode layout."] = { one = "Blizzard Edit Mode-layout med %d ramme, tilføjet som et nyt Edit Mode-layout.", other = "Blizzard Edit Mode-layout med %d rammer, tilføjet som et nyt Edit Mode-layout." },
