	["Blizzard UI"] = "Blizzard-UI",
	["Blizzard UI > Edit Mode integration needs \"Let EldoUI change this\" and Improve switched on (or use Copy for Edit Mode)"] = "Blizzard-UI > Edit Mode-integration kræver at \"Lad EldoUI ændre dette\" og Forbedr er slået til (eller brug Kopier til Edit Mode)",
