	["close it"] = "luk den",
	["Close the setup for good: it doesn't open at login again. Closing the window instead pauses it, and /eui install goes on where you stopped."] = "Luk opsætningen for altid: den åbner ikke igen når du logger ind. Lukker du i stedet vinduet, sættes den på pause, og /eui install fortsætter hvor du slap.",
	["Close-range damage. Frames stay where the layout puts them, party frames are a little more compact."] = "Skade i nærkamp. Rammerne bliver hvor layoutet placerer dem, grupperammerne er lidt mere kompakte.",
	["Close: do it later"] = "Luk: gør det senere",
