	["drag"] = "træk",
	["drag a side panel"] = "træk et sidepanel",
	["Drag and let go to preview. 0.40 to 1.20."] = "Træk og slip for at se et eksempel. 0,40 til 1,20.",
	["Drag any frame to a new place (/eui move)."] = "Træk en ramme til en ny plads (/eui move).",
	["Drag any frame to move it. Right-click a frame for its options. Done or Escape keeps your changes and leaves."] = "Træk en ramme for at flytte den. Højreklik på en ramme for dens indstillinger. Færdig eller Esc gemmer dine ændringer og lukker.",
	["Drag Blizzard's windows where you want them and scale them with the mouse wheel. Uncheck a window to leave it to Blizzard."] = "Træk Blizzards vinduer hen hvor du vil have dem, og skaler dem med musehjulet. Fjern fluebenet ved et vindue for at overlade det til Blizzard.",
	["Drag by"] = "Træk i",
	["Drag EldoUI's frames where you want them. Right-click a frame for its exact position."] = "Træk EldoUI's rammer hen hvor du vil have dem. Højreklik på en ramme for at se dens nøjagtige placering.",
	["Drag frames to move them. Ctrl+Z takes back the last change, Undo changes puts everything back."] = "Træk rammer for at flytte dem. Ctrl+Z tager den seneste ændring tilbage, Fortryd ændringer lægger alt tilbage.",
	["Drag to change the window's size."] = "Træk for at ændre vinduets størrelse.",
	["Drag to make the window bigger or smaller; the content follows. Ctrl+mouse wheel on the title bar zooms."] = "Træk for at gøre vinduet større eller mindre; indholdet følger med. Ctrl+musehjul på titellinjen zoomer.",
	["Drag to make this window wider, narrower, taller or shorter. Saved for your account; Reset size next to the scale puts it back."] = "Træk for at gøre vinduet bredere, smallere, højere eller lavere. Gemmes for hele kontoen; Nulstil størrelse ved siden af skalaen sætter det tilbage.",
	["Drag to move (EldoUI)"] = "Træk for at flytte (EldoUI)",
	["Drag to move the window."] = "Træk for at flytte vinduet.",
	["Drag to move the window. Ctrl+mouse wheel zooms it."] = "Træk for at flytte vinduet. Ctrl+musehjul zoomer det.",
	["Dragged frames snap to the grid, to the edges and centers of other frames and to the screen center. Hold Alt while dragging to place a frame freely."] = "Rammer som du trækker, fastgøres til gitteret, til kanter og midter på andre rammer og til skærmens midte. Hold Alt nede under trækket for at placere en ramme frit.",
	["Draws what your skin brings: every skin names its own graphics."] = "Tegner det dit skin medbringer: hvert skin angiver sin egen grafik.",
	["Dressing room"] = "Prøverum",
	["Druids have no interrupt: healers get Remove Curse on this key."] = "Druids har ingen afbrydelse: healere får Remove Curse på denne tast.",
	["Druids have no interrupt: Prowl takes this key in Cat Form."] = "Druids har ingen afbrydelse: Prowl tager denne tast i Cat Form.",
	["Druids have no interrupt: the bear's taunt takes this key."] = "Druids har ingen afbrydelse: bjørnens taunt tager denne tast.",
	["Druids have no interrupt; Bash in Bear Form is a stun."] = "Druids har ingen afbrydelse; Bash i Bear Form er et stun.",
	["Druids have no offensive dispel."] = "Druids har ingen offensiv dispel.",
	["Dungeon bosses in the Journal learn their drops from group and solo loot."] = "Dungeonbossernes sider i Journalen lærer deres drops fra loot både i grupper og alene.",
	["dungeons, raids, battlegrounds and arenas"] = "dungeons, raids, battlegrounds og arenaer",
	["Durability figure (armor man)"] = "Holdbarhedsfigur (rustningsmanden)",
	["E and D move forward and back, S and F strafe, and you turn with the mouse. W, A and Q become spell keys; 1, 3, 5 and 6 stay free for your own bars."] = "E og D går frem og tilbage, S og F strafer, og du drejer med musen. W, A og Q bliver evnetaster; 1, 3, 5 og 6 er frie til dine egne linjer.",
	["E D move, S F strafe. Bar 1: R T G W 2 Q A V C X Z 4."] = "E D går, S F strafer. Linje 1: R T G W 2 Q A V C X Z 4.",
	["Each bar has its own keys now. The key preview on the Keybinds page in /eui shows every one, and Undo last key set there puts your old keys back."] = "Hver linje har nu sine egne taster. Tasteforhåndsvisningen på siden Genvejstaster i /eui viser dem alle, og Fortryd sidste tastesæt dér lægger dine gamle taster tilbage.",
	["Each chat window keeps its own font size."] = "Hvert chatvindue beholder sin egen skriftstørrelse.",
	["Each key set binds bars 1 to 3 and three Consumable Bar keys. Other bars keep their keys. A preview shows every key first."] = "Hvert tastesæt tildeler taster til linje 1 til 3 og tre taster på Forbrugslinjen. Andre linjer beholder deres taster. En forhåndsvisning viser alle taster først.",
	["Each module's own font setting. Theme font or Default means the module follows the theme font."] = "Hvert moduls egen indstilling for skrifttype. Temaskrifttype eller Standard betyder at modulet følger temaskrifttypen.",
	["Each part of Blizzard's own UI has one switch. Off leaves it as Blizzard made it. Skin, Move, Hide, Replace and Improve say what EldoUI may do with it."] = "Hver del af Blizzards egen UI har én kontakt. Når den er slået fra, er den som Blizzard lavede den. Skin, Flyt, Skjul, Erstat og Forbedr siger hvad EldoUI må gøre med den.",
	["Each spell goes on the button of its keybind category on bars 1 to 3, the same key on every class. Only empty buttons get a spell; a button with your own action is kept."] = "Hver evne kommer på knappen for dens genvejskategori på linje 1 til 3, med samme tast på alle klasser. Kun tomme knapper får en evne; en knap med din egen handling beholdes.",
	["Each stat is worth what your scale says; the score is their sum."] = "Hver stat er det værd som din skala siger; scoren er summen af dem.",
	["Each switch works on its own and can be turned off any time in %s > General > Accessibility, which puts back what you had. That page also has sound cues, the text size and the kind of color blindness."] = "Hver kontakt virker for sig og kan slås fra når som helst i %s > Generelt > Tilgængelighed, så du får det tilbage du havde. Den side har også lydsignaler, tekststørrelsen og typen af farveblindhed.",
	["Each tint on a sample panel in your skin. Click one to use it."] = "Hver toning på et prøvepanel i dit skin. Klik på en for at bruge den.",
	["Each window keeps the look set on the Blizzard UI page."] = "Hvert vindue beholder det udseende der er valgt på siden Blizzard-UI.",
	["Easy to read"] = "Let at læse",
	["Edit group"] = "Rediger gruppe",
	["Edit list"] = "Rediger liste",
	["Edit Mode already has %d account layouts, the most it allows; delete one in Edit Mode first"] = "Edit Mode har allerede %d kontolayouts, det højeste antal den tillader; slet først et i Edit Mode",
