	["Font"] = "Skrifttype",
	["Font of the countdown numbers on action bars, bag slots, aura icons and every other cooldown swipe that uses EldoUI's cooldown text. Theme font follows the Font above."] = "Skrifttype for nedtællingstallene på handlingslinjer, taskepladser, auraikoner og alle andre cooldown-swipes der bruger EldoUI's cooldowntekst. Temaskrifttype følger Skrifttype ovenfor.",
	["Font of the game's floating damage and healing numbers. The game reads it when the world loads: log out and back in to see it."] = "Skrifttype for spillets svævende skades- og healingstal. Spillet læser den når verden indlæses: log ud og ind igen for at se den.",
	["Font of the names above characters. The game reads it when the world loads: log out and back in to see it."] = "Skrifttype for navnene over karakterer. Spillet læser den når verden indlæses: log ud og ind igen for at se den.",
	["Font size"] = "Skriftstørrelse",
	["font size %d"] = "skriftstørrelse %d",
	["Fonts and text"] = "Skrifttyper og tekst",
	["For a mouse with 12 side buttons that send 1 to =. Bar 1: the side buttons, bar 2: Shift + the side buttons, bar 3: Q E R F T, Mouse 4, G Z X C V, Mouse 5. W and S move, A and D strafe."] = "Til en mus med 12 sideknapper der sender 1 til =. Linje 1: sideknapperne, linje 2: Shift + sideknapperne, linje 3: Q E R F T, Mus 4, G Z X C V, Mus 5. W og S går, A og D strafer.",
	["For your class: %s."] = "Til din klasse: %s.",
	["Forced combat restrictions are %s (%s): the client acts as if you were in combat. %s switches it off; it stays on after a reload until you do."] = "Tvungne kampbegrænsninger er %s (%s): klienten opfører sig som om du var i kamp. %s slår dem fra; de er slået til indtil du gør det, også efter en genindlæsning.",
	["Forced combat restrictions are off again (%s)."] = "Tvungne kampbegrænsninger er slået fra igen (%s).",
	["Forged Metal"] = "Forged Metal",
	["Forgets your own keys for this key set and shows the preview, where Apply puts them back."] = "Glemmer dine egne taster for dette tastesæt og viser forhåndsvisningen hvor Anvend sætter dem tilbage.",
	["Fortitude, Inner Fire and Divine Spirit reminders you click to cast, the five-second rule on your mana bar, a candle counter and restock, and Power Word: Shield, Fade and spells for your role on empty action slots. The class bar shows your buffs, key cooldowns and reagents"] = "Påmindelser om Fortitude, Inner Fire og Divine Spirit som du klikker på for at caste, femsekundsreglen på din manabjælke, en tæller for stearinlys med genopfyldning samt Power Word: Shield, Fade og evner til din rolle på tomme handlingspladser. Klassebjælken viser dine buffs, vigtige cooldowns og reagenser",
	["Four roles in the setup and on the Role page: Melee, Ranged, Healer and Tank."] = "Fire roller i opsætningsguiden og på Rolle-siden: Melee, Ranged, Healer og Tank.",
	["Frame across (percent of the screen)"] = "Ramme vandret (procent af skærmen)",
	["Frame anchor"] = "Rammens ankerpunkt",
	["Frame edge, bottom"] = "Rammens kant, nederst",
	["Frame edge, top"] = "Rammens kant, øverst",
	["Frame positions"] = "Rammeplaceringer",
	["Frame shadows"] = "Rammeskygger",
	["Frame shadows belong to the flat skins, Modern and Minimal Modern. Other skins draw a frame of their own."] = "Rammeskygger hører til de flade skins, Modern og Minimal Modern. Andre skins tegner deres egen ramme.",
	["Frame up and down (percent of the screen)"] = "Ramme lodret (procent af skærmen)",
	["Frames"] = "Rammer",
	["Frames can't be moved in combat."] = "Rammer kan ikke flyttes i kamp.",
	["Frames shown"] = "Viste rammer",
	["Frames snap to the grid, to each other's edges and centers, and to the screen center. Hold Alt while dragging to place freely."] = "Rammer fastgøres til gitteret, til hinandens kanter og midter og til skærmens midte. Hold Alt mens du trækker, for at placere frit.",
	["Frames stay put; the mana bar shows the five-second rule."] = "Rammerne bliver hvor de er; manabjælken viser femsekundersreglen.",
	["Frames stay where the layout puts them."] = "Rammerne bliver hvor layoutet placerer dem.",
	["Frames update when combat ends."] = "Rammerne opdateres når kampen slutter.",
	["Frames with a box: %d. Outside this view: %d. Hidden: %d. Off: %d."] = "Rammer med en boks: %d. Uden for denne visning: %d. Skjult: %d. Fra: %d.",
	["Frames you dragged go back to the layout's spots."] = "Rammer du har trukket, vender tilbage til layoutets pladser.",
	["Free text"] = "Fritekst",
	["Frees an ally (or you) from movement effects."] = "Befrier en allieret (eller dig) fra bevægelseseffekter.",
	["Freezing Trap: the enemy that steps on it freezes."] = "Freezing Trap: fjenden der træder på den, fryser.",
	["French"] = "Fransk",
	["French keyboard (AZERTY): A, Z, Q, W and M sit in other places."] = "Fransk tastatur (AZERTY): A, Z, Q, W og M sidder andre steder.",
	["Frenzied Regeneration is on the Short defensive button."] = "Frenzied Regeneration ligger på knappen Kort defensiv.",
