	["Gaining threat"] = "Stigende aggro",
	["Game buttons that EldoUI doesn't style show the seconds left on a cooldown. EldoUI's own buttons have their own cooldown numbers."] = "Spillets knapper som EldoUI ikke styler, viser hvor mange sekunder der er tilbage af en cooldown. EldoUI's egne knapper har deres egne cooldowntal.",
	["Game colors"] = "Spilfarver",
