	["Game font scale"] = "Skala for spillets skrifttyper",
	["Game fonts"] = "Spillets skrifttyper",
	["Game keys"] = "Spillets taster",
	["Game keys, and where %s moves them:"] = "Spillets taster, og hvor %s flytter dem hen:",
	["Game keys:"] = "Spillets taster:",
	["Game menu"] = "Spilmenu",
	["Game menu (Esc)"] = "Spilmenu (Esc)",
	["Game menu, Settings, AddOn list, keybinds, macros, Edit Mode integration, pop-up dialogs and Blizzard service windows."] = "Spilmenu, indstillinger, addonliste, genvejstaster, makroer, Edit Mode-integration, pop op-dialoger og Blizzards servicevinduer.",
	["Game setting"] = "Spillets indstilling",
	["Game settings"] = "Spilindstillinger",
	["Game settings are kept per character: the ones checked here are set the way the setup's Game settings step does it."] = "Spilindstillinger gemmes pr. karakter: dem der er afkrydset her, sættes som opsætningens trin Spilindstillinger gør det.",
	["Game settings: %s"] = "Spilindstillinger: %s",
	["Game settings: keep"] = "Spilindstillinger: behold",
	["Game shortcut, moved from %s"] = "Genvej i spillet, flyttet fra %s",
	["Game shortcut, moved with the pet bar"] = "Genvej i spillet, flyttet med petlinjen",
	["Gamepad action bar and controller HUD"] = "Gamepad-handlingslinje og controller-HUD",
	["Gamepad Mode UI"] = "Gamepadtilstand",
	["Gamepad Mode UI is on. It starts when you turn on the game's gamepad interface in the game's Controller settings."] = "Gamepadtilstand er slået til. Den starter når du slår spillets gamepadinterface til i spillets controllerindstillinger.",
	["Gamepad Mode UI offers a controller layout, with your usual frame positions kept for switching back to mouse and keyboard."] = "Gamepadtilstand tilbyder et controllerlayout og bevarer dine sædvanlige rammeplaceringer så du kan skifte tilbage til mus og tastatur.",
	["Gamepad: The Classic movement key set puts bars 1 to 3 on 1-5 R F G V X Z C, with Shift for bar 2 and Ctrl for bar 3, so T is free and V is used."] = "Gamepad: Tastesættet Klassisk bevægelse lægger linje 1 til 3 på 1-5 R F G V X Z C, med Shift til linje 2 og Ctrl til linje 3, så T er fri og V er i brug.",
	["Gear at or below this durability shows as low (red) everywhere EldoUI shows durability."] = "Udstyr med denne holdbarhed eller lavere vises som lav (rød) overalt hvor EldoUI viser holdbarhed.",
	["Gear at or below this durability shows as worn (yellow) everywhere EldoUI shows durability: the Info Bar, the character window, the ready report and the reminders."] = "Udstyr med denne holdbarhed eller lavere vises som slidt (gul) overalt hvor EldoUI viser holdbarhed: Infobjælken, karaktervinduet, klar-tjek-rapporten og påmindelserne.",
	["General"] = "Generelt",
	["General (theme, fonts, scale)"] = "Generelt (tema, skrifttyper, skala)",
	["General setting"] = "Generel indstilling",
	["General, Trade, LookingForGroup and the other numbered channels also get their own tab. The main window keeps them too."] = "General, Trade, LookingForGroup og de andre nummererede kanaler får også deres egen fane. Hovedvinduet beholder dem også.",
	["General: Every EldoUI version can be downloaded as a zip from its release page."] = "Generelt: Alle EldoUI-versioner kan hentes som zip-fil fra deres udgivelsesside.",
	["General: Gnome Dash has calm scenery on every course, and coins and opponents show as round pictures without boxes, so it is easy to see what you can stand on."] = "Generelt: Gnome Dash har en rolig baggrund på alle baner, og mønter og modstandere vises som runde billeder uden kasser, så det er let at se hvad du kan stå på.",
	["General: In Gnome Dash you steer an animated gnome and, after a mushroom, a dwarf that runs, jumps and faces the way it moves, instead of a portrait picture."] = "Generelt: I Gnome Dash styrer du en levende gnom og, efter en svamp, en dværg der løber, hopper og vender den vej den bevæger sig, i stedet for et portrætbillede.",
	["General: In Gnome Dash, the gnome and the dwarf face the way they run instead of running backwards."] = "Generelt: I Gnome Dash vender gnomen og dværgen den vej de løber i stedet for at løbe baglæns.",
	["General: In Gnome Dash, the gnome and the dwarf wear their own clothes and colors instead of showing plain white."] = "Generelt: I Gnome Dash har gnomen og dværgen deres eget tøj og egne farver i stedet for at være helt hvide.",
	["General: Names in Cyrillic, Korean and Chinese show their letters on nameplates, unit frames and every other place EldoUI shows a name, where they were empty boxes before."] = "Navne på kyrillisk, koreansk og kinesisk viser nu deres bogstaver i stedet for tomme firkanter på nameplates, unitframes og alle andre steder EldoUI viser et navn.",
	["General: The bug report form and the support pages name the error window's Report button, as the game shows it."] = "Generelt: Fejlrapportformularen og supportsiderne kalder fejlvinduets knap Rapporter ligesom i spillet.",
	["General: The install guide and the release notes name the WoW: Forever game folder, _forever_; the guide tells beta players to install EldoUI there again."] = "Generelt: Installationsvejledningen og udgivelsesnoterne angiver spilmappen til WoW: Forever, _forever_; vejledningen fortæller betaspillere at de skal installere EldoUI der igen.",
	["General: The note after an update has a \"Never show again, even after updates\" check box; the switch on the What's new page turns the note back on."] = "Generelt: Beskeden efter en opdatering har afkrydsningsfeltet \"Vis aldrig igen, heller ikke efter opdateringer\"; kontakten på siden Nyheder slår beskeden til igen.",
	["German"] = "Tysk",
	["German keyboard (QWERTZ): Z and Y swap places."] = "Tysk tastatur (QWERTZ): Z og Y bytter plads.",
	["Gets you somewhere fast: a charge, blink or sprint."] = "Får dig hurtigt frem: en charge, blink eller sprint.",
	["Ghost"] = "Ånd",
	["Ghost Wolf, on the Movement ability button, is the shaman's movement spell."] = "Ghost Wolf, på knappen Bevægelsesevne, er Shamanens bevægelsesevne.",
	["Give a module name. See %s."] = "Angiv et modulnavn. Se %s.",
	["Give one part its own skin. Follow skin keeps it with the rest."] = "Giv en enkelt del et skin for sig. Følg skin holder den sammen med resten.",
	["Give this frame the width or height of another frame. It is saved in this frame's own size setting."] = "Giv denne ramme samme bredde eller højde som en anden ramme. Det gemmes i rammens egen indstilling for størrelse.",
	["Give this key to the key set. The manual bar loses it."] = "Giv denne tast til tastesættet. Den manuelle linje mister den.",
	["Give to this character"] = "Giv til denne karakter",
	["Global settings"] = "Globale indstillinger",
	["Glow"] = "Glød",
	["Glow preview (click to close)"] = "Forhåndsvisning af glød (klik for at lukke)",
	["Glows"] = "Glød",
	["Glows round a cast bar on unit frames and nameplates while the spell is one the game marks as important."] = "Gløder rundt om en castbar på unitframes og nameplates mens evnen er en som spillet markerer som vigtig.",
	["Glows, pulses and sliding windows hold still; highlights stay as a steady border in their color. For players who get dizzy or distracted by moving parts. Same switch as General > Animations."] = "Glød, pulser og glidende vinduer står stille; fremhævninger bliver som en fast kant i deres farve. Til spillere der bliver svimle eller forstyrret af ting i bevægelse. Samme kontakt som Generelt > Animationer.",
	["Go back to your profile %s and remove the imported profile."] = "Gå tilbage til din profil %s, og fjern den importerede profil.",
	["Go straight to the review page with this layout and the picks of the other steps as they are. Finish applies them; Change goes back to any step."] = "Gå direkte til gennemgangssiden med dette layout og de andre trins valg som de er. Afslut anvender dem; Ændr går tilbage til et hvilket som helst trin.",
	["Goes back to %s."] = "Går tilbage til %s.",
	["goes on this empty button when you apply"] = "kommer på denne tomme knap når du anvender",
	["Goes on to the first step."] = "Går videre til første trin.",
	["Goes on to the next step."] = "Går videre til næste trin.",
	["Goes through every step of the setup on its own, from the Welcome step, as on a first character."] = "Gennemgår hvert trin i opsætningen fra Velkommen ligesom på den første karakter.",
	["Goes through the steps with the picked pack filled in; change anything on the way."] = "Gennemgår trinnene med den valgte pakke udfyldt; ændr hvad som helst undervejs.",
