	["Healer"] = "Healer",
	["Healer group frames"] = "Healerens grupperammer",
	["Healers can bind heals and dispels to modifier clicks on group frames. The setup suggests spells; check the ones you want."] = "Healere kan binde heals og dispels til klik med ændringstaster på grupperammer. Opsætningen foreslår evner; sæt flueben ved dem du vil have.",
	["Healers get a click-cast setup here. Your role can be changed any time in %s > Role, or with %s."] = "Healere får en klikkastopsætning her. Din rolle kan ændres når som helst i %s > Rolle eller med %s.",
	["Healers get Dispel Magic on this key: it cleanses allies and purges enemies."] = "Healere får Dispel Magic på denne tast: den renser allierede og fjerner buffs fra fjender.",
	["Healers have Cleanse on the Interrupt button: paladins have no interrupt."] = "Healere har Cleanse på knappen Afbrydelse: Paladins har ingen afbrydelse.",
	["Healers have Dispel Magic on the Interrupt button: it cleanses allies and purges enemies."] = "Healere har Dispel Magic på knappen Afbrydelse: den renser allierede og fjerner buffs fra fjender.",
	["Healers have Remove Curse on the Interrupt button of the caster page: druids have no interrupt."] = "Healere har Remove Curse på knappen Afbrydelse på caster-siden: Druids har ingen afbrydelse.",
	["Heals on the way to the unit, from the game's heal prediction."] = "Heals på vej til enheden, fra spillets healforudsigelse.",
