	["Helps an ally or your pet."] = "Hjælper en allieret eller dit pet.",
	["Here is what the setup changed. Revert this puts one part back as it was before."] = "Her er hvad opsætningen ændrede. Rul dette tilbage sætter én del tilbage som den var før.",
	["Hidden"] = "Skjult",
	["Hidden boxes"] = "Skjulte bokse",
	["hidden by you (Hidden in the frames list brings it back)"] = "skjult af dig (Skjult i rammelisten henter den tilbage)",
	["hidden in this layout, key works"] = "skjult i dette layout, tasten virker",
	["hidden right now"] = "skjult lige nu",
	["Hidden while you control a vehicle or have an override bar."] = "Skjult mens du styrer et køretøj eller har en overstyringslinje.",
	["Hidden while you rest in an inn or a city."] = "Skjult mens du hviler i en kro eller en by.",
	["Hidden while you rest in an inn or a city. If you start or stop resting during a fight, the frame follows once combat ends."] = "Skjult mens du hviler i en kro eller en by. Begynder eller holder du op med at hvile under en kamp, følger rammen med når kampen slutter.",
	["Hidden while you ride a mount, whatever the rule says."] = "Skjult mens du rider på en mount, uanset hvad reglen siger.",
	["hidden, the normal way"] = "skjulte på normal vis",
	["Hidden. Show it again on the Hidden boxes page under Modules in /eui, or in move mode under Hidden."] = "Skjult. Vis den igen på siden Skjulte bokse under Moduler i /eui eller i flyttetilstand under Skjult.",
	["hidden: turn on \"%s\" first"] = "skjult: slå \"%s\" til først",
	["Hide"] = "Skjul",
	["Hide %s"] = "Skjul %s",
	["Hide auras that last longer than this in total. Also hides auras without a duration."] = "Skjul auraer der i alt varer længere end dette. Skjuler også auraer uden varighed.",
	["Hide boxes"] = "Skjul bokse",
	["Hide every box, name, the grid and this panel to see the real UI with its test frames. A small bar brings them back."] = "Skjul alle bokse, navne, gitteret og dette panel for at se det rigtige UI med dets testrammer. En lille bjælke henter dem tilbage.",
	["Hide in a vehicle"] = "Skjul i køretøj",
	["Hide the interface"] = "Skjul brugerfladen",
	["Hide this box"] = "Skjul denne boks",
	["Hide this frame. It stays hidden, also after a reload, until you show it again under Hidden in this menu's view list or on the Hidden boxes page."] = "Skjul denne ramme. Den er skjult indtil du viser den igen under Skjult i menuens visningsliste eller på siden Skjulte bokse. Det gælder også efter en genindlæsning.",
	["Hide while mounted"] = "Skjul på mount",
	["Hide while resting"] = "Skjul i hvileområder",
	["hide, lock or reset it"] = "skjul, lås eller nulstil den",
	["Hides Blizzard's version completely. EldoUI's own frame for it, if there is one, stays."] = "Skjuler Blizzards version helt. EldoUI's egen ramme til den bevares hvis der er en.",
	["Hiding dialogs would mean answering them for you, and EldoUI never confirms anything on its own."] = "At skjule dialoger ville betyde at svare på dem for dig, og EldoUI bekræfter aldrig noget af sig selv.",
	["Hiding it would break the other addon's options."] = "At skjule det ville ødelægge den anden addons indstillinger.",
	["Hiding menus would leave you without their choices."] = "At skjule menuer ville efterlade dig uden deres valg.",
	["Hiding these would stop you from accepting queues and ready checks."] = "At skjule dem ville forhindre dig i at acceptere køer og klar-tjek.",
	["High contrast"] = "Høj kontrast",
	["High contrast is on (Accessibility). Your skin shows again once it is off."] = "Høj kontrast er slået til (Tilgængelighed). Dit skin vises igen når den er slået fra.",
	["High contrast, large text, color-blind safe colors, sound cues and reduced motion."] = "Høj kontrast, stor tekst, farveblindvenlige farver, lydsignaler og færre bevægelser.",
	["High contrast, large text, safe colors, sound cues and reduced motion together."] = "Høj kontrast, stor tekst, farveblindvenlige farver, lydsignaler og færre bevægelser samlet.",
	["High threat"] = "Høj aggro",
	["Hit an error"] = "Fejlede",
	["Hold it and drag a side panel (calendar events, raid info, macro icons, ...) to place it on its own; with a right-click it goes back."] = "Hold den nede og træk et sidepanel (kalenderbegivenheder, raidinfo, makroikoner, ...) for at placere det for sig; med et højreklik kommer det tilbage.",
	["Hold it and right-click the title bar to put the window back where Blizzard places it."] = "Hold den nede og højreklik på titellinjen for at sætte vinduet tilbage hvor Blizzard placerer det.",
	["Hold it and turn the mouse wheel over the title bar to scale the window; with a right-click it sets the normal size again."] = "Hold den nede og drej musehjulet over titellinjen for at skalere vinduet; med et højreklik får det normal størrelse igen.",
	["Hold Shift for bar 2 (group help, cleanse, second spells) and Ctrl for bar 3 (utility, travel, resurrection, class buff)."] = "Hold Shift for linje 2 (gruppehjælp, rensning, sekundære evner) og Ctrl for linje 3 (værktøj, rejse, genoplivning, klassebuff).",
	["Hold the mouse button (or hold Ctrl) to see the real UI for as long as you hold it."] = "Hold museknappen nede (eller hold Ctrl) for at se det rigtige UI så længe du holder den nede.",
	["Hold this key (or both keys) to drag a window, so a slipped click, on a quest's Accept button for example, never moves it. No key: a plain drag moves it. Move mode needs no key."] = "Hold denne tast (eller begge taster) nede for at trække et vindue, så et klik der glider, for eksempel på en quests Accept-knap, aldrig flytter det. Ingen tast: et almindeligt træk flytter det. Flyttetilstand behøver ingen tast.",
	["Hold to show the HUD"] = "Hold for at vise HUD'en",
	["holds a macro"] = "indeholder en makro",
	["holds an item"] = "indeholder en genstand",
	["holds your own action"] = "indeholder din egen handling",
	["Holy and Sacred Candles"] = "Holy- og Sacred Candles",
	["Holy Candle"] = "Holy Candle",
	["Honored"] = "Honored",
	["Horde"] = "Horde",
	["Horizontal"] = "Vandret",
	["Hornbeam Seed"] = "Hornbeam Seed",
	["Hostile"] = "Hostile",
	["Hover a button and press a key, mouse button or wheel. Escape clears."] = "Hold musen over en knap, og tryk på en tast, en museknap eller hjulet. Esc rydder.",
	["Hover any EldoUI button (action, pet, stance, extra, vehicle exit) and press a key to bind it."] = "Hold musen over en EldoUI-knap (handlingslinje, pet, stance, ekstra, forlad køretøj), og tryk på en tast for at tildele den.",
	["Hover any EldoUI button and press a key to bind it. Out of combat only."] = "Hold musen over en EldoUI-knap, og tryk på en tast for at tildele den. Kun uden for kamp.",
	["How an aura that is about to run out shows."] = "Hvordan en aura der snart udløber, vises.",
	["How big the whole UI is. EldoUI is made for 1440p; Auto keeps that size on every screen."] = "Hvor stort hele UI'et er. EldoUI er lavet til 1440p; Auto beholder den størrelse på alle skærme.",
	["How Blizzard's own windows look. Only windows EldoUI may change are touched; this never lets EldoUI change more."] = "Hvordan Blizzards egne vinduer ser ud. Kun vinduer som EldoUI må ændre, røres; dette giver aldrig EldoUI lov til at ændre mere.",
	["How Blizzard's own windows look. Only windows you let EldoUI change are touched."] = "Hvordan Blizzards egne vinduer ser ud. Kun vinduer du lader EldoUI ændre, bliver berørt.",
	["How Blizzard's own windows look. Only windows you let EldoUI change on the Blizzard UI page are touched. Original needs a reload."] = "Hvordan Blizzards egne vinduer ser ud. Kun vinduer som du lader EldoUI ændre på siden Blizzard-UI, bliver berørt. Original kræver en genindlæsning.",
	["How dark the frame shadows are."] = "Hvor mørke rammeskyggerne er.",
	["How every EldoUI clock writes the time: the Info Bar, the minimap clock, journals and logs. Game setting follows the game's own 24-hour clock option."] = "Hvordan alle EldoUI-ure skriver tiden: Infobjælken, minikortets ur, journaler og logs. Spillets indstilling følger spillets egen indstilling for 24-timers ur.",
	["How far a frame moves from its point at most, in screen pixels."] = "Hvor langt en ramme højst flytter sig fra sit punkt, i skærmpixels.",
	["How far the frame shadows reach beyond the edge of a window or panel."] = "Hvor langt rammeskyggerne rækker ud over kanten af et vindue eller panel.",
	["How gold is written in every EldoUI window, bar and tooltip. Bags, Auction House, Merchant and Trade can keep their own choice."] = "Hvordan guld skrives i alle EldoUI's vinduer, bjælker og tooltips. Tasker, Auktionshus, Købmand og Byt kan beholde deres eget valg.",
	["How many lines (Pixel lines) or dots (Sparkle) run round the frame."] = "Hvor mange linjer (Pixellinjer) eller prikker (Glimt) der løber rundt om rammen.",
	["How much bigger EldoUI's text gets with Large text on, from 100 to 160 %."] = "Hvor meget større EldoUI's tekst bliver med Stor tekst slået til, fra 100 til 160 %.",
	["How much EldoUI shows. Keep as set leaves every module as it is."] = "Hvor meget EldoUI viser. Behold som indstillet lader alle moduler være som de er.",
	["How much EldoUI shows: Essential, Moderate or Full. It only switches modules on or off."] = "Hvor meget EldoUI viser: Basis, Moderat eller Fuld. Det slår kun moduler til eller fra.",
	["How much one notch of the mouse wheel changes the scale."] = "Hvor meget ét hak på musehjulet ændrer skalaen.",
	["How solid EldoUI's panels on the screen are, such as chat, tooltips and meters. Windows are always solid. See-through panels never drop below 80%, so their text stays readable."] = "Hvor dækkende EldoUI's paneler på skærmen er, fx chat, tooltips og målere. Vinduer er altid dækkende. Gennemsigtige paneler kommer aldrig under 80%, så deres tekst er læselig.",
	["How strongly the grid lines show in move mode."] = "Hvor tydeligt gitterlinjerne vises i flyttetilstand.",
	["How tags, datatexts and tooltips shorten big numbers. Secret values in combat use the game's own style."] = "Hvordan tags, datatekster og tooltips forkorter store tal. Hemmelige værdier i kamp bruger spillets egen stil.",
	["How the execute range shows on the health bar."] = "Hvordan execute-området vises på livsbjælken.",
	["How the warning shows on the frame."] = "Hvordan advarslen vises på rammen.",
	["How to play"] = "Sådan spiller du",
	["How visible a frame stays while you are idle, for the modules you tick below."] = "Hvor synlig en ramme er mens du er inaktiv, for de moduler du sætter flueben ved nedenfor.",
	["How visible the frame stays while the rule says hide."] = "Hvor synlig rammen er mens reglen siger skjul.",
