	["Manage"] = "Administrer",
	["Managed by EldoUI"] = "Styres af EldoUI",
	["Map and minimap: Buttons on the minimap's side rail keep the rail's order, whichever one you put there first."] = "Kort og minimap: Knapper på minimappets sideskinne følger skinnens rækkefølge, uanset hvilken du placerer der først.",
	["Map and minimap: Layer hop asks the players in your zone directly and also works with players who use the most common layer addon, so many more players can invite you to another layer."] = "Kort og minikort: Layer-hop spørger spillerne i din zone direkte og virker også med spillere der bruger den mest udbredte layer-addon, så mange flere spillere kan invitere dig til et andet layer.",
	["Map and minimap: Layer hop has two new options, Leave the group by itself and Invite without a card, both off until you turn them on."] = "Kort og minikort: Layer-hop har to nye indstillinger, Forlad gruppen af sig selv og Inviter uden kort. Begge er slået fra indtil du slår dem til.",
	["Map and minimap: Logging in no longer shows a blocked-action error from the minimap, and the minimap now shows the name of the player who pings it."] = "Kort og minikort: Minikortet viser ikke længere en fejl om en blokeret handling når du logger ind, og det viser nu navnet på den spiller der pinger det.",
	["Map and minimap: The layer chip reads your layer the way the live realms keep it, so it shows the same layer as other players near you."] = "Kort og minikort: Layerikonet læser dit layer sådan som de rigtige realms holder styr på det, så det viser det samme layer som andre spillere tæt på dig.",
	["Map and minimap: The minimap starts without an error again after you log in."] = "Kort og minikort: Minikortet starter igen uden fejl når du logger ind.",
