	["Nothing changed: %s"] = "Intet ændret: %s",
	["Nothing changes here. You can turn Gamepad Mode UI on later in /eui > Layouts."] = "Intet ændres her. Du kan slå gamepadtilstand til senere i /eui > Layouts.",
	["Nothing changes: every class spell is on your controller bars already."] = "Intet ændres: alle klasseevner er allerede på dine controllerlinjer.",
	["nothing else"] = "intet andet",
	["Nothing else changes."] = "Intet andet ændres.",
	["Nothing here deletes your data. Restoring keeps what it replaces."] = "Intet her sletter dine data. En gendannelse gemmer det den erstatter.",
	["nothing in it maps to EldoUI"] = "intet i den svarer til noget i EldoUI",
	["Nothing in this string maps to EldoUI with the current choices."] = "Intet i denne streng svarer til noget i EldoUI med de nuværende valg.",
	["Nothing is held. Every part of your saved data follows EldoUI's updates."] = "Intet holdes tilbage. Alle dele af dine gemte data følger EldoUI's opdateringer.",
	["Nothing is set aside. Every saved value read as expected."] = "Intet er lagt til side. Alle gemte værdier blev læst som forventet.",
	["Nothing like that is held. The Saved data page lists what is held."] = "Der er ikke fastholdt noget af den slags. Siden Gemte data viser hvad der er fastholdt.",
	["Nothing matches \"%s\". The search looks at names, descriptions and choices."] = "Intet passer til \"%s\". Søgningen ser på navne, beskrivelser og valgmuligheder.",
	["Nothing needed to change."] = "Der var intet at ændre.",
	["Nothing of this character's own needs setting up."] = "Intet af karakterens egne dele skal sættes op.",
	["Nothing picked yet."] = "Intet valgt endnu.",
	["Nothing to change."] = "Intet at ændre.",
	["Nothing to change: you already use the %s layout as it is."] = "Intet at ændre: du bruger allerede layoutet %s som det er.",
	["Nothing to choose yet."] = "Intet at vælge endnu.",
	["Nothing to export for %s."] = "Intet at eksportere for %s.",
	["Nothing to place: bars 4 and 5 have no empty button, or your out-of-combat spells are already on your bars."] = "Intet at sætte på: linje 4 og 5 har ingen tom knap, eller dine evner til uden for kamp er allerede på dine linjer.",
	["Nothing to place: your buttons hold them already"] = "Intet at placere: dine knapper har dem allerede",
	["Nothing to set here yet. Turn on \"%s\" first."] = "Intet at indstille her endnu. Slå \"%s\" til først.",
	["Nothing to set on this tab right now. Its settings show when the switch they need is on."] = "Intet at indstille på denne fane lige nu. Indstillingerne vises når den kontakt de kræver, er slået til.",
	["Nothing to undo on this profile."] = "Intet at fortryde på denne profil.",
	["Nothing to undo yet."] = "Intet at fortryde endnu.",
	["Nothing to undo."] = "Intet at fortryde.",
	["Nothing waits for a reload right now. A reload starts every part of EldoUI fresh."] = "Intet venter på en genindlæsning lige nu. En genindlæsning starter alle dele af EldoUI på ny.",
	["Nothing was changed. Run the setup again any time with %s."] = "Intet blev ændret. Kør opsætningen igen når som helst med %s.",
	["Nothing was copied."] = "Intet blev kopieret.",
	["Nothing went wrong since the log was last cleared."] = "Intet er gået galt siden loggen sidst blev ryddet.",
	["Nothing: every button and key in the plan is free to change."] = "Intet: alle knapper og taster i planen må ændres.",
