	["Now: %s"] = "Nu: %s",
	["Now: %s. Set on Global settings > General. A skin brings its own accent only while yours is the default blue."] = "Nu: %s. Indstilles under Globale indstillinger > Generelt. Et skin bruger kun sin egen accent så længe din er den blå standard.",
	["Now: %s. Set on Global settings > Textures. Follow skin uses your skin's bar texture."] = "Nu: %s. Indstilles under Globale indstillinger > Teksturer. Følg skin bruger dit skins bjælketekstur.",
	["Now: %s. The skin of every window, bar and frame, and of each part on its own."] = "Nu: %s. Skinnet på alle vinduer, bjælker og rammer og på hver enkelt del for sig.",
	["Nudge"] = "Finjuster",
	["Number row"] = "Talrække",
	["Numbers"] = "Tal",
	["Numbers on cooldowns"] = "Tal på cooldowns",
	["Numbers on the game's bars"] = "Tal på spillets bjælker",
	["Objective / quest tracker"] = "Mål- og questtracker",
	["Obsidian glass with faceted silver edges, engraved crystal corners and hexagon portrait frames. Nothing glows or moves. Brings the Lavender accent while yours is the default blue."] = "Obsidianglas med facetterede sølvkanter, graverede krystalhjørner og sekskantede portrætrammer. Intet gløder eller bevæger sig. Bruger accenten Lavender så længe din er den blå standard.",
	["Obsidian glass with faceted silver edges."] = "Obsidianglas med facetterede sølvkanter.",
	["October"] = "oktober",
	["October 2026"] = "oktober 2026",
	["off"] = "fra",
	["Off"] = "Fra",
	["Off hand swing timer"] = "Swingtimer for off hand",
	["Off keeps Blizzard's own version, untouched."] = "Slået fra: Blizzards egen version, urørt.",
	["Off lets you pick a color per class below. Only EldoUI uses these; Blizzard's frames keep theirs."] = "Når den er slået fra, kan du vælge en farve pr. klasse herunder. Kun EldoUI bruger dem; Blizzards rammer beholder deres egne.",
	["off while %s is loaded"] = "fra mens %s er indlæst",
	["Off while %s is loaded."] = "Fra mens %s er indlæst.",
	["Off."] = "Fra.",
	["off: %s"] = "fra: %s",
	["Off: %s stays where its own settings put it."] = "Fra: %s bliver hvor dens egne indstillinger sætter den.",
	["Off: every addon stays where its own settings put it."] = "Fra: alle addons bliver hvor deres egne indstillinger sætter dem.",
	["Off: frames you moved stay where you put them. On: every frame goes to the layout's spot (Undo puts them back)."] = "Fra: rammer du har flyttet, bliver hvor du har sat dem. Til: alle rammer går til layoutets plads (Fortryd lægger dem tilbage).",
	["Off: only the important cast glow. Subtle: gentle motion and basic warnings. Standard: adds threat and absorbs. Vivid: adds pulses and flashes. Changing a row below makes it Custom."] = "Fra: kun glød ved vigtigt cast. Subtle: blid bevægelse og basale advarsler. Standard: tilføjer aggro og absorbering. Vivid: tilføjer pulser og blink. Ændrer du en række nedenfor, bliver den Brugerdefineret.",
	["Offensive dispel"] = "Offensiv dispel",
	["Offer the settings now."] = "Tilbyd indstillingerne nu.",
	["Offered %s to %s. It is sent when they accept."] = "%s er tilbudt til %s. Det sendes når modtageren accepterer.",
	["Offline"] = "Offline",
	["Offline, Dead, Ghost, AFK or DND; empty otherwise. Refreshes on its own when the state changes."] = "Offline, Dead, Ghost, AFK eller DND; ellers tomt. Opdateres af sig selv når tilstanden skifter.",
	["OK"] = "OK",
	["OLED care"] = "OLED-pleje",
	["On"] = "Til",
	["on"] = "til",
	["On a 16:10 screen the layouts give the boss frames, the boss mod windows, the party pets and many more frames a spot of their own."] = "På en 16:10-skærm giver layoutene bossrammerne, bossmodvinduerne, gruppens pets og mange flere rammer deres egen plads.",
	["On a very wide screen, EldoUI's frames stay inside a centered area while the game world fills the screen."] = "På en meget bred skærm holder EldoUI's rammer sig inden for et centreret område mens spilverdenen fylder hele skærmen.",
	["On gray and white items: \"Needed\" with the quest or recipe that needs it, or \"Safe to sell\" when none of your quests or recipes do (needs the Loot Guide's quest data)."] = "På grå og hvide genstande: \"Skal bruges\" med den quest eller opskrift der skal bruge genstanden, eller \"Kan sælges\" når ingen af dine quests eller opskrifter skal bruge den (kræver Loot Guides questdata).",
	["on its own"] = "selvstændigt",
	["On screen"] = "På skærmen",
	["On the Keys and spells step: %s."] = "På trinnet Taster og evner: %s.",
	["on the player frame"] = "på spillerrammen",
	["On this button now"] = "På denne knap nu",
	["On you (read only)"] = "På dig (skrivebeskyttet)",
	["On your screen that is also pixel perfect: one UI unit is one screen pixel."] = "På din skærm er det også pixelperfekt: én UI-enhed er én skærmpixel.",
	["On your target (read only)"] = "På dit mål (skrivebeskyttet)",
	["on | off  debug messages in chat"] = "on | off  debugbeskeder i chatten",
	["on | off  drag frames around (no word flips it)"] = "on | off  træk rammer rundt (uden ord slås det til eller fra)",
	["on | off  switch profiles by talent group and content"] = "on | off  skift profil efter talentgruppe og indhold",
	["On."] = "Til.",
	["on: %s"] = "til: %s",
	["On: EldoUI's frames are placed for controller play while the game's gamepad interface is on."] = "Til: EldoUI's rammer er placeret til controllerspil mens spillets gamepadinterface er slået til.",
	["On: frames in a corner (chat, minimap, meters, bags) move into the area too, best for 32:9. Off: they stay in the true screen corners and only the rest of the HUD moves in."] = "Til: rammer i et hjørne (chat, minikort, målere, tasker) flytter også ind i området, bedst til 32:9. Fra: de bliver i skærmens egentlige hjørner, og kun resten af HUD'en flytter ind.",
	["On: the Blizzard proc art keeps the game's own gold. Off: it takes the color below instead."] = "Til: Blizzards proc-grafik beholder spillets egen guldfarve. Fra: den får farven nedenfor i stedet.",
	["Once per new EldoUI version, a small window lists the main changes. Saved for your account."] = "Én gang for hver ny EldoUI-version viser et lille vindue de vigtigste ændringer. Gemmes for hele kontoen.",
	["One click sets the %s layout, a skin with its accent, the %s font and the styles that fit the layout. Below, change any part on its own."] = "Ét klik sætter layoutet %s, et skin med dets accent, skrifttypen %s og de stile der passer til layoutet. Herunder kan du ændre hver del for sig.",
	["One frame in three materials: blue stone and brass for the Alliance, oxblood leather and iron for the Horde, weathered stone and steel otherwise. Follows your character's faction unless you pick one, and brings that faction's accent while yours is the default blue."] = "Én ramme i tre materialer: blå sten og messing for Alliance, oksblodsrødt læder og jern for Horde, ellers forvitret sten og stål. Følger din karakters fraktion medmindre du vælger en, og bruger fraktionens accent så længe din er den blå standard.",
	["One line in chat at login with the EldoUI version and how to open these settings."] = "Én linje i chatten ved login med EldoUI-versionen og hvordan du åbner disse indstillinger.",
	["One line under the title."] = "Én linje under titlen.",
	["One look for every glow in EldoUI. A glow starts only when the game signals something: a proc, an aura or a reminder."] = "Ét udseende for al glød i EldoUI. En glød starter kun når spillet signalerer noget: en proc, en aura eller en påmindelse.",
	["One look per part of the UI (bars, unit frames, minimap and more). A style that makes a frame bigger moves its neighbors to make room, and a style that doesn't fit this layout is grayed out."] = "Ét udseende pr. del af UI'et (bjælker, unitframes, minikort med mere). En stil der gør en ramme større, flytter dens naboer for at give plads, og en stil der ikke passer til dette layout, er nedtonet.",
	["One notice at login the first time EldoUI finds an addon that does the same job as part of EldoUI, with a button to choose who handles it."] = "Én besked ved login første gang EldoUI finder en addon der dækker det samme som en del af EldoUI, med en knap til at vælge hvem der står for den.",
	["One of bars 1 to 3 shows another bar while Shift, Ctrl or Alt is held, and this key set puts keys on that modifier there. Checked, the bar keeps its own buttons, so those keys press them. The Action Bars page can change it back."] = "En af linje 1 til 3 viser en anden linje mens Shift-, Ctrl- eller Alt-tasten holdes nede, og dette tastesæt binder taster med netop den ændringstast. Med flueben beholder linjen sine egne knapper, så tasterne rammer dem. Siden Handlingslinjer kan ændre det tilbage.",
	["One of the game's own aura groups, e.g. crowd control or big defensives."] = "En af spillets egne auragrupper, fx crowd control eller store defensive evner.",
	["One pixel per click. Hold Shift for 10."] = "En pixel pr. klik. Hold Shift for 10.",
	["One switch per part of Blizzard's UI. Off leaves Blizzard's version untouched; on lets you pick what EldoUI may do with it."] = "Én kontakt pr. del af Blizzards UI. Slået fra: Blizzards version røres ikke. Slået til: du vælger hvad EldoUI må gøre med den.",
	["One symbol: + elite, R rare, R+ rare elite, B boss."] = "Ét symbol: + elite, R rare, R+ rare elite, B boss.",
	["One thing gets in the way of your keys:"] = "Én ting står i vejen for dine taster:",
	["One UI unit is one screen pixel on this screen. Frames keep their 1440p size, so on a smaller screen they can overlap."] = "Én UI-enhed er én skærmpixel på denne skærm. Rammerne beholder deres 1440p-størrelse, så på en mindre skærm kan de overlappe.",
	["Only auras that someone else applied."] = "Kun auraer som en anden har lagt på.",
	["Only auras whose spell is on this allow list. The game applies spell lists to buffs on friends and debuffs on enemies only."] = "Kun auraer hvis evne er på denne tilladelsesliste. Spillet bruger kun evnelister på buffs på venner og debuffs på fjender.",
	["Only auras you, your pet or your vehicle applied."] = "Kun auraer som du, dit pet eller dit køretøj har lagt på.",
	["Only buffs you could right-click off."] = "Kun buffs som du kan højreklikke væk.",
	["Only cancelable"] = "Kun dem du kan fjerne",
	["Only EldoUI's own frames"] = "Kun EldoUI's egne rammer",
	["Only errors from EldoUI and its plugins. Errors from other addons are hidden."] = "Kun fejl fra EldoUI og dens plugins. Fejl fra andre addons er skjult.",
	["Only errors seen since you logged in or reloaded."] = "Kun fejl set siden du loggede ind eller genindlæste.",
	["Only in a party"] = "Kun i en gruppe",
	["Only in a party or raid"] = "Kun i en gruppe eller et raid",
	["Only in a raid"] = "Kun i et raid",
	["Only other people's"] = "Kun andres",
	["Only spells on"] = "Kun evner på",
	["Only there"] = "Kun der",
	["Only what is checked is turned on. Change any of these later on the Conveniences page in %s, or on each module's own page."] = "Kun det der er afkrydset, slås til. Du kan ændre dem senere på siden Bekvemmeligheder i %s eller på hvert moduls egen side.",
	["Only what you need to play: your frames, bars, class tools, chat and minimap. EldoUI's extra helpers and tooltip lines are off."] = "Kun det du behøver for at spille: dine rammer, handlingslinjer, klasseværktøjer, chat og minikort. EldoUI's ekstra hjælpere og tooltiplinjer er slået fra.",
	["Only when solo"] = "Kun solo",
	["Only with a focus"] = "Kun med et fokusmål",
	["Only with Apply on its page"] = "Kun med Anvend på dens side",
	["Only without a focus"] = "Kun uden et fokusmål",
	["Only yours"] = "Kun dine",
	["Opacity of a member who is out of range."] = "Opaciteten af et medlem der er uden for rækkevidde.",
	["Opacity of open windows in combat. 100 % keeps them solid. The world map keeps its own fade."] = "Opaciteten af åbne vinduer i kamp. 100 % holder dem helt synlige. Verdenskortet har sin egen toning.",
	["Opacity of open windows while your character moves. 100 % keeps them solid."] = "Opaciteten af åbne vinduer mens din karakter bevæger sig. 100 % holder dem helt synlige.",
	["Open"] = "Åbn",
	["open \"%s\""] = "åbn \"%s\"",
	["Open %s and paste this text into a new bug report."] = "Åbn %s, og indsæt denne tekst i en ny fejlrapport.",
	["Open a part of the UI to pick its style; styles mix freely. A style that doesn't fit your layout is grayed out with the reason."] = "Åbn en del af UI'et for at vælge dens stil; stile kan blandes frit. En stil der ikke passer til dit layout, er nedtonet med årsagen.",
	["Open all"] = "Åbn alle",
	["Open all bags"] = "Åbn alle tasker",
	["Open Appearance"] = "Åbn Udseende",
	["Open Blizzard UI page"] = "Åbn siden Blizzard-UI",
	["Open Center"] = "Open Center",
	["Open Center (1440p)"] = "Open Center (1440p)",
	["Open controller settings"] = "Åbn controllerindstillinger",
	["Open error log"] = "Åbn fejlloggen",
	["Open Fonts and text"] = "Åbn Skrifttyper og tekst",
	["open its options"] = "åbn indstillingerne for den",
	["Open letter"] = "Åbent brev",
	["Open move mode"] = "Åbn flyttetilstand",
	["Open Next trips"] = "Åbn Næste ture",
	["Open or close move mode"] = "Åbn eller luk flyttetilstand",
	["Open or close My Adventure"] = "Åbn eller luk My Adventure",
	["Open or close the Alts window"] = "Åbn eller luk Alts-vinduet",
	["Open or close the Loot Guide"] = "Åbn eller luk Loot Guide",
	["Open settings"] = "Åbn indstillinger",
	["Open Textures"] = "Åbn Teksturer",
	["Open that step"] = "Åbn det trin",
	["open the calendar"] = "åbn kalenderen",
	["open the import window: EldoUI, EllesmereUI, ElvUI and Edit Mode strings"] = "åbn importvinduet: EldoUI-, EllesmereUI-, ElvUI- og Edit Mode-strenge",
	["Open the Loot Guide on Best in Slot"] = "Åbn Loot Guide på Best in Slot",
	["open the options (same as plain /eui)"] = "åbn indstillingerne (samme som /eui alene)",
	["Open the settings of the module that does this."] = "Åbn indstillingerne for det modul der gør dette.",
	["Open the settings page of %s."] = "Åbn indstillingssiden for %s.",
	["Open the short update note for this version again."] = "Åbn den korte opdateringsnote for denne version igen.",
	["Opens a short setup with only the new parts. Every step starts on keep, so you only change what you pick."] = "Åbner en kort opsætning med kun de nye dele. Alle trin starter på behold, så du kun ændrer det du vælger.",
	["Opens the alt setup: put this character on a profile you already set up, as it is, with its own chat tabs, game settings, click-casting and class spells. A backup is kept first."] = "Åbner opsætningen til alts. Denne karakter bruger en eksisterende profil uændret med sine egne chatfaner, spilindstillinger, klikkast og klasseevner. Der gemmes først en sikkerhedskopi.",
	["Opens the Controller view of the Key sets window: where your role's spells go on the game's controller bars. Nothing is placed until you choose Apply there."] = "Åbner Tastesæt-vinduets controllervisning: hvor din rolles evner placeres på spillets controllerlinjer. Intet placeres før du vælger Anvend dér.",
	["Opens the game's Controller settings, where you turn the game's gamepad interface on or off."] = "Åbner spillets controllerindstillinger hvor du slår spillets gamepadinterface til eller fra.",
	["Opens the Key sets window on its Controller view: where your role's spells go on the game's controller bars. You see every change first, and nothing is placed until you choose Apply."] = "Åbner Tastesæt-vinduet i controllervisningen: hvor din rolles evner placeres på spillets controllerlinjer. Du ser alle ændringer først, og intet placeres før du vælger Anvend.",
	["Opens the keyboard view of this plan: each key, its category and the spell meant for it."] = "Åbner tastaturvisningen af denne plan: hver tast, dens kategori og den evne der er tiltænkt den.",
	["Opens the Keys and spells window, where these are set too."] = "Åbner vinduet Taster og evner. De kan også indstilles der.",
	["Opens the Other addons page, where you pick who handles each job."] = "Åbner siden Andre addons hvor du vælger hvem der står for hver funktion.",
	["Opens the paste box. It recognizes EldoUI, EllesmereUI, ElvUI and Edit Mode strings and shows what each imports before you click Import."] = "Åbner indsætningsfeltet. Det genkender EldoUI-, EllesmereUI-, ElvUI- og Edit Mode-strenge og viser hvad hver af dem importerer før du klikker på Importer.",
	["Opens the Role step of the setup with the suggested bindings for your class. Nothing is bound until you check it and click Apply."] = "Åbner opsætningens Rolle-trin med de foreslåede bindinger til din klasse. Intet bindes før du sætter flueben ved det og klikker på Anvend.",
	["Opens the Saved data page and sums up what it holds."] = "Åbner siden Gemte data og opsummerer hvad den indeholder.",
	["Opens the setup on its first step."] = "Åbner opsætningen på det første trin.",
	["Opens the setup on that step, so you can try it again."] = "Åbner opsætningen på det trin, så du kan prøve igen.",
	["Opens the setup on the step where you stopped, with your picks."] = "Åbner opsætningen på det trin hvor du slap, med dine valg.",
	["Optional: easier to read for low vision and color blindness. Nothing here is on unless you check it."] = "Valgfrit: lettere at læse ved nedsat syn og farveblindhed. Intet her er slået til medmindre du sætter flueben ved det.",
	["Options"] = "Valg",
	["Options window"] = "Indstillingsvindue",
