	["Part of the setup hit an error and was skipped: %s. Everything else is set up."] = "En del af opsætningen fejlede og blev sprunget over: %s. Alt andet er sat op.",
	["Part of this module failed to load, so some settings may be missing or not work. The error log shows what happened."] = "En del af modulet kunne ikke indlæses, så nogle indstillinger mangler måske eller virker ikke. Fejlloggen viser hvad der skete.",
