	["Pick a level first."] = "Vælg et trin først.",
	["Pick a look above first."] = "Vælg først et udseende ovenfor.",
	["Pick a profile"] = "Vælg en profil",
	["Pick a skin for every window and panel, then a look for each part of the UI, or Keep to leave a part as it is. Looks that don't fit your layout are grayed out."] = "Vælg et skin til alle vinduer og paneler og derefter et udseende til hver del af UI'et, eller Behold for at lade en del være som den er. Udseender der ikke passer til dit layout, er nedtonede.",
	["Pick a spell to take it off the list."] = "Vælg en evne for at fjerne den fra listen.",
	["Pick a usable area other than Whole screen first."] = "Vælg først et andet brugbart område end Hele skærmen.",
	["Pick another layout: the families, a legacy layout you still use, or one of My layouts. It asks first."] = "Vælg et andet layout: en af familierne, et ældre layout du stadig bruger, eller et af Mine layouts. Du bliver spurgt først.",
	["Pick another profile"] = "Vælg en anden profil",
