	["Press a key to bind it. Escape clears."] = "Tryk på en tast for at tildele den. Esc rydder.",
	["Press Ctrl+C to copy the list, then paste it into the report."] = "Tryk på Ctrl+C for at kopiere listen, og indsæt den derefter i rapporten.",
	["Press Ctrl+C to copy, then paste it where you report a layout problem."] = "Tryk Ctrl+C for at kopiere, og indsæt det så der hvor du rapporterer et layoutproblem.",
