	["Press Ctrl+C. Then Esc > Edit Mode > Layouts dropdown > Import, paste with Ctrl+V, name it and click Import."] = "Tryk på Ctrl+C. Gå derefter til Esc > Edit Mode > rullemenuen Layouts > Import, indsæt med Ctrl+V, giv det et navn, og klik på Import.",
	["Press the 12th key of the number row: the second key right of 0 (= on a US keyboard)."] = "Tryk på den 12. tast i talrækken: den anden tast til højre for 0 (= på et amerikansk tastatur).",
