	["Pulse speed"] = "Pulshastighed",
	["Pulses per second, at most two."] = "Pulser pr. sekund, højst to.",
	["Pulses slowly when it matters most: when you have aggro as damage dealer or healer, or lose it as a tank. Static with animations off."] = "Pulserer langsomt når det betyder mest: når du har aggro som DPS'er eller healer, eller mister den som tank. Statisk med animationer slået fra.",
	["Pummel in Berserker Stance, Shield Bash with a shield."] = "Pummel i Berserker Stance, Shield Bash med et skjold.",
	["Purge"] = "Purge",
	["Purgeable"] = "Kan purges",
	["Put %s on empty controller buttons?\n\nOnly empty buttons get a spell and your own actions stay. Take back spells removes them again."] = "Sæt %s på tomme controllerknapper?\n\nKun tomme knapper får en evne, og dine egne handlinger bliver. Tag evner tilbage fjerner dem igen.",
	["Put a mark next to colors that mean something: + good, ! warning, x bad, so color alone never carries the meaning."] = "Sæt et mærke ved farver der betyder noget: + god, ! advarsel, x dårlig, så farven aldrig alene bærer betydningen.",
	["Put back"] = "Læg tilbage",
	["Put back %s as it was before the update? What it holds now is kept as a copy, and updates leave this part alone until you choose Let go on this page."] = "Vil du gendanne %s som den var før opdateringen? Det den indeholder nu, gemmes som en kopi, og opdateringer lader denne del være indtil du vælger Slip på denne side.",
	["Put back the keys this character had before."] = "Gendan de taster denne karakter havde før.",
	["Put back the keys you had before and take the placed spells off again."] = "Læg de taster tilbage du havde før, og fjern de placerede evner igen.",
	["Put back the keys you had before the last key set. A key you changed since stays yours."] = "Lægger de taster tilbage du havde før det sidste tastesæt. En tast du har ændret siden er stadig din.",
	["Put back the keys you had before the last key set? A key you changed since stays yours."] = "Vil du lægge de taster tilbage du havde før det sidste tastesæt? En tast du har ændret siden er stadig din.",
	["Put back the keys you had before this key set."] = "Læg de taster tilbage du havde før dette tastesæt.",
	["Put back the keys you had before, take the placed spells and macros off again and put back the old ranks."] = "Gendan de taster du havde før, fjern de placerede evner og makroer igen, og sæt evnerne tilbage til deres gamle rang.",
	["Put back the keys, spells, macros and ranks of the last Apply. A button or key you changed since stays yours."] = "Gendan taster, evner, makroer og evnernes rang fra seneste anvendelse. En knap eller tast du har ændret siden, er stadig din.",
	["Put back the setup from before this change. Settings you changed since stay yours."] = "Læg opsætningen fra før denne ændring tilbage. Indstillinger du har ændret siden da, beholder du.",
	["Put back the switches from before the last change on this page."] = "Gendan kontakterne fra før den seneste ændring på denne side.",
	["Put back: %s. Type /reload so every part of EldoUI reads it again."] = "Lagt tilbage: %s. Skriv /reload så alle dele af EldoUI læser den igen.",
	["Put down what is on your cursor first."] = "Slip først det du har på markøren.",
	["Put every Blizzard window back where Blizzard places it?"] = "Sæt alle Blizzard-vinduer tilbage hvor Blizzard placerer dem?",
	["put every frame back to its layout position"] = "sæt alle rammer tilbage til deres layoutplacering",
	["Put every frame back where it was when move mode started."] = "Sæt alle rammer tilbage hvor de var da flyttetilstand startede.",
	["Put every frame you dragged back where the current layout puts it."] = "Sæt alle rammer som du har trukket, tilbage hvor det aktuelle layout placerer dem.",
	["Put every frame you dragged back where the current layout puts it?"] = "Vil du sætte alle rammer du har trukket, tilbage hvor det aktuelle layout placerer dem?",
	["Put every part of Blizzard's UI back to Blizzard default? EldoUI's own frames stay. If a part needs a reload to finish, you are asked once."] = "Sæt alle dele af Blizzards UI tilbage til Blizzard-standard? EldoUI's egne rammer bevares. Kræver en del en genindlæsning for at blive færdig, bliver du spurgt én gang.",
	["Put every setting in this list back to the value it had before this session's changes."] = "Sæt alle indstillinger på listen tilbage til den værdi de havde før denne sessions ændringer.",
	["Put every setting of this module back to its default. Asks first."] = "Sæt alle modulets indstillinger tilbage til standard. Spørger først.",
	["Put frames I dragged back in the layout's spots"] = "Sæt rammer jeg har trukket, tilbage på layoutets pladser",
	["Put key spells on empty action slots"] = "Sæt vigtige evner på tomme handlingspladser",
	["Put the %d changed setting under %s back to its default?"] = "Vil du sætte den %d ændrede indstilling under %s tilbage til standard?",
	["Put the %d changed settings under %s back to their default?"] = "Vil du sætte de %d ændrede indstillinger under %s tilbage til standard?",
	["Put the changed settings of this section back to their defaults."] = "Sæt afsnittets ændrede indstillinger tilbage til standard.",
	["Put the journal of %s back exactly as it was before the update? Your journal as it is now is backed up first, but moments written since the update leave it. To add back only what is missing, use Restore a backup with Merge in My Adventure instead."] = "Vil du gendanne journalen for %s præcis som den var før opdateringen? Din nuværende journal sikkerhedskopieres først, men øjeblikke der er skrevet siden opdateringen, forsvinder fra den. Brug i stedet Gendan en sikkerhedskopi med Flet i My Adventure for kun at tilføje det der mangler.",
	["Put the journal of %s back exactly as it was when you forgot the character?"] = "Vil du gendanne journalen for %s præcis som den var da du glemte karakteren?",
	["Put the journal of %s back? It is merged into the journal the character has now, so nothing from either is lost."] = "Vil du lægge journalen for %s tilbage? Den flettes ind i den journal karakteren har nu, så intet fra nogen af dem går tabt.",
	["Put the profile %s back the way it was."] = "Sæt profilen %s tilbage som den var.",
	["Put the set back"] = "Sæt tastesættet tilbage",
	["Put them there"] = "Sæt dem der",
	["Put this setting back to the value it had before."] = "Sæt indstillingen tilbage til den værdi den havde før.",
	["Put this window back to its normal size and 100 % scale, in the middle of the screen."] = "Sæt vinduet tilbage til normal størrelse og 100 % skala midt på skærmen.",
	["Put your profile %s back the way it was before the import."] = "Gendan din profil %s til tilstanden før importen.",
	["Puts %s back as it was before this setup."] = "Sætter %s tilbage som det var før denne opsætning.",
	["Puts %s back as it was on %s."] = "Sætter %s tilbage som det var den %s.",
	["Puts a copy back after you confirm, out of combat. Without a name, the newest copy of that part is used. Example: /eui data restore profile Default"] = "Lægger en kopi tilbage når du har bekræftet, uden for kamp. Uden et navn bruges den nyeste kopi af den del. Eksempel: /eui data restore profile Default", -- l10n: keep
	["Puts back every value EldoUI wrote into %s's settings, except ones you changed since."] = "Sætter alle værdier tilbage som EldoUI skrev i indstillingerne for %s, undtagen dem du har ændret siden.",
	["Puts back the setup from before the last layout, look, role or UI amount change on this profile. Settings you changed since stay yours."] = "Gendanner opsætningen fra før den seneste ændring af layout, udseende, rolle eller UI-mængde på denne profil. Indstillinger du har ændret siden, er stadig dine.",
	["Puts every frame you dragged that now covers another back on the spot the layout gives it."] = "Sætter hver ramme du har trukket, og som nu dækker en anden, tilbage på den plads layoutet giver den.",
	["Puts the whole profile back as it was before this setup, after one more question. Chat tabs and other addons' profiles stay as they are."] = "Sætter hele profilen tilbage som den var før denne opsætning, efter ét spørgsmål mere. Chatfaner og andre addons' profiler røres ikke.",
	["Puts this character back on %s, as before the alt setup of %s."] = "Sætter karakteren tilbage på %s som før opsætningen til alts den %s.",
	["Puts this character back on the profile it used before, after one more question, with its chat tabs, game settings, click-casting and class spells as they were. The profile it was attached to stays as it is."] = "Sætter karakteren tilbage på den profil den brugte før, efter ét spørgsmål mere, med chatfaner, spilindstillinger, klikkast og klasseevner som de var. Profilen den blev tilknyttet, røres ikke.",
	["Puts this character on the profile you picked, as it is, and sets up the parts checked under This character gets. A backup is kept first, and Undo puts everything back."] = "Sætter karakteren på den valgte profil uændret og sætter de dele op der er afkrydset under Denne karakter får. Der gemmes først en sikkerhedskopi, og Fortryd sætter alt tilbage.",
	["Puts this journal back under its character. If the character has a journal again, the two are merged and nothing from either is lost. Works out of combat."] = "Lægger denne journal tilbage under dens karakter. Har karakteren en journal igen, flettes de to, og intet fra nogen af dem går tabt. Virker uden for kamp.",
	["Puts this part back as it was before the update. What it holds now is kept as a copy first. Works out of combat. Afterwards updates leave this part alone until you choose Let go below."] = "Lægger denne del tilbage som den var før opdateringen. Det den indeholder nu, gemmes først som en kopi. Virker uden for kamp. Bagefter lader opdateringer denne del være indtil du vælger Slip nedenfor.",
	["Puts this part back as it was just before your restore, to undo it. What it holds now is kept in its place."] = "Fortryder din gendannelse og lægger denne del tilbage som den var lige før. Det den indeholder nu, gemmes i stedet.",
	["Puts this window back where Blizzard places it and attaches its side panels again."] = "Sætter vinduet tilbage hvor Blizzard placerer det, og sætter sidepanelerne på igen.",
