	["Say, party, guild, raid and the rest: %s"] = "Sig, gruppe, guild, raid og resten: %s",
	["Scale"] = "Skala",
	["scale (%d%%)"] = "skala (%d%%)",
	["Scale factor %.2f."] = "Skaleringsfaktor %.2f.",
	["Scale of this options window, saved for your account. The UI scale stays as it is. The mouse wheel works here too; drag the corner at the bottom right to change its width and height."] = "Skalaen på dette indstillingsvindue, gemt for hele kontoen. UI-skalaen røres ikke. Musehjulet virker også her; træk i hjørnet nederst til højre for at ændre bredde og højde.",
	["Scales every game font from Blizzard's size. Chat keeps the size each chat window has."] = "Skalerer alle spillets skrifttyper ud fra Blizzards størrelse. Chatten beholder den størrelse hvert chatvindue har.",
