	["Seconds"] = "Sekunder",
	["Seconds a fade takes. With animations off (General) every change is instant."] = "Sekunder en toning tager. Med animationer slået fra (Generelt) sker alle ændringer med det samme.",
	["Seconds frames set to When active stay shown after your last fight, target, movement, cast or loot."] = "Hvor mange sekunder rammer sat til Når aktiv er synlige efter din seneste kamp, dit seneste mål, bevægelse, cast eller loot.",
	["Seconds left"] = "Sekunder tilbage",
	["Seconds left when tenths of a second show. 0 never shows tenths."] = "Sekunder tilbage når tiendedele af et sekund vises. 0 viser aldrig tiendedele.",
	["Seconds left when the countdown numbers turn the expiring color."] = "Sekunder tilbage når nedtællingstallene skifter til udløbsfarven.",
	["Seconds the fade takes."] = "Hvor mange sekunder toningen tager.",
	["Seconds the flash takes to fade."] = "Hvor mange sekunder blinket tager om at tone ud.",
	["Seconds the frame stays visible after the rule stops applying, e.g. after combat ends or the mouse leaves."] = "Sekunder rammen er synlig efter reglen holder op med at gælde, fx når kampen slutter eller musen forlader den.",
	["Section"] = "Afsnit",
	["See what's new"] = "Se nyheder",
	["Select all"] = "Vælg alle",
	["select it, then nudge it with the arrows or the arrow keys (Shift: 10)"] = "vælg den, og finjuster den så med pilene eller piletasterne (Shift: 10)",
	["Select none"] = "Fravælg alle",
	["Select text"] = "Marker tekst",
	["Select the shown entry so Ctrl+C copies it."] = "Marker den viste post, så Ctrl+C kopierer den.",
	["Selected"] = "Valgt",
	["Selected key"] = "Valgt tast",
	["Selected: %s"] = "Valgt: %s",
	["Selected: press Ctrl+C and paste it into your bug report."] = "Markeret: tryk Ctrl+C og indsæt det i din fejlrapport.",
	["Self sustain"] = "Selvforsyning",
	["Sell gray items at vendors"] = "Sælg grå genstande hos købmænd",
	["Selling gray items"] = "Salg af grå genstande",
	["Send"] = "Send",
	["Send settings to a group member, guild member or friend. They see what changes before anything is applied."] = "Send indstillinger til et gruppemedlem, guildmedlem eller en ven. Modtageren ser hvad der ændres før noget bliver anvendt.",
	["Send to a player"] = "Send til en spiller",
	["Send to whom? Party, raid, guild or a player name."] = "Send til hvem? Skriv party, raid, guild eller et spillernavn.",
	["Sent %s to %s."] = "%s er sendt til %s.",
	["September"] = "september",
	["Set %s the same on %s?"] = "Vil du sætte %s til det samme på %s?",
	["Set aside"] = "Lagt til side",
	["Set aside when an older value was put back."] = "Lagt til side da en ældre værdi blev lagt tilbage.",
	["Set by EldoUI's action bars (Action Bars > Lock action bars)."] = "Sat af EldoUI's handlingslinjer (Handlingslinjer > Lås handlingslinjer).",
	["Set by hand on the Blizzard UI page and kept that way: %d."] = "Indstillet manuelt på siden Blizzard-UI og bevaret sådan: %d.",
	["Set every module to"] = "Sæt alle moduler til",
	["Set every module's Show rule to this preset? What you set in each module's own Visibility settings is replaced."] = "Vil du sætte alle modulers visningsregel til dette preset? Det du har indstillet under hvert moduls egne synlighedsindstillinger, bliver erstattet.",
	["Set up"] = "Sæt op",
	["Set up \"%s\", the profile this character uses now. Parts you skip keep their settings."] = "Sæt \"%s\" op, den profil denne karakter bruger nu. Dele du springer over, beholder deres indstillinger.",
	["Set up click-casting"] = "Sæt klikkast op",
	["Set up keys for bars 1 to 3 and fill empty buttons with your class spells, and see every change first. Only this step's Apply changes your keys and buttons, and Finish leaves them alone."] = "Sæt taster op til linje 1 til 3, fyld tomme knapper med dine klasseevner og se alle ændringer først. Kun dette trins Anvend ændrer dine taster og knapper, og Afslut lader dem være.",
	["Set up other addons"] = "Sæt andre addons op",
	["set up the supported addons from EldoUI's profiles (asks first)"] = "sæt de understøttede addons op fra EldoUI's profiler (spørger først)",
	["Set up this character"] = "Sæt denne karakter op",
	["Set up: %s"] = "Sat op: %s",
	["Sets the %s layout (a preview until Apply or Finish), the %s skin with its accent, EldoUI's font and the styles the layout suggests. Back puts the old positions back."] = "Sætter layoutet %s (et eksempel indtil Anvend eller Afslut), skinnet %s med dets accent, EldoUI's skrifttype og de stile layoutet foreslår. Tilbage gendanner de gamle placeringer.",
	["Sets the %s layout (a preview until Apply or Finish), the skin it was made for (%s) with its accent, EldoUI's font and the styles the layout suggests. The skin keeps following your layout. Back puts the old positions back."] = "Sætter layoutet %s (et eksempel indtil Anvend eller Afslut), det skin det er lavet til (%s) med dets accent, EldoUI's skrifttype og de stile layoutet foreslår. Skinnet følger fortsat dit layout. Tilbage gendanner de gamle placeringer.",
	["Sets the theme font on the game's own font objects. Switching it off puts Blizzard's fonts back; text that is already on screen follows after a reload."] = "Lægger temaskrifttypen på spillets egne skrifttypeobjekter. Slår du den fra, kommer Blizzards skrifttyper tilbage; tekst der allerede er på skærmen, følger efter en genindlæsning.",
	["Sets up every step with the pack at once: also chat tabs, game settings and other addons' profiles, and it turns on auto repair (your own gold), junk selling and fast loot. Then it shows your keys and spells, which change only when you press Apply there, and afterwards what changed, each part with Revert this."] = "Sætter alle trin op med pakken på én gang: også chatfaner, spilindstillinger og andre addons' profiler, og den slår automatisk reparation (dit eget guld), salg af skrald og hurtig loot til. Derefter viser den dine taster og evner (de ændres kun når du trykker på Anvend der) og bagefter hvad der blev ændret, hver del med Rul dette tilbage.",
	["Setting up the profile %s."] = "Sætter profilen %s op.",
	["Setting up the profile %s. To set up another profile instead, switch to it (or make a new one) on the Profiles page, then run %s: the setup starts over there."] = "Sætter profilen %s op. Vil du sætte en anden profil op i stedet, så skift til den (eller lav en ny) på siden Profiler, og kør derefter %s: opsætningen starter forfra der.",
	["Setting up the profiles of addons EldoUI places (Details!, BigWigs and more) is the setup's Other addons step: %s."] = "Opsætning af profilerne for de addons EldoUI placerer (Details!, BigWigs med flere) er opsætningens trin Andre addons: %s.",
	["Settings"] = "Indstillinger",
	["Settings from a string were imported into your profile %s."] = "Indstillinger fra en streng blev importeret ind i din profil %s.",
	["Settings that act for you (auto loot, auto accept and the like) are never changed here."] = "Indstillinger der handler på dine vegne (autoloot, automatisk accept og lignende), ændres aldrig her.",
	["Settings window"] = "Indstillingsvindue",
	["Settings you change in this window show up here until the next reload."] = "Indstillinger som du ændrer i dette vindue, vises her indtil næste genindlæsning.",
	["Settings: %s"] = "Indstillinger: %s",
