	["Shown on every nameplate"] = "Vist på alle nameplates",
	["Shown on the personal nameplate"] = "Vist på den personlige nameplate",
	["Shown only in this kind of group, whatever the rule says. A party is a group that is not a raid."] = "Vises kun i denne type gruppe, uanset hvad reglen siger. Gruppe betyder her en gruppe der ikke er et raid.",
	["Shown only while this talent group (dual specialization) is active."] = "Vises kun mens denne talentgruppe (dual spec) er aktiv.",
	["Shown only while you have a focus target, or only while you have none."] = "Vises kun mens du har et fokusmål, eller kun mens du ikke har et.",
	["Shows"] = "Viser",
	["Shows %s on screen. Right-clicking it and choosing Hide turns this off; the Hidden boxes page under Modules lists every hidden box."] = "Viser %s på skærmen. Højreklikker du på den og vælger Skjul, slås dette fra; siden Skjulte bokse under Moduler viser alle skjulte bokse.",
	["Shows every glow below on a sample icon for a few seconds. Changes show at once."] = "Viser al glød nedenfor på et prøveikon i nogle sekunder. Ændringer vises med det samme.",
	["Shows every key first; nothing changes until you press Apply there."] = "Viser alle taster først; intet ændres før du trykker på Anvend der.",
	["Shows its box, selects it and flashes it."] = "Viser dens boks, vælger den og får den til at blinke.",
	["shows on screen; All frames lists it"] = "vises på skærmen; Alle rammer viser den",
	["Shows the %s box in move mode. Turned off, the box is gone from move mode and the addon's own window stays as that addon shows it; the Hidden boxes page under Modules lists every hidden box."] = "Viser boksen for %s i flyttetilstand. Når den er slået fra, er boksen væk fra flyttetilstand, og addonens eget vindue er som addonen viser det; siden Skjulte bokse under Moduler viser alle skjulte bokse.",
	["Shows the errors EldoUI caught, with what happened."] = "Viser de fejl EldoUI har fanget, og hvad der skete.",
	["Shows the keys on bars 1 to 3 even when the action bar text style hides them. Off, those bars follow Action Bars > Show keybind like the others."] = "Viser tasterne på linje 1 til 3, også når tekststilen for handlingslinjerne skjuler dem. Når den er slået fra, følger de linjer Handlingslinjer > Vis genvejstast ligesom de andre.",
	["Shows the outline of the area until you click again. Move mode (/eui move) shows it too."] = "Viser omridset af området indtil du klikker igen. Flyttetilstand (/eui move) viser det også.",
	["Shows who interrupted a cast, like the game's own cast bar."] = "Viser hvem der afbrød et cast, ligesom spillets egen castbar.",
	["Shows your setup in full (version, layout, skin, role, UI amount, screen and text size, and which frames have no box right now) to copy into a bug report."] = "Viser hele din opsætning (version, layout, skin, rolle, UI-mængde, skærm- og tekststørrelse, og hvilke rammer der ikke har en boks lige nu) til at kopiere ind i en fejlrapport.",
	["Side margin"] = "Sidemargen",
	["Side-button mouse"] = "Mus med sideknapper",
	["Silences every sound EldoUI plays through its media library. The game's own sounds are not affected."] = "Slår alle lyde fra som EldoUI afspiller via sit mediebibliotek. Spillets egne lyde påvirkes ikke.",
	["Silencing emotes while resting"] = "Dæmpning af emotes i hvileområder",
	["Sit or stand"] = "Sid eller stå",
	["Size"] = "Størrelse",
	["Size of this window. The mouse wheel on its title bar changes it too."] = "Vinduets størrelse. Musehjulet på titellinjen ændrer den også.",
