	["Social window"] = "Socialt vindue",
	["Soft"] = "Blød",
	["Solid under the mouse"] = "Fuldt synlig under musen",
	["Solo"] = "Solo",
	["Solo and leveling: low unit frames beside the top bar row, pet above the player, target of target above the target."] = "Solo og leveling: lave unitframes ved siden af den øverste række handlingslinjer, pet over spilleren, målets mål over målet.",
	["Some addons ask once more in their own window before they import. A profile you made yourself can be saved with %s and is then used here."] = "Nogle addons spørger én gang til i deres eget vindue før de importerer. En profil du selv har lavet, kan gemmes med %s og bruges så her.",
	["Some changes (profile, Blizzard frames, modules) take full effect after a reload. Everything can be changed later in %s, and %s runs this setup again."] = "Nogle ændringer (profil, Blizzard-rammer, moduler) træder først helt i kraft efter en genindlæsning. Alt kan ændres senere i %s, og %s kører opsætningen igen.",
	["Some changes take full effect after a reload."] = "Nogle ændringer træder først helt i kraft efter en genindlæsning.",
	["Some EldoUI settings could not be updated this time. They are kept as they were, and the update runs again at your next login."] = "Nogle EldoUI-indstillinger kunne ikke opdateres denne gang. De beholdes som de var, og opdateringen kører igen næste gang du logger ind.",
	["Some frames cover each other now:"] = "Nogle rammer dækker nu hinanden:",
	["Some keyboards have an accent key there that types nothing on its own. The key sets then leave that place without a key."] = "Nogle tastaturer har dér en accenttast som ikke skriver noget alene. Tastesættene lader så den plads være uden tast.",
