	["Start countdown (battleground gates, pull countdown)"] = "Startnedtælling (battleground-porte, pull-nedtælling)",
	["Start fresh"] = "Start forfra",
	["Start over"] = "Start forfra",
	["Start setup"] = "Start opsætningen",
	["Start the EldoUI profile fresh"] = "Start EldoUI-profilen forfra",
	["Starts a quest"] = "Starter en quest",
	["Starts the quest %s"] = "Starter questen %s",
	["Stat weights"] = "Statvægte",
	["Statistics"] = "Statistik",
	["Status"] = "Status",
	["Status (AFK, dead ...)"] = "Status (AFK, død ...)",
	["stays free: the Consumable Bar is off"] = "er fri: Forbrugslinjen er slået fra",
	["Stealable"] = "Kan stjæles",
	["Step %d of %d"] = "Trin %d af %d",
	["Step %d of %d."] = "Trin %d af %d.",
	["Stone"] = "Sten",
	["Stone background with a gold-tinted border."] = "Stenbaggrund med en guldtonet kant.",
	["Stop"] = "Stop",
	["Stopped recording missing translations."] = "Registrerer ikke længere manglende oversættelser.",
	["Stops an enemy cast."] = "Stopper en fjendes cast.",
	["Strafe"] = "Strafe",
	["Stranglethorn Seed"] = "Stranglethorn Seed",
	["string cut short"] = "strengen er afkortet",
	["Strings from other UIs"] = "Strenge fra andre brugerflader",
	["Stronger colors for quick reading in busy fights."] = "Stærkere farver der er hurtige at aflæse i hektiske kampe.",
	["Structured"] = "Structured",
	["Style"] = "Stil",
	["Style and color of every glow: procs, highlights, reminders."] = "Stil og farve for al glød: procs, fremhævninger, påmindelser.",
	["Style presets"] = "Stilpresets",
	["Styles"] = "Stile",
	["Styles: %s"] = "Stile: %s",
	["Styles: %s and %d more"] = "Stile: %s og %d mere",
	["Styles: keep"] = "Stile: behold",
	["Subtle pulse"] = "Subtle pulse",
	["Summary"] = "Opsummering",
	["Sunday"] = "søndag",
	["Support"] = "Støtte",
	["Supported addons can follow your layout's reserved spots, with per-addon opt-outs and Undo."] = "Understøttede addons kan følge de reserverede pladser i dit layout; du kan fravælge det for hver addon og bruge Fortryd.",
	["Supported: the layouts keep their room and the text gets smaller."] = "Understøttet: layoutene beholder deres plads, og teksten bliver mindre.",
	["Supporters"] = "Støttere",
	["Surname (first name if none)"] = "Efternavn (ellers fornavn)",
	["Sust"] = "Selv",
	["Swing timer (main hand, off hand, ranged)"] = "Swingtimer (main hand, off hand, ranged)",
	["Switch %s on or off."] = "Slå %s til eller fra.",
	["Switch back in each addon's profiles"] = "Skift tilbage i hver addons profiler",
	["Switch every part of %s on or off. Blizzard's own version comes fully back after a reload."] = "Slå alle dele af %s til eller fra. Blizzards egen version kommer helt tilbage efter en genindlæsning.",
	["switch it off"] = "slå det fra",
	["switch it on"] = "slå det til",
	["Switch profile by talent group or by kind of content. A content rule wins over a talent group rule. Switching waits until you leave combat."] = "Skift profil efter talentgruppe eller type indhold. En indholdsregel vinder over en talentgrupperegel. Skiftet venter til du forlader kampen.",
	["Switch profiles automatically"] = "Skift profiler automatisk",
	["Switch profiles automatically by talent group or content."] = "Skift profil automatisk efter talentgruppe eller indhold.",
	["Switch the test restrictions on out of combat."] = "Slå testbegrænsningerne til uden for kamp.",
	["Switch, create, copy or reset the profile this character uses."] = "Skift, opret, kopier eller nulstil den profil denne karakter bruger.",
	["Switched off: %s. Blizzard's own versions come fully back after a reload."] = "Slået fra: %s. Blizzards egne versioner kommer helt tilbage efter en genindlæsning.",
	["switches %d modules"] = { one = "skifter %d modul", other = "skifter %d moduler" },
	["Switches back what the last UI amount changed. A module you switched yourself since stays as you set it."] = "Ruller den seneste ændring af UI-mængden tilbage. Et modul du selv har slået til eller fra siden, er som du satte det.",
	["Switches Edit Mode back to the layout you used before the game set it to Modern, out of combat."] = "Skifter Edit Mode tilbage til det layout du brugte før spillet satte det til Modern, uden for kamp.",
	["Switches Edit Mode back to the layout you used before, out of combat."] = "Skifter Edit Mode tilbage til det layout du brugte før, uden for kamp.",
	["Switches off: %s."] = "Slår fra: %s.",
	["Switches on: %s."] = "Slår til: %s.",
	["Switches the modules listed above. Your frames, skin, key bindings and other addons stay as they are."] = "Slår modulerne ovenfor til eller fra. Dine rammer, dit skin, dine genvejstaster og andre addons røres ikke.",
	["Switching style presets keeps your layout tidy, and a damaged saved settings file no longer stops EldoUI from loading."] = "Skift mellem stilpresets holder dit layout ryddeligt, og en beskadiget fil med gemte indstillinger forhindrer ikke længere EldoUI i at blive indlæst.",
	["Symbol of Divinity"] = "Symbol of Divinity",
	["Symbol of Kings"] = "Symbol of Kings",
	["System"] = "System",
	["System %s"] = "System %s",
	["System and settings windows"] = "System- og indstillingsvinduer",
	["Tabard designer"] = "Tabarddesigner",
	["table cut short"] = "tabellen er afkortet",
	["Tabs that already exist with these names are reused. You can rename, move or close them later from the tab's right-click menu, like any chat tab."] = "Faner der allerede findes med disse navne, genbruges. Du kan omdøbe, flytte eller lukke dem senere fra fanens højrekliksmenu, ligesom enhver anden chatfane.",
	["Take back spells"] = "Tag evner tilbage",
	["Take back your last change: a drag, a nudge, a typed position, an attach or a reset. Each click goes one step further back. Ctrl+Z does the same."] = "Tag din seneste ændring tilbage: et træk, et skub, en indtastet position, en fastgørelse eller en nulstilling. Hvert klik går et skridt længere tilbage. Ctrl+Z gør det samme.",
	["Take the class spells this window placed off your bars again. A button you changed since keeps your action."] = "Fjern igen de klasseevner som dette vindue har placeret på dine linjer. En knap du har ændret siden, beholder din handling.",
	["Taken from your execute spell."] = "Hentes fra din execute-evne.",
	["taken off"] = "fjernet",
	["Takes an enemy out for a while: a stun, fear or polymorph."] = "Sætter en fjende ud af spillet et stykke tid: et stun, en fear eller en polymorph.",
	["Takes every spell off Never show and Watch list. Your own lists stay."] = "Fjerner alle evner fra Vis aldrig og Watch list. Dine egne lister bevares.",
	["Takes full effect after a reload."] = "Træder først helt i kraft efter en genindlæsning.",
	["Takes one harmful spell aimed at the group."] = "Opfanger én skadelig evne rettet mod gruppen.",
	["Talent group"] = "Talentgruppe",
	["Talent group %d"] = "Talentgruppe %d",
	["Talent group 1 only"] = "Kun talentgruppe 1",
	["Talent group 2 only"] = "Kun talentgruppe 2",
	["Talent groups"] = "Talentgrupper",
	["Talent planner"] = "Talentplanlægger",
	["Talents"] = "Talenter",
	["Talking head"] = "Talking head",
	["Tank"] = "Tank",
	["Tank and DPS: your target's details on its nameplate, the player frame inside the center column."] = "Tank og DPS: dit måls detaljer på dets nameplate, spillerrammen inde i den midterste kolonne.",
	["Tanking"] = "Tanking",
	["Tanks have Sunder Armor on Rotation 3 of Defensive Stance; your own pick."] = "Tanks har Sunder Armor på Rotation 3 i Defensive Stance; dit eget valg.",
	["Tanks only: a calm color (Colors page) for mobs another tank in your group holds. Only when the game shows that tank's threat."] = "Kun tanks: en rolig farve (siden Farver) for mobs som en anden tank i din gruppe holder. Kun når spillet viser den anden tanks aggro.",
	["Tanks rarely fight in Berserker Stance; your own pick."] = "Tanks kæmper sjældent i Berserker Stance; dit eget valg.",
	["Tapped by someone else"] = "Tagget af en anden",
	["Target change flash"] = "Blink ved skift af mål",
	["Target Frame"] = "Målramme",
	["Target nearest enemy"] = "Vælg nærmeste fjende",
	["Target of Target Frame"] = "Ramme for målets mål",
	["Target, target-of-target and focus frames"] = "Målramme, målets mål og fokusramme",
	["Taunt is the tank's, on the Movement ability button of Defensive Stance; your own pick."] = "Taunt er tankens, på knappen Bevægelsesevne i Defensive Stance; dit eget valg.",
	["Taxi map"] = "Flyvekort",
	["Tells guild and group members who run EldoUI your version in a hidden addon message, never in chat. One chat line when someone has a newer one. Never sent in combat, boss fights or PvP matches."] = "Fortæller guild- og gruppemedlemmer der bruger EldoUI din version i en skjult addonbesked, aldrig i chatten. Én chatlinje når nogen har en nyere. Sendes aldrig i kamp, under bosskampe eller i PvP-kampe.",
	["Ten built-in layouts with clearer names, and EldoUI Center as the new default for new profiles."] = "Ti indbyggede layouts med tydeligere navne og EldoUI Center som ny standard for nye profiler.",
	["Tenths below"] = "Tiendedele under",
	["Test frame"] = "Testramme",
	["Test switch %s is on"] = "Testkontakten %s er slået til",
	["Text"] = "Tekst",
	["Text after it colored by health: green full, yellow half, red low. Works best as the first tag."] = "Teksten efter tagget farves efter liv: grøn ved fuldt liv, gul ved halvt, rød ved lavt. Virker bedst som det første tag.",
	["Text after it in gold for elites, silver for rares, red for bosses."] = "Teksten efter tagget i guld for elites, sølv for rares, rød for bosser.",
	["Text after it in the color of the unit's power (mana blue, rage red ...)."] = "Teksten efter tagget i farven på enhedens ressource (blå for mana, rød for rage ...).",
	["Text after it in the level difficulty color (gray, green, yellow, orange, red)."] = "Teksten efter tagget i levelets sværhedsfarve (grå, grøn, gul, orange, rød).",
	["Text after it in the player's class color."] = "Teksten efter tagget i spillerens klassefarve.",
	["Text after it in the reaction color: red hostile, yellow neutral, green friendly."] = "Teksten efter tagget i reaktionsfarven: rød for fjendtlig, gul for neutral, grøn for venlig.",
	["Text after it in your threat color on this unit: yellow, orange or red."] = "Teksten efter tagget i din aggrofarve på denne enhed: gul, orange eller rød.",
	["Text in the world"] = "Tekst i verden",
	["Text scale"] = "Tekstskala",
	["Text shadow"] = "Tekstskygge",
	["Text size"] = "Tekststørrelse",
	["Text tags"] = "Teksttags",
	["Text tags decide what a unit frame, group frame or nameplate text shows. Mix them with your own text: \"[name:short] [health:percent]\"."] = "Teksttags bestemmer hvad en tekst på en unitframe, grupperamme eller nameplate viser. Bland dem med din egen tekst: \"[name:short] [health:percent]\".",
	["Texts shown without a translation, one per line, ready for a translation file."] = "Tekster der vises uden oversættelse, én pr. linje, klar til en oversættelsesfil.",
	["Texture check"] = "Teksturtjek",
	["Texture check: %d found, %d missing. The full list is in the copy box."] = "Teksturtjek: %d fundet, %d mangler. Den fulde liste står i kopifeltet.",
	["Texture of every EldoUI bar that has no texture of its own. Follow skin uses your skin's bar texture. Textures from SharedMedia packs you have installed are listed under their addon."] = "Tekstur for alle EldoUI-bjælker der ikke har deres egen tekstur. Følg skin bruger dit skins bjælketekstur. Teksturer fra SharedMedia-pakker du har installeret, vises under deres addon.",
	["Textures"] = "Teksturer",
	["Thank you for standing behind EldoUI."] = "Tak fordi I bakker op om EldoUI.",
	["Thank you for the code, research and testing that went into EldoUI."] = "Tak for koden, researchen og testene bag EldoUI.",
	["Thanks"] = "Tak",
	["That is not a filter list string."] = "Det er ikke en filterlistestreng.",
	["That is not a sound file ID or an addon .ogg/.mp3 path."] = "Det er ikke et lydfil-ID eller en .ogg/.mp3-sti i en addon.",
	["That is not an EldoUI filter list string."] = "Det er ikke en filterlistestreng fra EldoUI.",
	["That is the profile you use now; pick another one to copy from."] = "Det er den profil du bruger nu; vælg en anden at kopiere fra.",
	["That journal is gone."] = "Den journal findes ikke længere.",
	["that name isn't allowed in Edit Mode"] = "det navn er ikke tilladt i Edit Mode",
	["That page opens after combat."] = "Siden åbner efter kampen.",
	["That value is no longer set aside."] = "Den værdi er ikke længere lagt til side.",
	["The %s layout with the frames you dragged on profile %s, saved when it became a legacy layout."] = "Layoutet %s med de rammer du har trukket på profilen %s, gemt da det blev et ældre layout.",
	["The %s setup is written to disk with the next reload."] = "Opsætningen af %s skrives til disken ved næste genindlæsning.",
	["the %s step"] = "trinnet %s",
	["The 1440p canvas the layouts are made for, on any screen. Follows your screen if it changes."] = "Det 1440p-lærred som layoutene er lavet til, på enhver skærm. Følger din skærm hvis den skifter.",
	["The accent when Accent color is set to Custom color."] = "Accenten når Accentfarve er sat til Brugerdefineret farve.",
	["The addon that owns the window places it."] = "Den addon der ejer vinduet, placerer det.",
	["The addons the setup turned off are turned on again: %s."] = "De addons opsætningen slog fra, slås til igen: %s.",
	["The Alerts tab keeps its lines between sessions and follows your EldoUI language."] = "Fanen Advarsler gemmer sine linjer mellem sessioner og følger sproget i EldoUI.",
	["The bar page keys (%s) are taken off, so bar 1 never swaps its spells in a fight."] = "Sidetasterne for linjen (%s) fjernes, så linje 1 aldrig skifter sine evner midt i en kamp.",
	["The bar shows all the time. Action Bars > Visibility changes it again."] = "Linjen vises hele tiden. Handlingslinjer > Synlighed ændrer det igen.",
	["The bar stays out of sight, also when you point at it. Its keys still work. Action Bars brings it back."] = "Linjen er skjult, også når du peger på den. Dens taster virker stadig. Handlingslinjer henter den tilbage.",
	["The bar texture, smooth bars and the textures of each module."] = "Bjælketeksturen, glidende bjælker og teksturerne i hvert modul.",
	["The Battleground Timers module shows its own battle start bar next to Blizzard's."] = "Modulet Battleground Timers viser sin egen startbjælke for kampen ved siden af Blizzards.",
	["The big defensive or emergency button."] = "Den store defensive knap eller nødknappen.",
	["the BigWigs integration is off"] = "BigWigs-integrationen er slået fra",
	["The character's realm when it differs from yours."] = "Karakterens realm når den er en anden end din.",
	["The class of a player; empty for NPCs."] = "En spillers klasse; tomt for NPC'er.",
	["The classic look tidied up: satin graphite, a fine bronze double edge and softened corners, with thin portrait rings. Brings the Sand accent while yours is the default blue."] = "Det klassiske udseende, strammet op: satingrafit, en fin dobbelt bronzekant, blødere hjørner og tynde portrætringe. Bruger accenten Sand så længe din er den blå standard.",
	["The Consumable Bar is off, so this key stays free."] = "Forbrugslinjen er slået fra, så denne tast er fri.",
	["The copies needed for this restore exceed the backup size limit. Nothing changed."] = "Kopierne til denne gendannelse overstiger størrelsesgrænsen for sikkerhedskopier. Intet er ændret.",
	["The copy is merged into your journal. Your journal as it was a moment ago is kept as a backup in My Adventure."] = "Kopien er flettet ind i din journal. Din journal som den var for et øjeblik siden, gemmes som en sikkerhedskopi i My Adventure.",
	["The data bars go to it."] = "Databjælkerne placeres i den.",
	["The dungeon map shows the game's minimap large in Live, and WoW: Forever's own dungeons open it with their boss list."] = "Dungeonkortet viser spillets minikort i stor størrelse i Live, og WoW: Forevers egne dungeons åbner det med deres bossliste.",
	["The Edit Mode layout %s no longer exists, so Edit Mode stays on Modern."] = "Edit Mode-layoutet %s findes ikke længere, så Edit Mode bliver på Modern.",
	["The EldoUI font for every EldoUI text that has no font of its own. Languages these fonts lack keep the game font."] = "EldoUI-skrifttypen til al EldoUI-tekst der ikke har sin egen skrifttype. Sprog som disse skrifttyper mangler, beholder spillets skrifttype.",
	["The EldoUI font, text size, outline and shadow, number styles and the fonts of each module."] = "EldoUI-skrifttypen, tekststørrelse, kontur og skygge, talformater og skrifttyperne i hvert modul.",
	["The EldoUI profile"] = "EldoUI-profilen",
	["The error log (/eui errors) with a Report button that leaves out your character's name, realm, guild and chat text."] = "Fejlloggen (/eui errors) med en Rapporter-knap der udelader din karakters navn, realm, guild og chattekst.",
	["The error log: what went wrong in EldoUI, with a copy button for a report."] = "Fejlloggen: hvad der gik galt i EldoUI, med en kopiknap til en rapport.",
	["The familiar original layout: portraits in the corners, a round minimap, one bar row along the bottom and Blizzard's own windows."] = "Det velkendte originale layout: portrætter i hjørnerne, et rundt minikort, én række handlingslinjer langs bunden og Blizzards egne vinduer.",
	["The familiar original layout: portraits in the top left corner, a round minimap top right, the action bars along the bottom with the chat beside them, and the world kept clear."] = "Det velkendte originale layout: portrætter i øverste venstre hjørne, et rundt minikort øverst til højre, handlingslinjerne langs bunden med chatten ved siden af, og verden holdt fri.",
	["The figure only repeats the game's repair alert, so a replacement would add nothing."] = "Figuren gentager kun spillets reparationsadvarsel, så en erstatning ville intet tilføje.",
	["The food types your hunter pet eats."] = "De fodertyper som dit Hunter-pet spiser.",
	["The Forever surname, empty when the character has none (or it is your own and the game hides it)."] = "Forever-efternavnet, tomt når karakteren ikke har et (eller det er dit eget og spillet skjuler det).",
	["The frame art around player, target, pet and the other unit frames: portrait ring or box, bar frame and fill. It never changes positions, sizes, bars or what the portrait shows."] = "Rammegrafikken omkring spiller-, mål-, pet- og de andre unitframes: portrætring eller -boks, bjælkeramme og fyld. Den ændrer aldrig placeringer, størrelser, bjælker eller hvad portrættet viser.",
	["The frame art of party and raid frames: the skin's material and a fine edge. They stay compact, so a full raid keeps its room."] = "Rammegrafikken på gruppe- og raidrammer: skinnets materiale og en fin kant. Rammerne er kompakte, så et fuldt raid beholder sin plads.",
	["The frame drawn around EldoUI's action buttons. The buttons, their keys and what they cast never change."] = "Rammen omkring EldoUI's handlingsknapper. Knapperne, deres taster og det de caster, ændres aldrig.",
	["The frame fades in when it appears, for example a new target, focus or boss. Follows General > Animations."] = "Rammen tones ind når den vises, for eksempel ved et nyt mål, fokus eller en boss. Følger Generelt > Animationer.",
	["the frame links could form a loop"] = "rammeforbindelserne kan danne en løkke",
	["The frame of this options window. Follow skin frames it like every other EldoUI window."] = "Rammen om dette indstillingsvindue. Følg skin rammer det ind som alle andre EldoUI-vinduer.",
	["The frame takes the color."] = "Rammen får farven.",
	["The full list is in chat."] = "Den fulde liste står i chatten.",
	["The game did not have the memory to load EldoUI's saved settings, so this session uses the defaults and the setup stays closed. Turn off some other addons, then reload."] = "Spillet havde ikke hukommelse nok til at indlæse EldoUI's gemte indstillinger, så denne session bruger standardindstillingerne, og opsætningen er lukket. Slå nogle andre addons fra, og genindlæs.",
	["The game doesn't allow chat messages right now."] = "Spillet tillader ikke chatbeskeder lige nu.",
	["The game keeps these four buttons for its own actions."] = "Spillet holder disse fire knapper til sine egne handlinger.",
	["The game set Edit Mode to Modern when its gamepad interface turned off. Restore now switches back to %s."] = "Spillet satte Edit Mode til Modern da dets gamepadinterface blev slået fra. Gendan nu skifter tilbage til %s.",
	["The game's controller bars aren't available right now."] = "Spillets controllerlinjer er ikke tilgængelige lige nu.",
	["The game's controller bars: your class spells in the same order, for play with a controller."] = "Spillets controllerlinjer: dine klasseevner i samme rækkefølge, til spil med en controller.",
	["The game's gamepad interface is off. You can turn it on in the game's Controller settings."] = "Spillets gamepadinterface er slået fra. Du kan slå det til i spillets controllerindstillinger.",
	["The game's own buttons"] = "Spillets egne knapper",
	["The game's own classic frames round the bars: portrait circle, name area and the elite dragon. Made for the Classic frames style (thin bars at the classic proportions beside a portrait box as wide as the plate's portrait side); other frames, and party and raid frames, get the Vanilla look."] = "Spillets egne klassiske rammer omkring bjælkerne: portrætcirkel, navnefelt og elitedragen. Lavet til rammestilen Classic (tynde bjælker i de klassiske proportioner ved siden af en portrætboks lige så bred som pladens portrætside); andre rammer samt gruppe- og raidrammer får Vanilla-udseendet.",
	["The game's own health, power and experience bars show the value and the percent."] = "Spillets egne livs-, ressource- og XP-bjælker viser værdien og procenten.",
	["The game's own Lua error window, which pops up on every error until you close it. Hide keeps it closed; EldoUI still logs every error in /eui errors. Don't touch leaves the game's setting as it is."] = "Spillets eget Lua-fejlvindue: det springer op ved hver fejl indtil du lukker det. Skjul holder det lukket; EldoUI logger stadig alle fejl i /eui errors. Uændret lader spillets indstilling være som den er.",
	["The game's own original frames: the classic player and target plates with the elite dragon (with the Classic frames unit style), the gryphon-capped action bar and the round minimap border. Windows get carved gray stone, a warm brass double line and stone clasps on their corners. Brings the Gold accent while yours is the default blue."] = "Spillets egne originale rammer: de klassiske spiller- og målplader med elitedragen (med unitframestilen Klassiske rammer), handlingslinjen med grifferne i enderne og den runde kant om minikortet. Vinduer får hugget grå sten, en varm dobbeltlinje i messing og stenspænder på hjørnerne. Bruger accenten Guld så længe din er den blå standard.",
	["The game's proc art on buttons, pixel lines everywhere else. Gold for procs."] = "Spillets proc-grafik på knapper, pixellinjer alle andre steder. Guld til procs.",
	["The game's style for your language"] = "Spillets stil for dit sprog",
	["The game's tutorial hints stay away. Turn them back on in the game's Interface settings."] = "Spillets vejledningstips vises ikke. Slå dem til igen i spillets interfaceindstillinger.",
	["The gamepad UI is on, so the key sets stand down: your controller keeps its own buttons."] = "Gamepad-brugerfladen er slået til, så tastesættene holder pause: din controller beholder sine egne knapper.",
	["The glow also pulses slowly. Static with animations off."] = "Gløden pulserer også langsomt. Statisk når animationer er slået fra.",
	["The glow of the execute shade on the Effects page (Glow style)."] = "Gløden fra execute-skyggen på siden Effekter (stilen Glød).",
	["The glow of the low health warning on the Effects page (Glow style)."] = "Gløden fra advarslen om lavt liv på siden Effekter (stilen Glød).",
	["The grid frames snap to, in steps of 4 from 4 to 128. Press Enter to apply."] = "Gitteret rammer fastgøres til, i trin på 4 fra 4 til 128. Tryk Enter for at bruge det.",
	["The HUD fades while nothing happens and comes back when you act. This page sets every module's Visibility at once."] = "HUD'en toner ud når intet sker, og kommer tilbage når du handler. Denne side indstiller alle modulers synlighed på én gang.",
	["The icon breathes and the time turns red."] = "Ikonet pulserer og tiden bliver rød.",
	["The icon breathes."] = "Ikonet pulserer.",
	["The Info Bar adds session gold and XP rates, a group roll tracker and mail information across your characters."] = "Infobjælken får guld og XP pr. time for spilsessionen, en ruloversigt for gruppen og postoplysninger på tværs af dine karakterer.",
	["The Journal can group a boss's loot by kind and shows a branching dungeon quest chain as a flowchart."] = "Journalen kan gruppere en boss' loot efter type og viser en forgrenet dungeonquestkæde som et rutediagram.",
	["The journal kept under %s is removed. It leaves your saved file at your next logout or /reload."] = "Journalen gemt under %s er fjernet. Den forsvinder fra din gemte fil ved næste logout eller /reload.",
	["The journal of %s is back. It is on disk after your next logout or /reload."] = "Journalen for %s er tilbage. Den er gemt på disken efter dit næste logout eller /reload.",
	["The journal of %s is removed. It leaves your saved file at your next logout or /reload."] = "Journalen for %s er fjernet. Den forsvinder fra din gemte fil ved næste logout eller /reload.",
	["the key belongs to a manual bar"] = "tasten hører til en manuel linje",
	["The key sets use the keys in the same places on every keyboard. Pick yours, or let EldoUI guess from the game language."] = "Tastesættene bruger tasterne på de samme pladser på alle tastaturer. Vælg dit, eller lad EldoUI gætte ud fra spillets sprog.",
	["The keys with Alt held: where the game shortcuts a set takes go."] = "Tasterne med Alt-tasten holdt nede: hvor de genveje et sæt tager, flyttes hen.",
	["The keys with Ctrl held."] = "Tasterne med Ctrl holdt nede.",
	["The keys with Shift held."] = "Tasterne med Shift holdt nede.",
	["The keys without a modifier."] = "Tasterne uden ændringstast.",
	["the last hour"] = "den seneste time",
	["the layout needs a name"] = "layoutet skal have et navn",
	["The layout placed %s on its %s spot. Undo leaves it where the addon puts it."] = "Layoutet placerede %s på sin plads til %s. Fortryd lader den blive hvor addonen sætter den.",
	["The layout spots for other addons are off."] = "Layoutpladserne til andre addons er slået fra.",
	["The layout that places your frames: applied as when you pick it on the Layouts page, with its frame sizes."] = "Det layout der placerer dine rammer: anvendt som når du vælger det på siden Layouts, med dets rammestørrelser.",
	["The list in that string has no usable name."] = "Listen i strengen har intet brugbart navn.",
	["The list the rows below edit."] = "Den liste som rækkerne nedenfor redigerer.",
	["The look from the Glows page (Danger: execute range)."] = "Udseendet fra siden Glød (Fare: execute-område).",
	["The look from the Glows page (Danger: low health)."] = "Udseendet fra siden Glød (Fare: lavt liv).",
	["The Loot Guide isn't installed."] = "Loot Guide er ikke installeret.",
	["The lower range comes from your own spell: 20 % with Execute or Hammer of Wrath. Without such a spell, no shade shows."] = "Den nederste grænse kommer fra din egen evne: 20 % med Execute eller Hammer of Wrath. Uden sådan en evne vises ingen skygge.",
	["The materials of a skin that comes in a look per faction. Auto follows your character's faction."] = "Materialerne i et skin der findes i et udseende pr. fraktion. Auto følger din karakters fraktion.",
	["The memory EldoUI uses right now. It is measured when this window opens and each time you point at this line."] = "Den hukommelse EldoUI bruger lige nu. Den måles når vinduet åbner, og hver gang du peger på denne linje.",
	["The mouse wheel stops at this size."] = "Musehjulet stopper ved denne størrelse.",
	["The one switch for every window below. Off: EldoUI leaves every Blizzard window where Blizzard places it, at its own size. Your ticks stay for when you turn it on again."] = "Hovedkontakten for alle vinduer nedenfor. Fra: EldoUI lader alle Blizzard-vinduer være hvor Blizzard placerer dem, i deres egen størrelse. Dine flueben bevares til du slår den til igen.",
	["The options open after combat."] = "Indstillingerne åbner efter kampen.",
	["The original corners in less space: a smaller minimap and chat, smaller bar buttons and no side bars, made for 1080p screens."] = "De originale hjørner på mindre plads: mindre minikort og chat, mindre knapper og ingen sidelinjer, lavet til 1080p-skærme.",
	["The pack is empty."] = "Pakken er tom.",
	["The party as one row and a raid of up to ten as two rows, under the center column above your bars. A larger raid moves beside the center."] = "Gruppen som én række og et raid på op til ti som to rækker, under midterkolonnen over dine handlingslinjer. Et større raid flytter ved siden af midten.",
	["the people who made EldoUI possible"] = "folkene der gjorde EldoUI muligt",
	["The people who made EldoUI possible."] = "Folkene der gjorde EldoUI muligt.",
	["the pet bar"] = "petlinjen",
	["The pet bar moves from Ctrl + the number row to Alt + the number row."] = "Petlinjen flyttes fra Ctrl + talrækken til Alt-tasten + talrækken.",
	["The place this value came from holds something else now. Nothing was changed."] = "Stedet som værdien kom fra, indeholder noget andet nu. Intet blev ændret.",
	["The plain dark panels."] = "De almindelige mørke paneler.",
	["The point of the screen %s is measured from."] = "Det punkt på skærmen som %s måles fra.",
	["The power bar turns the low power color (Colors page) when it drops below the value you set. Handy for keeping an eye on a healer's mana."] = "Kraftbjælken får farven for lav kraft (siden Farver) når den falder under den værdi du vælger. Praktisk til at holde øje med en healers mana.",
	["The preview changes the UI at once. Back or closing this window puts your old scale back. You can change it later in /eui > General or with /eui scale."] = "Eksemplet ændrer UI'et med det samme. Klikker du på Tilbage eller lukker vinduet, får du din gamle skala tilbage. Du kan ændre den senere i /eui > Generelt eller med /eui scale.",
	["The profile %s exists. %s Starting it fresh resets its layout, styles and settings for every character that uses it."] = "Profilen %s findes. %s Starter du den forfra, nulstilles dens layout, stile og indstillinger for alle karakterer der bruger den.",
	["The profile %s was deleted."] = "Profilen %s blev slettet.",
	["The profile a new character of each class starts with on its first login with EldoUI. Characters that already have a profile keep it."] = "Den profil en ny karakter af hver klasse starter med ved sit første login med EldoUI. Karakterer der allerede har en profil, beholder den.",
	["The profile changes after combat."] = "Profilen skifter efter kampen.",
	["the profile for your class"] = "profilen til din klasse",
	["The profile this character uses. Every character can use any profile."] = "Den profil som denne karakter bruger. Alle karakterer kan bruge en hvilken som helst profil.",
	["The profile you last picked"] = "Den profil du sidst valgte",
	["The quest icon pops in when a unit becomes part of one of your quests."] = "Questikonet popper frem når en enhed bliver en del af en af dine quests.",
	["The quest log is part of the world map, so hiding it on its own makes no sense."] = "Questloggen er en del af verdenskortet, så det giver ingen mening at skjule den alene.",
	["The range is tinted."] = "Området bliver tonet.",
	["The red time text starts at this many seconds left."] = "Tidsteksten bliver rød når der er så mange sekunder tilbage.",
	["The ring or border around the minimap. A minimap without a border keeps none."] = "Ringen eller kanten omkring minikortet. Et minikort uden kant får ingen.",
	["The role layer in use. No role leaves the layout as it is. Switching role puts back what the previous role changed, unless you changed it yourself since."] = "Rollelaget i brug. Ingen rolle lader layoutet være som det er. Skifter du rolle, gendannes det som den forrige rolle ændrede, medmindre du selv har ændret det siden.",
	["The role picked in the group: Tank, Healer or Damage."] = "Rollen valgt i gruppen: Tank, Healer eller Damage.",
	["The safe area is off, or this screen is not wider than it."] = "Det sikre område er slået fra, eller skærmen er ikke bredere end det.",
	["The settings from %s stopped arriving and were dropped."] = "Indstillingerne fra %s holdt op med at komme frem og blev kasseret.",
	["The setup again: scale, layout, look, role and chat. It asks before it changes anything."] = "Opsætningen igen: skala, layout, udseende, rolle og chat. Den spørger før den ændrer noget.",
	["The setup change waits for the end of combat."] = "Ændringen af opsætningen venter til kampen slutter.",
	["The setup is done. Closes this page and asks for a reload only if a change needs one."] = "Opsætningen er færdig. Lukker denne side og beder kun om en genindlæsning hvis en ændring kræver det.",
	["The setup opens after combat."] = "Opsætningen åbner efter kampen.",
	["The setup opens again after the reset."] = "Opsætningen åbner igen efter nulstillingen.",
	["The setup's Role step lists them for your class."] = "Opsætningens Rolle-trin viser dem for din klasse.",
	["The shade starts once health is under this percent."] = "Skyggen starter når livet er under denne procent.",
	["The shop and secure transfers are protected, so they stay Blizzard's."] = "Butikken og sikre overførsler er beskyttede, så de er stadig Blizzards.",
	["The shown entry as a bug report to copy, with a link to the bug form. Nothing is sent by itself."] = "Den viste post som en fejlrapport du kan kopiere, med et link til fejlformularen. Intet sendes af sig selv.",
	["The side buttons hold bar 1 and Shift + the side buttons bar 2. Bar 3 sits on the keys around your movement hand."] = "Sideknapperne har linje 1 og Shift + sideknapperne linje 2. Linje 3 sidder på tasterne omkring din bevægelseshånd.",
	["The skin of your whole UI and of each part. A skin never moves frames or turns modules on or off."] = "Skin til hele dit UI og til hver del. Et skin flytter aldrig rammer og slår aldrig moduler til eller fra.",
	["The skin's material behind the bars, its border round the frame and a round portrait ring."] = "Skinnets materiale bag bjælkerne, dets kant omkring rammen og en rund portrætring.",
	["The sound to play. General > Sounds has the volume channel."] = "Lyden der afspilles. Under Generelt > Lyde vælger du lydkanalen.",
	["the spot is in use"] = "pladsen er i brug",
	["the stance bar"] = "stance-linjen",
	["The status icon breathes while a resurrection or summon is on its way."] = "Statusikonet pulserer blødt mens en genoplivning eller summon er på vej.",
	["the string"] = "strengen",
	["the string has characters an EllesmereUI string can't have"] = "strengen indeholder tegn som en EllesmereUI-streng ikke kan have",
	["the string has characters an ElvUI string can't have"] = "strengen indeholder tegn som en ElvUI-streng ikke kan have",
	["the string holds no profile"] = "strengen indeholder ingen profil",
	["the string is damaged"] = "strengen er beskadiget",
	["the string is damaged (no ElvUI type marker)"] = "strengen er beskadiget (ingen ElvUI-typemarkør)",
	["the string is damaged or cut short"] = "strengen er beskadiget eller afkortet",
	["the string is damaged or cut short. Copy it again in full."] = "strengen er beskadiget eller afkortet. Kopier den igen i sin helhed.",
	["the string is too long"] = "strengen er for lang",
	["The string is too long."] = "Strengen er for lang.",
	["The Talent Planner with Import build, Training, and lower spell ranks lit on your bars."] = "Talentplanlæggeren med Importer build, Træning og evner i lavere rang oplyst på dine handlingslinjer.",
	["The threat glow on unit frames and nameplates (Effects, Threat border with the Glow style). The game's threat state turns it on."] = "Aggrogløden på unitframes og nameplates (Effekter, Aggrokant med stilen Glød). Spillets aggrotilstand slår den til.",
	["The time turns red."] = "Tiden bliver rød.",
	["The tint shows while power is under this percent."] = "Farvetonen vises mens ressourcen er under denne procent.",
	["The title bar"] = "Titellinjen",
	["The totem bar with a loadout for your role, the cooldown bar, shield and imbue reminders, totem squares on party frames for healers, and an Ankh counter and restock"] = "Totemlinjen med et loadout til din rolle, cooldownlinjen, påmindelser om skjold og imbue, totemfelter på grupperammer til healere samt en Ankh-tæller med genopfyldning",
	["The Tour helps switch and the tour helps already shown."] = "Kontakten Førstegangshjælp og den førstegangshjælp der allerede er vist.",
	["The UI scale choice shows which scales the layouts are made for, with Auto recommended."] = "Valget af UI-skala viser hvilke skalaer layoutene er lavet til, med Auto som det anbefalede.",
	["The undo runs when combat ends."] = "Fortrydelsen kører når kampen er slut.",
	["The unit's absorb shield over the health bar. Color on the Colors page."] = "Enhedens absorberingsskjold over livsbjælken. Farven vælger du på siden Farver.",
	["The unit's level; ?? when the game hides it."] = "Enhedens level; ?? når spillet skjuler det.",
	["The unit's name in the Name format (General page, or this module's own choice there). [name:short] / [name:medium] / [name:long] cut it to 10 / 15 / 20 letters, [name:N] to N letters (counted after the format; accents and other alphabets are kept whole), [name:abbrev] shortens all but the last word (\"C. K. Seaclaw\")."] = "Enhedens navn efter indstillingen Navneformat (siden Generelt eller modulets eget valg der). [name:short] / [name:medium] / [name:long] afkorter det til 10 / 15 / 20 bogstaver, [name:N] til N bogstaver (talt efter formatet; accenter og andre alfabeter bevares hele), [name:abbrev] forkorter alle ord undtagen det sidste (\"C. K. Seaclaw\").",
	["The unit's raid group number (1-8); empty outside raids."] = "Enhedens raidgruppenummer (1-8); tomt uden for raids.",
	["the update could not finish and runs again at your next login"] = "opdateringen kunne ikke gøres færdig og kører igen ved dit næste login",
	["The versions from 0.5.0 to 0.6.6005 in short: what they brought that is still in EldoUI."] = "Versionerne fra 0.5.0 til 0.6.6005 kort fortalt: det de bragte med sig og som stadig findes i EldoUI.",
	["The warning pulses slowly. Static with animations off."] = "Advarslen pulserer langsomt. Statisk når animationer er slået fra.",
	["The warning shows while the unit's health is under this percent."] = "Advarslen vises mens enhedens liv er under denne procent.",
	["The whole module"] = "Hele modulet",
	["The whole profile as a readable Lua table, for bug reports and comparing setups."] = "Hele profilen som en læsbar Lua-tabel, til fejlrapporter og til at sammenligne opsætninger.",
	["The whole profile as one string."] = "Hele profilen som én streng.",
	["The whole profile or one part of it."] = "Hele profilen eller én del af den.",
	["Theme font"] = "Temaskrifttype",
	["Theme font, number format, the game's own fonts and every module's font in one place."] = "Temaskrifttype, talformat, spillets egne skrifttyper og alle modulers skrifttyper samlet ét sted.",
	["There are no new spells to take off your bars."] = "Der er ingen nye evner at tage af dine linjer.",
	["There are no spells from the last fill to take off."] = "Der er ingen evner fra den seneste udfyldning at fjerne.",
	["there is no copy of that any more."] = "der er ikke længere nogen kopi af det.",
	["There is no keybind backup for this character."] = "Der er ingen sikkerhedskopi af genvejstaster for denne karakter.",
	["There is no profile %q. /eui profile list shows them."] = "Der findes ingen profil %q. /eui profile list viser dem.",
	["There is no setup change to undo on this profile."] = "Der er ingen ændring af opsætningen at fortryde på denne profil.",
	["There is no setup to undo on this character."] = "Der er ingen opsætning at fortryde på denne karakter.",
	["There is nothing to check yet: choose a key set first."] = "Der er intet at tjekke endnu: vælg et tastesæt først.",
	["There is nothing to put back on this character."] = "Der er intet at gendanne på denne karakter.",
	["These addons run next to EldoUI without drawing the same thing twice, so nothing stands back. EldoUI does their job too, in full or in part."] = "Disse addons kører ved siden af EldoUI uden at tegne det samme to gange, så intet træder til side. EldoUI dækker også deres funktion, helt eller delvist.",
	["These are developer tools you open on purpose."] = "Det er udviklerværktøjer du selv åbner.",
	["These are settings from the game's own options window (Esc > Options). They only change how things look or read: nothing here plays for you.\n\nA setting the game already uses shows as set and is not written again. EldoUI remembers your value before it changes one, so Blizzard default in /eui puts it back.\n\nA second run starts with nothing checked, so clicking through changes nothing."] = "Det er indstillinger fra spillets eget indstillingsvindue (Esc > Options). De ændrer kun hvordan ting ser ud eller læses: intet her spiller for dig.\n\nEn indstilling som spillet allerede bruger, vises som sat og skrives ikke igen. EldoUI husker din værdi før den ændrer en, så Blizzard-standard i /eui gendanner den.\n\nEn ny kørsel starter uden noget afkrydset, så det ændrer intet at klikke sig igennem.",
	["Thick"] = "Tyk",
	["Thickness"] = "Tykkelse",
	["Thin"] = "Tynd",
	["Thin lines that run round the frame in the accent color."] = "Tynde linjer der løber rundt om rammen i accentfarven.",
	["This can't be undone."] = "Dette kan ikke fortrydes.",
	["this character"] = "denne karakter",
	["This character"] = "Denne karakter",
	["This character gets"] = "Denne karakter får",
	["This character goes back to profile %s, as before the alt setup of %s, and its chat tabs, game settings, click-casting and class spells go back too. Profile %s stays as it is, and other addons' profiles stay as they are."] = "Karakteren vender tilbage til profilen %s som før opsætningen til alts den %s, og dens chatfaner, spilindstillinger, klikkast og klasseevner vender også tilbage. Profilen %s røres ikke, og andre addons' profiler røres ikke.",
	["This character goes back to profile %s, as before the alt setup of %s, and its chat tabs, game settings, click-casting and class spells go back too. The copy %s made for it is deleted, and other addons' profiles stay as they are."] = "Karakteren vender tilbage til profilen %s som før opsætningen til alts den %s, og dens chatfaner, spilindstillinger, klikkast og klasseevner vender også tilbage. Kopien %s der blev lavet til den, slettes, og andre addons' profiler røres ikke.",
	["This character uses %s with its %s role layer, like the other characters on it."] = "Karakteren bruger %s med dens rollelag %s, ligesom de andre karakterer på den.",
	["This character uses profile %s again, as before the alt setup. Reload to finish?"] = "Karakteren bruger profilen %s igen som før opsætningen til alts. Vil du genindlæse for at afslutte?",
	["This character uses profile %s now."] = "Karakteren bruger nu profilen %s.",
	["This character's keys match your key set."] = "Denne karakters taster passer til dit tastesæt.",
	["This character's own chat windows: the tabs are made and filled the way the setup's Chat step does it."] = "Karakterens egne chatvinduer: fanerne laves og fyldes som opsætningens trin Chat gør det.",
	["This client has no test switch for combat restrictions."] = "Denne klient har ingen testkontakt til kampbegrænsninger.",
	["This EldoUI (%s) is older than the plugin needs. Update EldoUI."] = "Denne EldoUI (%s) er ældre end pluginnet kræver. Opdater EldoUI.",
	["This error as a bug report to copy, with a link to the bug form. Nothing is sent by itself."] = "Denne fejl som en fejlrapport du kan kopiere, med et link til fejlformularen. Intet sendes af sig selv.",
	["this game client can't read Base64 strings"] = "denne spilklient kan ikke læse Base64-strenge",
	["this game client can't read CBOR data"] = "denne spilklient kan ikke læse CBOR-data",
	["this game client can't unpack compressed strings"] = "denne spilklient kan ikke pakke komprimerede strenge ud",
	["this game client has no Edit Mode import"] = "denne spilklient har ingen Edit Mode-import",
	["this game client has no Edit Mode layouts"] = "denne spilklient har ingen Edit Mode-layouts",
	["This is a talent build (a talent calculator link or a talent loadout string). The Talent Planner reads it: paste it in the planner's Import box, or type /eui talents import followed by it."] = "Dette er et talentbuild (et link fra en talentberegner eller en loadout-streng). Talentplanlæggeren kan læse det: indsæt det i planlæggerens importfelt, eller skriv /eui talents import efterfulgt af det.",
	["this is an EllesmereUI %q string, not a profile"] = "dette er en EllesmereUI-streng af typen %q, ikke en profil",
	["this is an ElvUI %q export; only profile exports hold a layout"] = "dette er en ElvUI-eksport af typen %q; kun profileksporter indeholder et layout",
	["this is an old EllesmereUI cooldown-manager string, which EllesmereUI no longer reads either"] = "dette er en gammel EllesmereUI-streng til Cooldown Manager; EllesmereUI kan heller ikke selv læse den længere",
	["This is ElvUI's \"Table\" export, which is Lua code. EldoUI never runs pasted code: export the profile again in ElvUI with the normal (compressed) format."] = "Dette er ElvUI's \"Table\"-eksport og består af Lua-kode. EldoUI kører aldrig indsat kode: eksporter profilen igen i ElvUI med det normale (komprimerede) format.",
	["this is not an EldoUI string"] = "dette er ikke en EldoUI-streng",
	["This key set"] = "Dette tastesæt",
	["This key set is not there any more."] = "Dette tastesæt findes ikke længere.",
	["This key types nothing"] = "Denne tast skriver intet",
	["This layout keeps bar %d out of sight. Point at it out of combat to use it; its keys work any time."] = "Dette layout holder linje %d skjult. Peg på den uden for kamp for at bruge den; dens taster virker altid.",
	["This layout keeps the healer group frames beside the center."] = "Dette layout beholder healerens grupperammer ved siden af midten.",
	["This login"] = "Dette login",
	["This look uses your layout."] = "Dette udseende bruger dit layout.",
	["This module is not loaded."] = "Modulet er ikke indlæst.",
	["This module is off."] = "Modulet er slået fra.",
	["This module's setting; the module's own page shows the same value."] = "Modulets indstilling; modulets egen side viser den samme værdi.",
	["This plan was made for another character. Look at the preview again."] = "Denne plan blev lavet til en anden karakter. Se forhåndsvisningen igen.",
	["This point-linked layout cannot be imported: %s. Nothing was changed."] = "Dette layout med sammenkædede punkter kan ikke importeres: %s. Intet blev ændret.",
	["This profile"] = "Denne profil",
	["This profile is set up already, so Apply keeps its scale, layout, look, role, Blizzard UI switches and convenience features, and sets up this character's chat tabs, game settings and other addons' profiles."] = "Denne profil er allerede sat op, så Anvend beholder dens skala, layout, udseende, rolle, Blizzard-UI-kontakter og bekvemmelighedsfunktioner og sætter denne karakters chatfaner, spilindstillinger og andre addons' profiler op.",
	["This session"] = "Denne session",
	["this session, %s"] = "denne session, %s",
	["This skin has one look."] = "Dette skin har ét udseende.",
	["This string doesn't say which game it was made for. EldoUI reads it as a WoW: Forever layout: positions, sizes and visibility carry over. Skipped: %s."] = "Denne streng angiver ikke hvilket spil den er lavet til. EldoUI læser den som et WoW: Forever-layout: placeringer, størrelser og synlighed overføres. Sprunget over: %s.",
	["This string holds a list your EldoUI doesn't have (%s)."] = "Denne streng indeholder en liste som din EldoUI ikke har (%s).",
	["This string is for the %s module, which isn't installed."] = "Denne streng er til modulet %s som ikke er installeret.",
	["This string was made for another version of the game (%s), not WoW: Forever. EldoUI imports what Forever has: positions, sizes and visibility. Skipped: %s."] = "Denne streng er lavet til en anden version af spillet (%s), ikke WoW: Forever. EldoUI importerer det Forever har: placeringer, størrelser og synlighed. Sprunget over: %s.",
	["This window can't be moved or scaled in combat."] = "Vinduet kan ikke flyttes eller skaleres i kamp.",
	["thousand"] = "tusind",
	["Threat"] = "Aggro",
	["Threat border"] = "Aggrokant",
	["Threat colors and the threat meter."] = "Aggrofarver og aggromåleren.",
	["Threat colors on nameplates and EldoUI's threat meter at its placed spot. Main tank frames show in raids. Nothing else moves."] = "Aggrofarver på nameplates og EldoUI's aggromåler på sin faste plads. Rammer til main tanks vises i raids. Intet andet flytter sig.",
	["Thursday"] = "torsdag",
	["Time left"] = "Tid tilbage",
	["Tint"] = "Farvetone",
	["To"] = "Til",
	["To keep your saved file small, EldoUI let go of its %d oldest backup copies. Your journal's newest copy from before an update is always kept."] = { one = "For at holde din gemte fil lille har EldoUI fjernet sin ældste sikkerhedskopi. Den nyeste kopi af din journal fra før en opdatering beholdes altid.", other = "For at holde din gemte fil lille har EldoUI fjernet sine %d ældste sikkerhedskopier. Den nyeste kopi af din journal fra før en opdatering beholdes altid." },
	["Toasts, banners, talking head, raid warnings, red error text, zone text, ready check and pop-ups, tutorials."] = "Pop op-beskeder, bannere, talking head, raidadvarsler, rød fejltekst, zonetekst, klar-tjek og pop op-vinduer, vejledninger.",
	["Too large for the %s layout's spots."] = "For stor til pladserne i layoutet %s.",
	["Too large for the %s layout: it would cover the %s."] = "For stor til layoutet %s: den ville dække %s.",
	["Tools"] = "Værktøjer",
	["Tooltips"] = "Tooltips",
	["Top"] = "Øverst",
	["top"] = "øverst",
	["Top left"] = "Øverst til venstre",
	["top left"] = "øverst til venstre",
	["Top right"] = "Øverst til højre",
	["top right"] = "øverst til højre",
	["Totem and shield reminders"] = "Påmindelser om totems og skjolde",
	["Totem bar for your role, reminders and an Ankh counter"] = "Totemlinje til din rolle, påmindelser og en Ankh-tæller",
	["Totem loadout: %s"] = "Totem-loadout: %s",
	["Totem nameplates"] = "Nameplates for totems",
	["Totem range"] = "Totemrækkevidde",
	["Totem slots can hold hidden combat data, so EldoUI moves and skins Blizzard's own totem bar instead."] = "Totempladser kan rumme skjulte kampdata, så EldoUI flytter og giver Blizzards egen totemlinje skin i stedet.",
	["Tour helps"] = "Førstegangshjælp",
	["Tour helps explain new parts of EldoUI the first time you meet them, and a new character on an account you already set up gets one short page instead of the whole setup."] = "Førstegangshjælp forklarer nye dele af EldoUI første gang du møder dem, og en ny karakter på en konto du allerede har sat op, får én kort side i stedet for hele opsætningen.",
	["Tour helps explain new things once, like this one. Turn them off here; Show tour helps again brings them back."] = "Førstegangshjælp som denne forklarer nye ting én gang. Slå den fra her; Vis førstegangshjælp igen henter den tilbage.",
	["Tour helps: /eui tour %s, or /eui tour reset to see them all again."] = "Førstegangshjælp: /eui tour %s, eller /eui tour reset for at se det hele igen.",
	["Tracked Buffs"] = "Sporede buffs",
	["Tracked buffs"] = "Sporede buffs",
	["Trade"] = "Byt",
	["Trade window"] = "Byttevindue",
	["Trades health for mana."] = "Bytter liv til mana.",
	["Trainer"] = "Træner",
	["Tranquility is the healer's; your own pick."] = "Tranquility er healerens; dit eget valg.",
	["Transmogrify"] = "Transmogrificering",
	["Trav"] = "Rejs",
	["Travel"] = "Rejse",
	["Travel Form and Aquatic Form are on the stance bar."] = "Travel Form og Aquatic Form ligger på stance-linjen.",
	["trillion"] = "bio.",
	["Tritanopia (blue)"] = "Tritanopi (blå)",
	["Trivial"] = "Triviel",
	["Troubleshooting"] = "Fejlfinding",
	["Try it"] = "Prøv det",
	["Try tags"] = "Prøv tags",
	["Tuesday"] = "tirsdag",
	["Turn"] = "Drej",
	["Turn all off"] = "Slå alle fra",
	["Turn all on"] = "Slå alle til",
	["Turn every %s switch off and put your own game settings back?"] = "Slå alle kontakter under %s fra og sæt dine egne spilindstillinger tilbage?",
	["Turn every switch off and put your own game settings back. If a part needs a reload to look like Blizzard's again, you are asked once."] = "Slå alle kontakter fra og sæt dine egne spilindstillinger tilbage. Kræver en del en genindlæsning for at ligne Blizzards igen, bliver du spurgt én gang.",
	["Turn every switch on this tab off and put your own game settings back."] = "Slå alle kontakter på denne fane fra og sæt dine egne spilindstillinger tilbage.",
	["Turn every switch on this tab off and put your own game settings back? The choices you made on this tab are lost."] = "Slå alle kontakter på denne fane fra og sæt dine egne spilindstillinger tilbage? Dine valg på denne fane går tabt.",
	["Turn it on on the Modules page (%s), or type %s."] = "Slå det til på siden Moduler (%s), eller skriv %s.",
	["Turn off"] = "Slå fra",
	["Turn off %s"] = "Slå %s fra",
	["Turn off the bar page keys"] = "Slå sidetasterne for linjen fra",
	["Turn on"] = "Slå til",
	["Turn on \"%s\" first."] = "Slå \"%s\" til først.",
	["Turn on %s"] = "Slå %s til",
	["Turn on Blizzard UI > %s first."] = "Slå Blizzard-UI > %s til først.",
	["Turn on Blizzard UI > %s: %s first."] = "Slå Blizzard-UI > %s: %s til først.",
	["Turn on the %s module first."] = "Slå modulet %s til først.",
	["Turn on the Consumable Bar"] = "Slå Forbrugslinjen til",
	["Turn on the resources and frames your class uses (combo points, form mana, totem timers, pet frames)."] = "Slå de ressourcer og rammer til som din klasse bruger (combopoints, mana i former, totemnedtællinger, petrammer).",
	["Turn on the resources, reminders and spells your class uses, on top of the role."] = "Slå de ressourcer, påmindelser og evner til som din klasse bruger, oven på rollen.",
	["Turning it off takes full effect after a reload."] = "Slås det fra, træder det først helt i kraft efter en genindlæsning.",
	["Turns %s off for this character, after a reload, and EldoUI does all of its jobs."] = "Slår %s fra for denne karakter efter en genindlæsning, og EldoUI overtager alle dens funktioner.",
	["Turns %s off for this character, after a reload, so EldoUI's %s runs."] = "Slår %s fra for denne karakter efter en genindlæsning, så EldoUI's %s kører.",
	["Turns on Large text at the size named above. Undo puts back what you had."] = "Slår Stor tekst til i størrelsen ovenfor. Fortryd sætter det tilbage, du havde.",
	["Turns the enemy into a sheep; damage breaks it."] = "Forvandler fjenden til et får; skade bryder det.",
	["Turns the note off for good. The switch on the What's new page turns it back on."] = "Slår noten fra for altid. Kontakten på siden Nyheder slår den til igen.",
	["Turns the paging off on those bars and shows the keys on bars 1 to 3. The paging can be changed back on the Action Bars page, the keys on the Keybinds page."] = "Slår sideskiftet fra på de linjer og viser tasterne på linje 1 til 3. Sideskiftet kan ændres tilbage på siden Handlingslinjer, tasterne på siden Genvejstaster.",
	["Tutorials, help tips and cinematic frames"] = "Vejledninger, hjælpetip og filmsekvensrammer",
	["Twin Orbs"] = "Twin Orbs",
	["Twin Orbs (1440p)"] = "Twin Orbs (1440p)",
	["Twin Orbs adds an eleventh layout, with health and power orbs, a shared action-bar tray and the Infernal Stone skin."] = "Twin Orbs tilføjer et ellevte layout med orber til liv og ressourcer, en fælles bakke til handlingslinjerne og skinnet Infernal Stone.",
	["Two things get in the way of your keys:"] = "To ting står i vejen for dine taster:",
	["Type"] = "Type",
	["Type %s in chat or use the EldoUI button in the Game Menu to open the EldoUI options."] = "Skriv %s i chatten eller brug EldoUI-knappen i spilmenuen for at åbne EldoUI's indstillinger.",
	["Type %s to choose."] = "Skriv %s for at vælge.",
	["Type /eui locale track first, then open the pages you want to check."] = "Skriv /eui locale track først, og åbn så de sider du vil tjekke.",
	["Type /reload after combat to apply this."] = "Skriv /reload efter kampen for at aktivere ændringen.",
	["Type a name and press Enter. New lists start as block lists."] = "Skriv et navn og tryk Enter. Nye lister starter som blokeringslister.",
	["Type a name and press Enter: a new profile with default settings, used by this character from now on."] = "Skriv et navn og tryk Enter: en ny profil med standardindstillinger som denne karakter bruger fra nu af.",
	["Type a new name and press Enter. Built-in lists keep their name."] = "Skriv et nyt navn og tryk Enter. Indbyggede lister beholder deres navn.",
	["Type a new name for this profile and press Enter. Characters, profile rules and class defaults follow the new name."] = "Skriv et nyt navn til denne profil og tryk Enter. Karakterer, profilregler og klassestandarder følger det nye navn.",
	["Type and press Enter to search."] = "Skriv og tryk Enter for at søge.",
	["Type tags and press Enter to see the result below."] = "Skriv tags og tryk Enter for at se resultatet nedenfor.",
	["Type these in chat. Words in <> are yours to fill in. /eui help <command> shows one."] = "Skriv disse i chatten. Ord i <> udfylder du selv. /eui help <command> forklarer én kommando.",
	["UI amount"] = "UI-mængde",
	["UI amount as set"] = "UI-mængde som indstillet",
	["UI amount: %s"] = "UI-mængde: %s",
	["UI amount: %s (%s)"] = "UI-mængde: %s (%s)",
	["UI amount: %s, %s."] = "UI-mængde: %s, %s.",
	["UI amount: %s, your modules already match it."] = "UI-mængde: %s, dine moduler matcher den allerede.",
	["UI amount: stays as set."] = "UI-mængde: er som indstillet.",
	["UI scale"] = "UI-skala",
	["UI scale is %s (%.4f). Use %s (1440p), %s or a number from 0.4 to 1.2."] = "UI-skalaen er %s (%.4f). Brug %s (1440p), %s eller et tal fra 0.4 til 1.2.",
	["UI scale set to %.4f."] = "UI-skala sat til %.4f.",
	["UI scale: %s"] = "UI-skala: %s",
	["UI scale: keep"] = "UI-skala: behold",
	["UI widgets (top center, below minimap, encounter power bar)"] = "UI-widgets (øverst i midten, under minikortet, encounter-ressourcebjælke)",
	["UK"] = "UK",
	["UK English keyboard (ISO): a tall Enter key and a key left of Z."] = "Britisk engelsk tastatur (ISO): en høj Enter-tast og en tast til venstre for Z.",
	["Uncheck every module below: each one goes back to the visibility it had before."] = "Fjern fluebenet ved alle moduler nedenfor: hvert modul går tilbage til den synlighed det havde før.",
	["Undo"] = "Fortryd",
	["Undo all"] = "Fortryd alle",
	["Undo changes"] = "Fortryd ændringer",
	["Undo for layout, pack and setup changes keeps the last three changes of each profile across reloads."] = "Fortryd gemmer de seneste tre ændringer af layout, pakke og opsætning for hver profil, også efter en genindlæsning.",
	["Undo last"] = "Fortryd seneste",
	["Undo last (Ctrl+Z) brings them back."] = "Fortryd seneste (Ctrl+Z) bringer dem tilbage.",
	["Undo last key set"] = "Fortryd sidste tastesæt",
	["Undo last setup change"] = "Fortryd seneste opsætningsændring",
	["Undo the last setup"] = "Fortryd den seneste opsætning",
	["Undo the restore of %s? It goes back to how it was just before, and what it holds now is kept in its place."] = "Vil du fortryde gendannelsen af %s? Den bliver som den var lige før, og det den indeholder nu, gemmes i stedet.",
	["Undo the setup?"] = "Vil du fortryde opsætningen?",
	["Undo the whole setup"] = "Fortryd hele opsætningen",
	["Undo the whole setup puts it back"] = "Fortryd hele opsætningen sætter det tilbage",
	["Undo UI amount"] = "Fortryd UI-mængde",
	["Undo waits for the end of combat."] = "Fortryd venter til kampen slutter.",
	["Undoes the previews and pauses the setup. /eui install goes on where you stopped."] = "Fortryder eksemplerne og sætter opsætningen på pause. /eui install fortsætter hvor du slap.",
	["Undone: %s."] = "Fortrudt: %s.",
	["Unfriendly"] = "Unfriendly",
	["Unhide"] = "Vis igen",
	["Unit frames"] = "Unitframes",
	["Unit Frames"] = "Unitframes",
	["Unit frames, group frames, action bars, chat and windows keep their own switches on their pages."] = "Unitframes, grupperammer, handlingslinjer, chat og vinduer har deres egne kontakter på deres sider.",
	["Unit frames, nameplates and auras"] = "Unitframes, nameplates og auraer",
	["Unit states and effects"] = "Enhedstilstande og effekter",
	["Unit, party and raid frames, nameplates and eight action bars, with unit-frame graphics in your skin's materials."] = "Unitframes, grupperammer og raidrammer, nameplates og otte handlingslinjer, med unitframe-grafik i dit skins materialer.",
	["Unit, party, raid and boss frames, cast bar, class resources, buffs, private auras and nameplates. Secure: they change out of combat."] = "Unitframes, gruppe-, raid- og bossrammer, castbar, klasseressourcer, buffs, private auraer og nameplates. Beskyttede: de ændres kun uden for kamp.",
	["Unit-frame graphics"] = "Unitframe-grafik",
	["Unit-frame graphics are not available in this version."] = "Unitframe-grafik er ikke tilgængelig i denne version.",
	["Unit-frame graphics: %s"] = "Grafik til unitframes: %s",
	["Unknown addon"] = "Ukendt addon",
	["Unknown category. Try all, general, positions, global, a module name from /eui modules, or one of these lists: %s."] = "Ukendt kategori. Prøv all, general, positions, global, et modulnavn fra /eui modules eller en af disse lister: %s.",
	["Unknown command %q. Did you mean %s/eui %s|r? %s lists everything."] = "Ukendt kommando %q. Mente du %s/eui %s|r? %s viser alt.",
	["Unknown command %q. Type %s for the full list."] = "Ukendt kommando %q. Skriv %s for hele listen.",
	["unknown tag %s"] = "ukendt tag %s",
	["unknown tag at %d"] = "ukendt tag ved %d",
	["Unlock EldoUI's frames so you can drag them. It opens on your fight screen (Combat mode); pick All frames or a group on the move panel for the rest. Done in move mode brings this window back."] = "Lås EldoUI's rammer op så du kan trække dem. Flyttetilstand åbner på din kampskærm (Kamptilstand); vælg Alle rammer eller en gruppe i flyttepanelet for resten. Færdig i flyttetilstand bringer dette vindue tilbage.",
	["Unlock every EldoUI frame to drag it into place. This window steps aside until you press Done."] = "Lås alle EldoUI-rammer op så du kan trække dem på plads. Vinduet træder til side indtil du trykker på Færdig.",
	["Until it is on, %s stay free; then they use your potion, healthstone, and mana potion or bandage."] = "Indtil den er slået til, er %s frie; derefter bruger de din potion, healthstone og mana potion eller bandage.",
	["Until the window closes"] = "Indtil vinduet lukkes",
	["Until you log out"] = "Indtil du logger ud",
	["Up from the screen point in the title to the same point of the frame: a higher number moves it up, a lower one down. Press Enter to apply."] = "Lodret fra skærmpunktet i titlen til samme punkt på rammen: et højere tal flytter den op, et lavere ned. Tryk Enter for at bruge det.",
	["Update"] = "Opdater",
	["updated from version %d to %d"] = "opdateret fra version %d til %d",
	["Upgrade spell ranks automatically"] = "Opgrader evnerang automatisk",
	["upright, %d columns"] = { one = "lodret, %d kolonne", other = "lodret, %d kolonner" },
	["US"] = "US",
	["US English keyboard (ANSI): a long Shift key, no key left of Z."] = "Amerikansk engelsk tastatur (ANSI): en lang Shift-tast, ingen tast til venstre for Z.",
	["Usable area"] = "Brugbart område",
	["Usage: /eui data [list | restore <part> [<name>] | follow <part> [<name>]]"] = "Brug: /eui data [list | restore <part> [<name>] | follow <part> [<name>]]",
	["Usage: /eui profile list | use <name> | new <name> | copy <from> | reset | delete <name>"] = "Brug: /eui profile list | use <name> | new <name> | copy <from> | reset | delete <name>", -- l10n: keep
	["Usage: /eui send <party | raid | guild | player> [what]"] = "Brug: /eui send <party | raid | guild | player> [what]",
	["Use"] = "Brug",
	["Use %s"] = "Brug %s",
	["Use %s/eui %s on|r, %soff|r or %stoggle|r."] = "Brug %s/eui %s on|r, %soff|r eller %stoggle|r.",
	["Use EldoUI's"] = "Brug EldoUI's",
	["Use EldoUI's own frame and hide Blizzard's."] = "Brug EldoUI's egen ramme og skjul Blizzards.",
	["Use Gamepad Mode UI"] = "Brug gamepadtilstand",
	["Use general setting"] = "Brug den generelle indstilling",
	["Use it as it is"] = "Brug den som den er",
	["Use its look"] = "Brug dets udseende",
	["Use on, off or toggle after %s. Type %s for the list."] = "Brug on, off eller toggle efter %s. Skriv %s for listen.",
	["Use the best %s (Consumable Bar)"] = "Brug den bedste %s (Forbrugslinje)",
	["Use the EldoUI font for the whole game"] = "Brug EldoUI-skrifttypen i hele spillet",
	["Use the EldoUI profile as it is"] = "Brug EldoUI-profilen som den er",
	["Use the game's class colors"] = "Brug spillets klassefarver",
	["Use the Hearthstone (Consumable Bar)"] = "Brug Hearthstone (Forbrugslinje)",
	["Use the layout's spot"] = "Brug layoutets plads",
	["Use the Never show list"] = "Brug listen Vis aldrig",
	["Use the new buttons in a whisper window to invite, look up, add, or ignore the contact, or open your saved conversation."] = "Brug de nye knapper i hviskevinduet til at invitere, slå spilleren op, tilføje spilleren som ven, ignorere spilleren eller åbne jeres gemte samtale.",
	["Use the quest item (Objective Tracker)"] = "Brug questgenstanden (Questtracker)",
	["Use the rules below when your talent group or content changes."] = "Brug reglerne nedenfor når din talentgruppe eller typen af indhold skifter.",
	["Use the suggested size"] = "Brug den foreslåede størrelse",
	["Use this color preset? Colors you picked yourself on this page are replaced."] = "Vil du bruge dette farvepreset? Farver du selv har valgt på denne side, erstattes.",
	["Use this group. With no group on, every aura of the widget's kind shows."] = "Brug denne gruppe. Er ingen gruppe slået til, vises alle auraer af widgettens type.",
	["Use your execute spell"] = "Brug din execute-evne",
	["Use your mana gem (Consumable Bar)"] = "Brug din Mana Gem (Forbrugslinje)",
	["Used for highlights, the EldoUI name and cast bars. Layout presets set their own."] = "Bruges til fremhævninger, EldoUI-navnet og castbars. Layoutpresets sætter deres egen.",
	["Uses guild bank repair money when your guild allows it, then your own gold."] = "Bruger guildbankens reparationspenge når din guild tillader det, og derefter dit eget guld.",
	["Uses the skin your layout was made for (now %s). It changes with the next layout you pick."] = "Bruger det skin som dit layout er lavet til (nu %s). Det skifter med det næste layout du vælger.",
	["Uses the Unit-frame graphics row at the top of this tab."] = "Bruger rækken Unitframe-grafik øverst på denne fane.",
	["Using profile %s."] = "Bruger profilen %s.",
	["Util"] = "Util",
	["Utility cooldowns"] = "Utility-cooldowns",
	["Utility Cooldowns"] = "Utility-cooldowns",
	["Values set aside"] = "Værdier lagt til side",
	["Vanilla"] = "Vanilla",
	["Vanilla Original"] = "Vanilla Original",
	["Vanilla Original (1440p)"] = "Vanilla Original (1440p)",
	["Vanilla Refined"] = "Vanilla Refined",
	["Vanish is on this button outside Stealth."] = "Vanish ligger på denne knap uden for Stealth.",
	["Vehicle, possess and override bars (with leave button and seat indicator)"] = "Køretøjs-, kontrol- og overstyringslinjer (med forlad-knap og sædeindikator)",
	["Version %s"] = "Version %s",
	["Version %s was seen in your guild or group."] = "Version %s er set i din guild eller gruppe.",
	["Version %s, game version %s (Interface %s)."] = "Version %s, spilversion %s (Interface %s).",
	["Version check"] = "Versionstjek",
	["Very hard"] = "Meget svær",
	["Victory Rush: usable after a kill, it heals you."] = "Victory Rush: kan bruges efter et drab og heler dig.",
	["Visibility preset"] = "Synlighedspreset",
	["Visibility preset %s applied."] = "Synlighedspreset %s er anvendt.",
	["Volume channel for EldoUI's sounds (Fanfare and modules set to Default). Master plays even with game sound effects off."] = "Lydkanal for EldoUI's lyde (Fanfare og moduler sat til Standard). Master spiller også når spillets lydeffekter er slået fra.",
	["Volume panel"] = "Lydstyrkepanel",
	["W and S move forward and back, A and D strafe, and you turn with the mouse. The side buttons send the number row keys, so 1 to = on the keyboard press the same buttons."] = "W og S går frem og tilbage, A og D strafer, og du drejer med musen. Sideknapperne sender talrækkens taster, så 1 til = på tastaturet trykker de samme knapper.",
	["W and S move forward and back, A and D strafe. You turn with the right mouse button held, which frees Q and E for abilities."] = "W og S går frem og tilbage, A og D strafer. Du drejer ved at holde højre museknap nede, så Q og E bliver frie til evner.",
	["W and S move forward and back, A and D turn, Q and E strafe: the game's own movement keys."] = "W og S går frem og tilbage, A og D drejer, Q og E strafer: spillets egne bevægelsestaster.",
	["W and S move, A and D strafe, and you turn with the mouse. Bar 1: 1-5 R F E Q Z X C, bar 2: Shift + the same keys, bar 3: Ctrl + the same keys. Character moves to the comma key."] = "W og S går, A og D strafer, og du drejer med musen. Linje 1: 1-5 R F E Q Z X C, linje 2: Shift + de samme taster, linje 3: Ctrl + de samme taster. Karakterpanelet flyttes til kommatasten.",
	["W and S move, A and D turn, Q and E strafe. Bar 1: 1-5 R F G V X Z C, bar 2: Shift + the same keys, bar 3: Ctrl + the same keys. Character moves to the comma key."] = "W og S går, A og D drejer, Q og E strafer. Linje 1: 1-5 R F G V X Z C, linje 2: Shift + de samme taster, linje 3: Ctrl + de samme taster. Karakterpanelet flyttes til kommatasten.",
	["W S move, A D strafe. Bar 1: 1-5 R F E Q Z X C."] = "W S går, A D strafer. Linje 1: 1-5 R F E Q Z X C.",
	["W S move, A D turn. Bar 1: 1-5 R F G V X Z C."] = "W S går, A D drejer. Linje 1: 1-5 R F G V X Z C.",
	["waits: learn %s first"] = "venter: lær %s først",
	["waits: switch to %s and press Apply again"] = "venter: skift til %s og tryk Anvend igen",
	["Warcraft Parchment"] = "Warcraft Parchment",
	["Warlocks have no movement spell: Banish takes this key."] = "Warlocks har ingen bevægelsesevne: Banish tager denne tast.",
	["Warm dark panels in the bronze frame line of the WoW: Forever action bars and micro menu, drawn from the game's own art. The accent turns Sand when it was still the default blue."] = "Varme mørke paneler i bronzerammernes stil fra handlingslinjerne og mikromenuen i WoW: Forever, tegnet ud fra spillets egen grafik. Accenten skifter til Sand hvis den stadig var den blå standard.",
	["warning"] = "advarsel",
	["Warning"] = "Advarsel",
	["Warns you when a frame's health drops below the value you set, with a red edge, tint or glow. The game's own red screen edge is a separate setting in Options > Combat."] = "Advarer dig når en rammes liv falder under den værdi du vælger, med en rød kant, toning eller glød. Spillets egen røde skærmkant er en separat indstilling under Indstillinger > Kamp.",
	["Warriors have no ally spell."] = "Warriors har ingen evne til allierede.",
	["Warriors have no cleanse."] = "Warriors har ingen rensning.",
	["Warriors have no offensive dispel."] = "Warriors har ingen offensiv dispel.",
	["Warriors have no resurrection."] = "Warriors har ingen genoplivning.",
