	["Welcome to EldoUI"] = "Velkommen til EldoUI",
	["What"] = "Hvad",
	["What Apply changes"] = "Hvad Anvend ændrer",
	["What changed in each EldoUI version."] = "Hvad der er ændret i hver EldoUI-version.",
	["what changed in this EldoUI version"] = "hvad der er ændret i denne EldoUI-version",
	["What EldoUI found in your saved data at this login. Repaired means a small fix that loses nothing, such as a gap in a list closed up."] = "Hvad EldoUI fandt i dine gemte data ved dette login. Repareret betyder en lille rettelse hvor intet går tabt, fx et hul i en liste der er lukket.",
	["What happens on a character whose keys differ from this key set. Ask me shows one alert with a preview; Automatic sets its keys out of combat, with a backup and Undo."] = "Hvad der sker på en karakter hvis taster afviger fra dette tastesæt. Spørg mig viser én advarsel med en forhåndsvisning; Automatisk sætter tasterne uden for kamp, med en sikkerhedskopi og Fortryd.",
	["What it changes"] = "Hvad det ændrer",
	["What it is."] = "Hvad det er.",
	["What the tag string shows on your own character right now. Typing here changes nothing."] = "Hvad tagstrengen viser på din egen karakter lige nu. Det du skriver her, ændrer ingenting.",
	["What the tag string shows on your target. Target something to see it."] = "Hvad tagstrengen viser på dit mål. Vælg et mål for at se det.",
	["What this text shows. Custom tags lets you write your own, e.g. [name:short] [health:percent]; the Text tags page lists every tag."] = "Hvad denne tekst viser. Med Brugerdefinerede tags kan du skrive dine egne, fx [name:short] [health:percent]; siden Teksttags viser alle tags.",
	["What's new"] = "Nyheder",
	["Wheel step"] = "Hjultrin",
	["When a newly installed plugin has setup pages, they open once after login. Off: run them from this page."] = "Når et nyinstalleret plugin har opsætningssider, åbner de én gang efter login. Fra: kør dem fra denne side.",
	["When active"] = "Når aktiv",
	["When another addon does a job EldoUI also does, EldoUI stands back. Pick who handles each job; EldoUI never turns an addon off for you."] = "Når en anden addon dækker noget som EldoUI også gør, holder EldoUI sig tilbage. Vælg hvem der står for hver funktion; EldoUI slår aldrig en addon fra for dig.",
	["When EldoUI adds a layout to Blizzard's Edit Mode, make it the active one."] = "Gør layoutet til det aktive når EldoUI føjer et layout til Blizzards Edit Mode.",
	["When the frame is shown. Outside the rule it fades to the faded alpha. Hovering a faded frame shows it again."] = "Hvornår rammen vises. Uden for reglen toner den ud til den udtonede opacitet. Holder du musen over en udtonet ramme, vises den igen.",
	["When the frame is shown. Outside the rule it fades to the faded alpha; at 0 it is hidden for real, so it takes no clicks (When active only fades it, so it still takes clicks). Hovering shows it again."] = "Hvornår rammen vises. Uden for reglen toner den ud til den udtonede opacitet; ved 0 er den skjult for alvor, så den tager ingen klik (Når aktiv toner den kun ud, så den stadig tager klik). Holder du musen over, vises den igen.",
	["When the game notices a controller, EldoUI asks once whether to place its frames for controller play. Nothing changes until you choose."] = "Når spillet opdager en controller, spørger EldoUI én gang om rammerne skal placeres til controllerspil. Intet ændres før du vælger.",
	["When you forget a character in the Alts window, its journal is backed up first and kept here until you put it back or remove it."] = "Når du glemmer en karakter i Alts-vinduet, sikkerhedskopieres dens journal først og gemmes her indtil du lægger den tilbage eller fjerner den.",
	["Where a press starts a drag. Windows with secure parts always drag by the title bar."] = "Hvor et tryk starter et træk. Vinduer med beskyttede dele trækkes altid i titellinjen.",
	["Where every frame sits. Click a layout to preview it, then Apply or go on; Back puts your old positions back."] = "Hvor hver ramme sidder. Klik på et layout for at se et eksempel, og vælg så Anvend eller gå videre; Tilbage gendanner dine gamle placeringer.",
	["Where the game's own shortcuts are"] = "Hvor spillets egne genveje ligger",
	["Where the glow sits: under the icon's numbers and keybind, over them, or on top of everything on the frame."] = "Hvor gløden sidder: under ikonets tal og genvejstast, over dem eller øverst over alt andet på rammen.",
	["Where the Healer role puts your party and raid frames. The cast bar and the cooldown rows stay where they are."] = "Hvor rollen Healer placerer dine gruppe- og raidrammer. Castbaren og cooldownrækkerne bliver hvor de er.",
	["Which auras appear. The game does the filtering. Custom groups lets you combine up to four groups with your own spell lists and conditions."] = "Hvilke auraer der vises. Spillet står for filtreringen. Med Brugerdefinerede grupper kan du kombinere op til fire grupper med dine egne evnelister og betingelser.",
	["Which colors you mix up. Red and green kinds get blue for good and friendly; the blue kind gets green."] = "Hvilke farver du forveksler. Ved rød- og grønblindhed bliver godt og venligt blåt; ved blåblindhed bliver det grønt.",
	["Which of Blizzard's own frames and windows EldoUI may change. Anything EldoUI may not change stays exactly as Blizzard made it."] = "Hvilke af Blizzards egne rammer og vinduer EldoUI må ændre. Alt hvad EldoUI ikke må ændre, er præcis som Blizzard lavede det.",
	["which original interface textures this client ships (opens a copy box)"] = "hvilke originale grænsefladeteksturer denne klient leveres med (åbner et kopifelt)",
	["Which parts of Blizzard's UI EldoUI may change (Blizzard UI page)."] = "Hvilke dele af Blizzards UI EldoUI må ændre (siden Blizzard-UI).",
	["Which profile should the setup write into?"] = "Hvilken profil skal opsætningen skrive i?",
	["While the setup is not finished: one chat line per login and a small alert. Off: the setup no longer opens by itself; /eui install still opens it."] = "Så længe opsætningen ikke er færdig: én chatlinje pr. login og en lille advarsel. Fra: opsætningen åbner ikke længere af sig selv; /eui install åbner den stadig.",
	["While you drag a frame, lines show where its edges or center line up with another frame or the screen center."] = "Mens du trækker en ramme, viser linjer hvor dens kanter eller midte flugter med en anden ramme eller skærmens midte.",
	["While you hold the Show HUD key (Key Bindings > AddOns > EldoUI), every faded EldoUI frame shows. Works in combat. A protected frame its rule hides for real stays hidden."] = "Mens du holder tasten Vis HUD nede (Key Bindings > AddOns > EldoUI), vises alle udtonede EldoUI-rammer. Virker i kamp. En beskyttet ramme som reglen virkelig skjuler, er skjult.",
	["While you move"] = "Mens du bevæger dig",
	["Whisper"] = "Hvisk",
	["Whispers"] = "Hvisk",
	["Whispers and Battle.net whispers also get their own tab. The main window keeps them too."] = "Hvisk og Battle.net-hvisk får også deres egen fane. Hovedvinduet beholder dem også.",
	["Whispers in the chat"] = "Hvisk i chatten",
	["Whispers tab"] = "Fane til hvisk",
	["Whispers, loot and the public channels have their own tabs now, so your main chat stays readable. Right-click a tab to change or close it."] = "Hvisk, loot og de offentlige kanaler har deres egne faner nu, så din hovedchat er læsbar. Højreklik på en fane for at ændre eller lukke den.",
	["White"] = "Hvid",
	["Who uses it?"] = "Hvem bruger den?",
	["Whole screen"] = "Hele skærmen",
	["Whole screen: no limit. Centered 16:9: the width a 16:9 screen of the same height has (2560 on a 1440 px tall screen). Has no effect when the screen is not wider than the area."] = "Hele skærmen: ingen grænse. Centreret 16:9: den bredde en 16:9-skærm med samme højde har (2560 på en skærm der er 1440 px høj). Har ingen virkning når skærmen ikke er bredere end området.",
	["Whole UI"] = "Hele UI'et",
	["Wide center: cooldowns first, then resources and buffs, unit frames wide apart, side bars beside the bar stack."] = "Bred midte: cooldowns først, så ressourcer og buffs, unitframes langt fra hinanden, sidelinjer ved stakken af handlingslinjer.",
	["Widescreen Edges"] = "Widescreen Edges",
	["Widescreen Edges (1440p)"] = "Widescreen Edges (1440p)",
	["Width of"] = "Bredde som",
	["Width of the area in UI units, used with \"Custom width\". With the auto UI scale a 16:9 area is 2560 wide."] = "Områdets bredde i UI-enheder ved \"Brugerdefineret bredde\". Med den automatiske UI-skala er et 16:9-område 2560 bredt.",
	["Width of the grid lines in screen pixels."] = "Gitterlinjernes bredde i skærmpixels.",
	["Wild Berries"] = "Wild Berries",
	["Wild Thornroot"] = "Wild Thornroot",
	["Window"] = "Vindue",
	["Window look"] = "Vinduesudseende",
	["Window scale"] = "Vinduesskala",
	["Window size"] = "Vinduesstørrelse",
	["Window titles use the skin's own font (now %s). Off keeps EldoUI's title font."] = "Vinduestitler bruger skinnets egen skrifttype (nu %s). Når den er slået fra, bruges EldoUI's titelskrifttype.",
	["Window titles use the skin's own font when it has one. This skin uses EldoUI's title font."] = "Vinduestitler bruger skinnets egen skrifttype når det har en. Dette skin bruger EldoUI's titelskrifttype.",
	["Windows"] = "Vinduer",
	["Windows and toasts slide and fade in, glows move and switches change softly. Off shows every change at once and holds glows still, like Reduce motion on the Accessibility page."] = "Vinduer og pop op-beskeder glider og tones ind, glød bevæger sig, og kontakter skifter blødt. Når den er slået fra, vises alle ændringer med det samme og glød står stille, ligesom Færre bevægelser på siden Tilgængelighed.",
	["Windows are locked (/eui windows unlock)."] = "Vinduerne er låst (/eui windows unlock).", -- l10n: keep
	["Windows are locked. Unlock them to drag, scale or reset a window."] = "Vinduerne er låst. Lås dem op for at trække, skalere eller nulstille et vindue.",
	["Windows EldoUI may change: %d of %d (in your skin: %d, original: %d)."] = "Vinduer EldoUI må ændre: %d af %d (i dit skin: %d, original: %d).",
	["Windows locked."] = "Vinduer låst.",
	["windows reset"] = "vinduer nulstillet",
	["Windows unlocked."] = "Vinduer låst op.",
	["With a target"] = "Med et mål",
	["With the Vanilla Original skin, the unit frames, the action bar tray, the minimap border and the micro menu wear the game's own classic art."] = "Med skinnet Vanilla Original bærer unitframes, bakken til handlingslinjerne, minikortets kant og mikromenuen spillets egen klassiske grafik.",
	["Works in combat; needs a reagent."] = "Virker i kamp; kræver et reagens.",
	["World and NPCs"] = "Verden og NPC'er",
	["World and Travel"] = "Verden og rejser",
	["World map and quest log"] = "Verdenskort og questlog",
	["Worn gear at"] = "Slidt udstyr ved",
	["would go on this empty button (check the box below)"] = "ville komme på denne tomme knap (sæt flueben i feltet nedenfor)",
	["WoW Forever"] = "WoW Forever",
	["Wowhead links"] = "Wowhead-links",
	["Write a quick journal note"] = "Skriv en hurtig journalnote",
	["Writes the layout's spot into %s's own settings, so it stays there without EldoUI too. You see every value first; Undo puts them back."] = "Skriver layoutets plads ind i de egne indstillinger for %s, så den også bliver der uden EldoUI. Du ser alle værdier først; Fortryd sætter dem tilbage.",
	["Writes this font into every module below that offers it."] = "Skriver denne skrifttype ind i alle moduler herunder der tilbyder den.",
	["Writes this texture into every module below that offers it."] = "Skriver denne tekstur ind i alle moduler herunder der tilbyder den.",
	["X"] = "X",
	["XP Bar"] = "XP-bjælke",
	["XP, reputation and honor bars"] = "XP-, omdømme- og ærebjælker",
	["Y"] = "Y",
	["Yes"] = "Ja",
	["Yes: only auras you or your pet applied. No: only other people's."] = "Ja: kun auraer som du eller dit pet har lagt på. Nej: kun andres.",
	["You already use %s."] = "Du bruger allerede %s.",
	["you are in combat"] = "du er i kamp",
	["You are not in a group."] = "Du er ikke i en gruppe.",
	["You are not in a guild."] = "Du er ikke i en guild.",
	["You are not in a raid."] = "Du er ikke i et raid.",
	["You are playing with a controller. EldoUI can place its frames for controller play: centered above the game's gamepad bar and clear of its radial menu. Your normal layout and dragged frames stay saved, and everything goes back when the game's gamepad interface is turned off."] = "Du spiller med en controller. EldoUI kan placere sine rammer til controllerspil: centreret over spillets gamepadlinje og fri af dens radialmenu. Dit normale layout og dine flyttede rammer bliver gemt, og alt vender tilbage når spillets gamepadinterface slås fra.",
	["You are stunned, feared, rooted or silenced (the game's loss of control alert)."] = "Du er stunnet, feared, rooted eller silenced (spillets advarsel om kontroltab).",
	["You can apply it"] = "Du kan lægge den på",
	["You die"] = "Du dør",
	["You enter combat: something attacks you, or you attack."] = "Du går i kamp: noget angriber dig, eller du angriber.",
	["You have a controller. EldoUI can place its frames for controller play while the game's gamepad interface is on: centered above the game's gamepad bar and clear of its radial menu."] = "Du har en controller. EldoUI kan placere sine rammer til controllerspil mens spillets gamepadinterface er slået til: centreret over spillets gamepadlinje og fri af dens radialmenu.",
	["You manage your own keys"] = "Du styrer dine egne taster",
	["You manage your own keys, so EldoUI writes no key. Untick \"I manage my own keys\" on the Keybinds page to use a key set."] = "Du styrer dine egne taster, så EldoUI skriver ingen tast. Fjern fluebenet ved \"Jeg styrer mine egne taster\" på siden Genvejstaster for at bruge et tastesæt.",
	["You manage your own keys: EldoUI leaves them as they are."] = "Du styrer dine egne taster: EldoUI lader dem være som de er.",
	["You manage your own keys: no key changes, and EldoUI never offers keys on your other characters."] = "Du styrer dine egne taster: ingen taster ændres, og EldoUI tilbyder aldrig taster på dine andre karakterer.",
	["you moved it; picking a layout again puts it back"] = "du har flyttet den; vælg et layout igen for at sætte den tilbage",
	["You picked EldoUI over %s, but %s is still on, so EldoUI stands back. Type %s to choose."] = "Du valgte EldoUI frem for %s, men %s er stadig slået til, så EldoUI træder til side. Skriv %s for at vælge.",
	["You picked EldoUI over %s, but it is still on, so EldoUI stands back. Choose again, or turn it off in the addon list."] = "Du valgte EldoUI frem for %s, men den er stadig slået til, så EldoUI træder til side. Vælg igen, eller slå den fra i addonlisten.",
	["You picked EldoUI, but %s is still on."] = "Du valgte EldoUI, men %s er stadig slået til.",
	["You ran the setup on this character before. Every step starts on \"keep\", so clicking through changes nothing, and EldoUI asks before it changes your profile."] = "Du har kørt opsætningen på denne karakter før. Alle trin starter på \"behold\", så det ændrer intet at klikke sig igennem, og EldoUI spørger før den ændrer din profil.",
	["You set up EldoUI on this character before. Each step you apply now overwrites that part of your profile %s. A backup is kept: the Welcome step can undo it. Continue?"] = "Du har sat EldoUI op på denne karakter før. Hvert trin du anvender nu, overskriver den del af din profil %s. Der gemmes en sikkerhedskopi: trinnet Velkommen kan fortryde det. Vil du fortsætte?",
	["You use the %s layout. Apply it again?"] = "Du bruger layoutet %s. Vil du anvende det igen?",
	["Your addons"] = "Dine addons",
	["Your addons: no addon is turned off"] = "Dine addons: ingen addon slås fra",
	["Your armor, aura, shield or group buff."] = "Din rustning, din aura, dit skjold eller din gruppebuff.",
	["Your bars changed since the preview. Look at the preview again before you apply."] = "Dine linjer er ændret siden forhåndsvisningen. Se forhåndsvisningen igen før du anvender ændringerne.",
	["Your between-pulls bar: buffs, travel and resurrection. Point at it out of combat to use it; Ctrl and your keys work any time."] = "Din linje til mellem pulls: buffs, rejse og genoplivning. Peg på den uden for kamp for at bruge den; Ctrl og dine taster virker altid.",
	["Your between-pulls bar: buffs, travel and resurrection. Point at it out of combat to use it; its keys work any time."] = "Din linje til mellem pulls: buffs, rejse og genoplivning. Peg på den uden for kamp for at bruge den; dens taster virker altid.",
	["Your character dies."] = "Din karakter dør.",
	["Your chat windows for this character: EldoUI's tabs, a font size and class-colored names. The look of the chat panel itself is on the Styles step."] = "Dine chatvinduer for denne karakter: EldoUI's faner, en skriftstørrelse og klassefarvede navne. Udseendet af selve chatpanelet ligger i trinnet Stile.",
	["Your choice."] = "Dit valg.",
	["Your class has no class details to add."] = "Din klasse har ingen klassedetaljer at tilføje.",
	["Your class has nothing to add."] = "Din klasse har intet at tilføje.",
	["Your class setup also places %s; give them a free button."] = "Din klasseopsætning placerer også %s; giv dem en ledig knap.",
	["Your class setup's character macros, each under its own name. A macro you already have by that name is never changed."] = "Karaktermakroerne fra din klasseopsætning, hver under sit eget navn. En makro du allerede har med det navn, ændres aldrig.",
	["Your class spells on the game's controller bars, in the order of your key set: the fight's spells on page 1 and the spells between pulls on page 2. Each button shows its category, as on the keyboard. Nothing changes until you press Apply."] = "Dine klasseevner på spillets controllerlinjer, i dit tastesæts rækkefølge: kampens evner på side 1 og evnerne mellem kampene på side 2. Hver knap viser sin kategori ligesom på tastaturet. Intet ændres før du trykker Anvend.",
	["Your class's bars, totems, reminders and macros in one step."] = "Din klasses linjer, totems, påmindelser og makroer i ét trin.",
	["Your current settings for this part are replaced."] = "Dine nuværende indstillinger for denne del bliver erstattet.",
	["Your EldoUI settings were saved by a newer version of EldoUI. They are kept exactly as they are, including what this version doesn't know."] = "Dine EldoUI-indstillinger blev gemt af en nyere version af EldoUI. De beholdes præcis som de er, også det som denne version ikke kender.",
	["Your EldoUI settings were updated for this version. Nothing was removed, and %d saved values EldoUI could not read are set aside. Type /eui data to see them."] = { one = "Dine EldoUI-indstillinger er opdateret til denne version. Intet blev fjernet, og %d gemt værdi som EldoUI ikke kunne læse, er lagt til side. Skriv /eui data for at se den.", other = "Dine EldoUI-indstillinger er opdateret til denne version. Intet blev fjernet, og %d gemte værdier som EldoUI ikke kunne læse, er lagt til side. Skriv /eui data for at se dem." },
	["Your EldoUI settings were updated for this version. Nothing was removed, and a copy from before the update is kept: type /eui data to see it."] = "Dine EldoUI-indstillinger er opdateret til denne version. Intet blev fjernet, og en kopi fra før opdateringen er gemt: skriv /eui data for at se den.",
	["Your EldoUI settings were updated for this version. Nothing was removed."] = "Dine EldoUI-indstillinger er opdateret til denne version. Intet blev fjernet.",
	["Your EldoUI settings were updated for this version. Nothing was removed: a copy from before the update is kept, and %d saved values EldoUI could not read are set aside. Type /eui data to see them."] = { one = "Dine EldoUI-indstillinger er opdateret til denne version. Intet blev fjernet: en kopi fra før opdateringen er gemt, og %d gemt værdi som EldoUI ikke kunne læse, er lagt til side. Skriv /eui data for at se den.", other = "Dine EldoUI-indstillinger er opdateret til denne version. Intet blev fjernet: en kopi fra før opdateringen er gemt, og %d gemte værdier som EldoUI ikke kunne læse, er lagt til side. Skriv /eui data for at se dem." },
	["Your EldoUI setup"] = "Din EldoUI-opsætning",
	["Your experience toward the next level in percent (45%). Empty at max level."] = "Din erfaring mod næste level i procent (45%). Tomt ved max level.",
	["Your faction's materials in one shared frame."] = "Din fraktions materialer i én fælles ramme.",
	["Your Felhunter's Devour Magic is on the pet bar."] = "Din Felhunters Devour Magic ligger på petlinjen.",
	["Your frames go back to your normal layout. The Layouts page turns Gamepad Mode UI on again."] = "Dine rammer vender tilbage til dit normale layout. På siden Layouts kan du slå gamepadtilstand til igen.",
	["Your frames move for controller play whenever the game's gamepad interface is on."] = "Dine rammer flyttes til controllerspil når spillets gamepadinterface er slået til.",
	["Your hand rests one key to the right: E and D move, S and F strafe, and you turn with the mouse. Bar 1: R T G W 2 Q A V C X Z 4, bar 2: Shift + the same keys, bar 3: Ctrl + the same keys."] = "Din hånd hviler én tast til højre: E og D går, S og F strafer, og du drejer med musen. Linje 1: R T G W 2 Q A V C X Z 4, linje 2: Shift + de samme taster, linje 3: Ctrl + de samme taster.",
	["Your health and power as two liquid orbs at the ends of the action bars, with your target centered above the bars."] = "Dit liv og din ressource som to kugler af væske for enderne af handlingslinjerne, med dit mål centreret over linjerne.",
	["Your hunter pet's happiness as the game names it."] = "Dit Hunter-pets tilfredshed, sådan som spillet kalder den.",
	["Your hunter pet's loyalty level."] = "Dit Hunter-pets loyalitetslevel.",
	["Your incoming heals"] = "Dine indkommende heals",
	["Your journal is back as it was before the update. Your journal as it was a moment ago is kept as a backup in My Adventure."] = "Din journal er tilbage som før opdateringen. Din journal som den var for et øjeblik siden, gemmes som en sikkerhedskopi i My Adventure.",
	["Your key set now belongs to your profile and knows US, UK, Nordic, German and French keyboards, and new spells land on their own key on bars 1 to 3."] = "Dit tastesæt hører nu til din profil og kender US-, UK-, nordiske, tyske og franske tastaturer, og nye evner får deres egen tast på linje 1 til 3.",
	["Your key set: the keys of bars 1 to 3 and the class spells on them."] = "Dit tastesæt: tasterne på linje 1 til 3 og klasseevnerne på dem.",
	["Your keyboard: %s. The key sets use its keys from now on."] = "Dit tastatur: %s. Tastesættene bruger dets taster fra nu af.",
	["Your keys and spells change when combat ends."] = "Dine taster og evner ændres når kampen slutter.",
	["Your keys are saved for all your characters."] = "Dine taster er gemt for alle dine karakterer.",
	["Your keys are saved for this character only."] = "Dine taster er kun gemt for denne karakter.",
	["Your keys are set"] = "Dine taster er sat",
	["Your keys are shared by your account, so this changes the keys of all your characters. The copy for Undo is kept on this character."] = "Dine taster deles af hele kontoen, så dette ændrer tasterne på alle dine karakterer. Kopien til Fortryd gemmes på denne karakter.",
	["Your keys changed since the preview. Look at the preview again before you apply."] = "Dine taster er ændret siden forhåndsvisningen. Se forhåndsvisningen igen før du trykker på Anvend.",
	["Your keys or action buttons changed since the preview. Look at the preview again before you apply."] = "Dine taster eller handlingsknapper er ændret siden forhåndsvisningen. Se forhåndsvisningen igen før du trykker på Anvend.",
	["Your known class spells go on the empty buttons of their category on bars 1 to 3. A button with your own action keeps it, and a spell already on your bars is not moved."] = "Dine kendte klasseevner kommer på de tomme knapper i deres kategori på linje 1 til 3. En knap du selv har lagt noget på, beholder det, og en evne der allerede er på dine handlingslinjer, flyttes ikke.",
	["Your layout %s is not installed. Your frames use the %s layout until you pick one; your own positions are kept."] = "Dit layout %s er ikke installeret. Dine rammer bruger layoutet %s indtil du vælger et; dine egne placeringer beholdes.",
	["Your layout asks for: %s."] = "Dit layout ønsker: %s.",
	["Your layout places and sizes these addons out of combat. Their frames follow when you change layouts."] = "Dit layout placerer og skalerer disse addons uden for kamp. Rammerne følger med når du skifter layout.",
	["Your layout, skin and styles stay as they are."] = "Dit layout, dit skin og dine stile røres ikke.",
	["Your main chat sits in EldoUI's chat panel and stays there after Edit Mode changes."] = "Din hovedchat sidder i EldoUI's chatpanel og bliver der efter ændringer i Edit Mode.",
	["Your main chat stays where the game puts it. The Blizzard UI step can let EldoUI move it into EldoUI's chat panel."] = "Din hovedchat bliver hvor spillet placerer den. Trinnet Blizzard-UI kan lade EldoUI flytte den ind i EldoUI's chatpanel.",
	["Your main damage or healing cooldown."] = "Din primære skade- eller healingcooldown.",
	["Your main damage or healing spells for your role, in the order you press them most."] = "Dine primære skade- eller healingevner til din rolle, i den rækkefølge du oftest trykker på dem.",
	["Your modules already match %s."] = "Dine moduler matcher allerede %s.",
	["Your movement keys stay as they are. The keys 7 to = sit farther from your movement hand."] = "Dine bevægelsestaster røres ikke. Tasterne 7 til = sidder længere fra din bevægelseshånd.",
	["Your normal layout and dragged frames stay saved and come back when the game's gamepad interface is off. EldoUI never turns the game's gamepad interface on or off: that switch is in the game's Controller settings. Change this later in /eui > Layouts > Gamepad Mode UI."] = "Dit normale layout og dine flyttede rammer bliver gemt og kommer tilbage når spillets gamepadinterface er slået fra. EldoUI slår aldrig spillets gamepadinterface til eller fra: den indstilling findes i spillets controllerindstillinger. Skift det senere i /eui > Layouts > Gamepadtilstand.",
	["Your other characters"] = "Dine andre karakterer",
	["Your own actions stay where they are: %s."] = "Dine egne handlinger bliver hvor de er: %s.",
	["Your own key map"] = "Dit eget tastekort",
	["Your own keys"] = "Dine egne taster",
	["your own keys"] = "dine egne taster",
	["Your own mix"] = "Din egen blanding",
	["Your own pick for Bear Form."] = "Dit eget valg til Bear Form.",
	["Your own pick for Berserker Stance."] = "Dit eget valg til Berserker Stance.",
	["Your own pick for between pulls."] = "Dit eget valg til mellem pulls.",
	["Your own pick, such as a mount (the Consumable Bar can show yours too)."] = "Dit eget valg, fx en mount (Forbrugslinjen kan også vise din).",
	["Your own pick, such as a mount; teleports and portals are in the travel menu."] = "Dit eget valg, fx en mount; teleports og portaler ligger i rejsemenuen.",
	["Your own pick."] = "Dit eget valg.",
	["Your own pick: totems sit on the totem bar."] = "Dit eget valg: totems sidder på totemlinjen.",
	["Your own tag string, used when the text is set to Custom tags. Example: [classcolor][name:medium][close] [level]"] = "Din egen tagstreng. Den bruges når teksten er sat til Brugerdefinerede tags. Eksempel: [classcolor][name:medium][close] [level]",
	["Your potion, healthstone and mana potion or bandage on a small bar, each used by one key of bar 3."] = "Din potion, healthstone og mana potion eller bandage på en lille linje, hver brugt med én tast på linje 3.",
	["Your profile %s now holds a copy of another profile."] = "Din profil %s indeholder nu en kopi af en anden profil.",
	["Your profile %s now uses the layout %s from %s: %s."] = "Din profil %s bruger nu layoutet %s fra %s: %s.",
	["Your profile %s was reset to its defaults."] = "Din profil %s blev nulstillet til standard.",
	["Your profile keeps its own look. Use %s's look (art, windows, styles)?"] = "Din profil beholder sit eget udseende. Vil du bruge udseendet fra %s (grafik, vinduer, stile)?",
	["Your profile uses %s, and %s on this character differ from it. Look at the keys before anything changes."] = "Din profil bruger %s, og %s på denne karakter afviger fra det. Se tasterne før noget ændres.",
	["Your profile uses %s, so this character got its keys: %s. Keys you set yourself stayed."] = "Din profil bruger %s, så denne karakter har fået dets taster: %s. Taster du selv har sat, er blevet.",
	["Your rested experience, shortened. Empty when you are not rested or at max level."] = "Din udhvilede erfaring, forkortet. Tomt når du ikke er udhvilet eller er på max level.",
	["Your role and class: a small layer over the layout, and click-cast setup for healers."] = "Din rolle og klasse: et lille lag over layoutet og opsætning af klikkast til healere.",
	["Your role has no class spell here."] = "Din rolle har ingen klasseevne her.",
	["Your role is now %s. %s of this role can go on your bars: on empty buttons, and on buttons where EldoUI put a spell of your old role. Your own actions stay."] = "Din rolle er nu %s. %s til denne rolle kan komme på dine handlingslinjer: på tomme knapper og på knapper hvor EldoUI har sat en evne til din gamle rolle. Dine egne handlinger bliver.",
	["Your safety net: copies kept before each update, values set aside instead of deleted, and what EldoUI checked at this login."] = "Dit sikkerhedsnet: kopier der gemmes før hver opdatering, værdier der lægges til side i stedet for at blive slettet, og hvad EldoUI tjekkede ved dette login.",
	["Your screen is %s. EldoUI is made for 1440p, so Auto draws every screen as the 2560x1440 canvas (%s), a little taller on a screen narrower than 16:9: every layout looks exactly as designed, smaller on a smaller screen and bigger on a bigger one."] = "Din skærm er %s. EldoUI er lavet til 1440p, så Auto tegner alle skærme som 2560x1440-lærredet (%s), lidt højere på en skærm der er smallere end 16:9: alle layouts ser ud præcis som designet, mindre på en mindre skærm og større på en større.",
	["Your settings, layout, dragged frames and journal carry over to this version, and a copy is kept first that the new Saved data page can put back."] = "Dine indstillinger, dit layout, dine flyttede rammer og din journal overføres til denne version, og først gemmes en kopi der kan sættes tilbage fra den nye side Gemte data.",
	["Your setup"] = "Din opsætning",
	["Your skin keeps its own background: tints color the flat skins (Modern, Minimal Modern, Blizzard and WoW Forever)."] = "Dit skin beholder sin egen baggrund: toninger farver de flade skins (Modern, Minimal Modern, Blizzard og WoW Forever).",
	["Your text style hides the keys on the action buttons. This shows them on bars 1 to 3 only, so you can see the keys you set; the other bars keep the style."] = "Din tekststil skjuler tasterne på handlingsknapperne. Dette viser dem kun på linje 1 til 3, så du kan se de taster du sætter; de andre linjer beholder stilen.",
	["Your threat state on this unit (no numbers)."] = "Din aggrotilstand på denne enhed (ingen tal).",
	["Your totems protect the group: the totem bar."] = "Dine totems beskytter gruppen: totemlinjen.",
	["Your UI is ready"] = "Din UI er klar",
	["Your weapon poison (an item)."] = "Din våbengift (en genstand).",
	["Your whole look in one place: a complete look, its layout, the UI amount and Blizzard's windows, applied together."] = "Hele dit udseende samlet ét sted: et komplet udseende, dets layout, UI-mængden og Blizzards vinduer, anvendt sammen.",
	["Your windows stay. The tabs checked below get their own window, docked next to the main chat."] = "Dine vinduer bliver. Fanerne der er afkrydset herunder, får deres eget vindue, dokket ved siden af hovedchatten.",
	["Zone ability"] = "Zoneevne",
	["Zone and subzone text"] = "Zone- og underzonetekst",
	["Zone: %s"] = "Zone: %s",
	["zzz while you rest in an inn or city (your own frame only)."] = "zzz mens du hviler på en kro eller i en by (kun din egen ramme).",
} end)
